package solution

import (
	"fmt"
	"strings"
)

// ParseError reports a parse failure at a 1-based line number.
type ParseError struct {
	Line int
}

func (e *ParseError) Error() string {
	return fmt.Sprintf("csv parse error on line %d", e.Line)
}

// Parse parses s as strict CSV and returns its records.
func Parse(s string) ([][]string, error) {
	n := len(s)
	if n == 0 {
		return nil, nil
	}

	var records [][]string
	i := 0
	line := 1

	for {
		var record []string
		recordDone := false

		for !recordDone {
			var field string

			if i < n && s[i] == '"' {
				// Quoted field.
				openLine := line
				i++
				var b strings.Builder
				closed := false
				for i < n {
					c := s[i]
					if c == '"' {
						if i+1 < n && s[i+1] == '"' {
							b.WriteByte('"')
							i += 2
							continue
						}
						i++
						closed = true
						break
					}
					if c == '\n' {
						line++
					}
					b.WriteByte(c)
					i++
				}
				if !closed {
					return nil, &ParseError{Line: openLine}
				}
				field = b.String()

				// Check what follows the closing quote.
				if i >= n {
					record = append(record, field)
					recordDone = true
				} else if s[i] == ',' {
					i++
					record = append(record, field)
				} else if s[i] == '\n' {
					i++
					line++
					record = append(record, field)
					recordDone = true
				} else if s[i] == '\r' && i+1 < n && s[i+1] == '\n' {
					i += 2
					line++
					record = append(record, field)
					recordDone = true
				} else {
					return nil, &ParseError{Line: line}
				}
			} else {
				// Unquoted field.
				start := i
				for i < n {
					c := s[i]
					if c == ',' || c == '\n' {
						break
					}
					if c == '\r' && i+1 < n && s[i+1] == '\n' {
						break
					}
					if c == '"' {
						return nil, &ParseError{Line: line}
					}
					i++
				}
				field = s[start:i]
				record = append(record, field)

				if i >= n {
					recordDone = true
				} else if s[i] == ',' {
					i++
				} else if s[i] == '\n' {
					i++
					line++
					recordDone = true
				} else {
					// "\r\n"
					i += 2
					line++
					recordDone = true
				}
			}
		}

		records = append(records, record)
		if i >= n {
			break
		}
	}

	return records, nil
}
