```go
package solution

import (
	"errors"
	"math"
)

type tokKind int

const (
	tNum tokKind = iota
	tOp
	tEOF
)

type token struct {
	kind tokKind
	op   byte
	val  float64
}

func tokenize(s string) ([]token, error) {
	var toks []token
	i := 0
	n := len(s)
	for i < n {
		c := s[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			i++
		case c == '+' || c == '-' || c == '*' || c == '/' || c == '^' || c == '(' || c == ')':
			toks = append(toks, token{kind: tOp, op: c})
			i++
		case (c >= '0' && c <= '9') || c == '.':
			start := i
			intDigits := 0
			for i < n && s[i] >= '0' && s[i] <= '9' {
				i++
				intDigits++
			}
			var v float64
			for k := start; k < start+intDigits; k++ {
				v = v*10 + float64(s[k]-'0')
			}
			fracDigits := 0
			if i < n && s[i] == '.' {
				i++
				fstart := i
				for i < n && s[i] >= '0' && s[i] <= '9' {
					i++
					fracDigits++
				}
				if fracDigits > 0 {
					// Compute fraction precisely by parsing whole mantissa.
					v = parseDecimal(s[start:start+intDigits], s[fstart:fstart+fracDigits])
				}
			}
			if intDigits == 0 && fracDigits == 0 {
				return nil, errors.New("invalid number")
			}
			toks = append(toks, token{kind: tNum, val: v})
		default:
			return nil, errors.New("invalid character")
		}
	}
	toks = append(toks, token{kind: tEOF})
	return toks, nil
}

func parseDecimal(intPart, fracPart string) float64 {
	var v float64
	for i := 0; i < len(intPart); i++ {
		v = v*10 + float64(intPart[i]-'0')
	}
	var f float64
	for i := 0; i < len(fracPart); i++ {
		f = f*10 + float64(fracPart[i]-'0')
	}
	if len(fracPart) > 0 {
		f /= math.Pow(10, float64(len(fracPart)))
	}
	return v + f
}

type parser struct {
	toks []token
	pos  int
}

func (p *parser) peek() token { return p.toks[p.pos] }

func (p *parser) isOp(c byte) bool {
	t := p.toks[p.pos]
	return t.kind == tOp && t.op == c
}

func (p *parser) expr() (float64, error) {
	left, err := p.term()
	if err != nil {
		return 0, err
	}
	for p.isOp('+') || p.isOp('-') {
		op := p.peek().op
		p.pos++
		right, err := p.term()
		if err != nil {
			return 0, err
		}
		if op == '+' {
			left += right
		} else {
			left -= right
		}
	}
	return left, nil
}

func (p *parser) term() (float64, error) {
	left, err := p.unary()
	if err != nil {
		return 0, err
	}
	for p.isOp('*') || p.isOp('/') {
		op := p.peek().op
		p.pos++
		right, err := p.unary()
		if err != nil {
			return 0, err
		}
		if op == '*' {
			left *= right
		} else {
			if right == 0 {
				return 0, errors.New("division by zero")
			}
			left /= right
		}
	}
	return left, nil
}

func (p *parser) unary() (float64, error) {
	if p.isOp('+') {
		p.pos++
		return p.unary()
	}
	if p.isOp('-') {
		p.pos++
		v, err := p.unary()
		if err != nil {
			return 0, err
		}
		return -v, nil
	}
	return p.power()
}

func (p *parser) power() (float64, error) {
	base, err := p.primary()
	if err != nil {
		return 0, err
	}
	if p.isOp('^') {
		p.pos++
		exp, err := p.unary()
		if err != nil {
			return 0, err
		}
		return math.Pow(base, exp), nil
	}
	return base, nil
}

func (p *parser) primary() (float64, error) {
	t := p.peek()
	if t.kind == tNum {
		p.pos++
		return t.val, nil
	}
	if p.isOp('(') {
		p.pos++
		v, err := p.expr()
		if err != nil {
			return 0, err
		}
		if !p.isOp(')') {
			return 0, errors.New("expected )")
		}
		p.pos++
		return v, nil
	}
	return 0, errors.New("unexpected token")
}

// Eval parses and evaluates an arithmetic expression.
func Eval(s string) (float64, error) {
	toks, err := tokenize(s)
	if err != nil {
		return 0, err
	}
	p := &parser{toks: toks}
	v, err := p.expr()
	if err != nil {
		return 0, err
	}
	if p.peek().kind != tEOF {
		return 0, errors.New("unexpected trailing input")
	}
	return v, nil
}
