package solution

import "errors"

var errInvalidDate = errors.New("invalid date")

// parseDate validates a strict YYYY-MM-DD string and returns its day number
// (days since 1970-01-01 in the proleptic Gregorian calendar).
func parseDate(s string) (int64, error) {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return 0, errInvalidDate
	}
	for i := 0; i < 10; i++ {
		if i == 4 || i == 7 {
			continue
		}
		if s[i] < '0' || s[i] > '9' {
			return 0, errInvalidDate
		}
	}
	y := int64(s[0]-'0')*1000 + int64(s[1]-'0')*100 + int64(s[2]-'0')*10 + int64(s[3]-'0')
	m := int64(s[5]-'0')*10 + int64(s[6]-'0')
	d := int64(s[8]-'0')*10 + int64(s[9]-'0')
	if m < 1 || m > 12 || d < 1 {
		return 0, errInvalidDate
	}
	if d > daysInMonth(y, m) {
		return 0, errInvalidDate
	}
	return daysFromCivil(y, m, d), nil
}

func isLeap(y int64) bool {
	return (y%4 == 0 && y%100 != 0) || y%400 == 0
}

func daysInMonth(y, m int64) int64 {
	switch m {
	case 1, 3, 5, 7, 8, 10, 12:
		return 31
	case 4, 6, 9, 11:
		return 30
	default:
		if isLeap(y) {
			return 29
		}
		return 28
	}
}

func floorDiv(a, b int64) int64 {
	q := a / b
	if (a%b != 0) && ((a < 0) != (b < 0)) {
		q--
	}
	return q
}

// daysFromCivil returns days since 1970-01-01 (Howard Hinnant's algorithm).
func daysFromCivil(y, m, d int64) int64 {
	if m <= 2 {
		y--
	}
	era := floorDiv(y, 400)
	yoe := y - era*400
	var mp int64
	if m > 2 {
		mp = m - 3
	} else {
		mp = m + 9
	}
	doy := (153*mp+2)/5 + d - 1
	doe := yoe*365 + yoe/4 - yoe/100 + doy
	return era*146097 + doe - 719468
}

// weekday returns 0 for Monday ... 6 for Sunday.
func weekday(z int64) int64 {
	// 1970-01-01 (z=0) was a Thursday (index 3).
	w := (z + 3) % 7
	if w < 0 {
		w += 7
	}
	return w
}

// prefix returns a function g such that g(b)-g(a) is the number of
// Monday–Friday days in [a, b).
func prefix(n int64) int64 {
	const monday int64 = 4 // 1970-01-05 is a Monday
	k := n - monday
	q := floorDiv(k, 7)
	r := k - 7*q
	if r > 5 {
		r = 5
	}
	return 5*q + r
}

func Count(from, to string, holidays []string) (int, error) {
	a, err := parseDate(from)
	if err != nil {
		return 0, err
	}
	b, err := parseDate(to)
	if err != nil {
		return 0, err
	}
	hdays := make([]int64, 0, len(holidays))
	for _, h := range holidays {
		hd, err := parseDate(h)
		if err != nil {
			return 0, err
		}
		hdays = append(hdays, hd)
	}

	sign := int64(1)
	if b < a {
		a, b = b, a
		sign = -1
	}

	total := prefix(b) - prefix(a)

	seen := make(map[int64]struct{}, len(hdays))
	for _, hd := range hdays {
		if _, ok := seen[hd]; ok {
			continue
		}
		seen[hd] = struct{}{}
		if hd >= a && hd < b && weekday(hd) < 5 {
			total--
		}
	}

	return int(sign * total), nil
}
