package solution

import "sort"

// Set is a set of integers stored as sorted, disjoint, maximally merged
// half-open intervals. The zero value is an empty set ready to use.
type Set struct {
	iv [][2]int
}

// replace swaps s.iv[i:j] for repl.
func (s *Set) replace(i, j int, repl [][2]int) {
	tail := len(s.iv) - j
	newLen := i + len(repl) + tail
	out := make([][2]int, newLen)
	copy(out, s.iv[:i])
	copy(out[i:], repl)
	copy(out[i+len(repl):], s.iv[j:])
	s.iv = out
}

// Add adds every integer in [lo, hi) to the set.
func (s *Set) Add(lo, hi int) {
	if lo >= hi {
		return
	}
	n := len(s.iv)
	// First interval that touches or overlaps [lo, hi) from the left.
	i := sort.Search(n, func(k int) bool { return s.iv[k][1] >= lo })
	// First interval strictly after [lo, hi) (not touching).
	j := sort.Search(n, func(k int) bool { return s.iv[k][0] > hi })
	newLo, newHi := lo, hi
	if i < j {
		if s.iv[i][0] < newLo {
			newLo = s.iv[i][0]
		}
		if s.iv[j-1][1] > newHi {
			newHi = s.iv[j-1][1]
		}
	}
	s.replace(i, j, [][2]int{{newLo, newHi}})
}

// Remove removes every integer in [lo, hi) from the set.
func (s *Set) Remove(lo, hi int) {
	if lo >= hi {
		return
	}
	n := len(s.iv)
	// First interval that overlaps [lo, hi).
	i := sort.Search(n, func(k int) bool { return s.iv[k][1] > lo })
	// First interval entirely at or after hi.
	j := sort.Search(n, func(k int) bool { return s.iv[k][0] >= hi })
	if i >= j {
		return
	}
	var repl [][2]int
	if s.iv[i][0] < lo {
		repl = append(repl, [2]int{s.iv[i][0], lo})
	}
	if s.iv[j-1][1] > hi {
		repl = append(repl, [2]int{hi, s.iv[j-1][1]})
	}
	s.replace(i, j, repl)
}

// Contains reports whether x is in the set.
func (s *Set) Contains(x int) bool {
	n := len(s.iv)
	k := sort.Search(n, func(k int) bool { return s.iv[k][1] > x })
	return k < n && s.iv[k][0] <= x
}

// Intervals returns a fresh copy of the canonical interval list.
func (s *Set) Intervals() [][2]int {
	out := make([][2]int, len(s.iv))
	copy(out, s.iv)
	return out
}
