package solution

import (
	"container/list"
	"time"
)

type entry struct {
	key    string
	value  string
	expiry time.Time
}

// Cache is an LRU cache with per-entry TTL and an injected clock.
// It is not safe for concurrent use.
type Cache struct {
	capacity int
	ttl      time.Duration
	now      func() time.Time
	ll       *list.List // front = LRU, back = MRU
	items    map[string]*list.Element
}

// New creates a cache with the given capacity, TTL and clock.
func New(capacity int, ttl time.Duration, now func() time.Time) *Cache {
	return &Cache{
		capacity: capacity,
		ttl:      ttl,
		now:      now,
		ll:       list.New(),
		items:    make(map[string]*list.Element, capacity),
	}
}

func expired(e *entry, t time.Time) bool {
	return !t.Before(e.expiry)
}

func (c *Cache) remove(el *list.Element) {
	e := el.Value.(*entry)
	delete(c.items, e.key)
	c.ll.Remove(el)
}

// Get returns the value for k if it has a live entry and marks it MRU.
func (c *Cache) Get(k string) (string, bool) {
	el, ok := c.items[k]
	if !ok {
		return "", false
	}
	t := c.now()
	e := el.Value.(*entry)
	if expired(e, t) {
		c.remove(el)
		return "", false
	}
	c.ll.MoveToBack(el)
	return e.value, true
}

// Put inserts or updates k with value v.
func (c *Cache) Put(k, v string) {
	t := c.now()
	if el, ok := c.items[k]; ok {
		e := el.Value.(*entry)
		if !expired(e, t) {
			e.value = v
			e.expiry = t.Add(c.ttl)
			c.ll.MoveToBack(el)
			return
		}
		c.remove(el)
	}

	if c.ll.Len() >= c.capacity {
		for el := c.ll.Front(); el != nil; {
			next := el.Next()
			if expired(el.Value.(*entry), t) {
				c.remove(el)
			}
			el = next
		}
		for c.ll.Len() >= c.capacity {
			c.remove(c.ll.Front())
		}
	}

	e := &entry{key: k, value: v, expiry: t.Add(c.ttl)}
	c.items[k] = c.ll.PushBack(e)
}

// Len returns the number of live entries at the current time.
func (c *Cache) Len() int {
	t := c.now()
	n := 0
	for el := c.ll.Front(); el != nil; el = el.Next() {
		if !expired(el.Value.(*entry), t) {
			n++
		}
	}
	return n
}
