```go
package solution

import (
	"strconv"
	"strings"
)

type ParseError struct {
	Line int
}

func (e *ParseError) Error() string {
	return "csv: parse error on line " + strconv.Itoa(e.Line)
}

func Parse(s string) ([][]string, error) {
	if len(s) == 0 {
		return nil, nil
	}

	var records [][]string
	i := 0
	line := 1

	for i < len(s) {
		var record []string
		for {
			var field string
			if i < len(s) && s[i] == '"' {
				startLine := line
				i++ // consume opening '"'
				contentStart := i
				var b strings.Builder
				hasEscaped := false
				closed := false

				for i < len(s) {
					c := s[i]
					if c == '"' {
						if i+1 < len(s) && s[i+1] == '"' {
							if !hasEscaped {
								b.WriteString(s[contentStart:i])
								hasEscaped = true
							}
							b.WriteByte('"')
							i += 2
						} else {
							if !hasEscaped {
								field = s[contentStart:i]
							} else {
								field = b.String()
							}
							i++ // consume closing '"'
							closed = true
							break
						}
					} else {
						if c == '\n' {
							line++
						}
						if hasEscaped {
							b.WriteByte(c)
						}
						i++
					}
				}
				if !closed {
					return nil, &ParseError{Line: startLine}
				}
			} else {
				start := i
				for i < len(s) {
					c := s[i]
					if c == '"' {
						return nil, &ParseError{Line: line}
					}
					if c == ',' || c == '\n' || (c == '\r' && i+1 < len(s) && s[i+1] == '\n') {
						break
					}
					i++
				}
				field = s[start:i]
			}

			record = append(record, field)

			if i == len(s) {
				break
			}
			if s[i] == ',' {
				i++
				continue
			}
			if s[i] == '\n' {
				i++
				line++
				break
			}
			if s[i] == '\r' && i+1 < len(s) && s[i+1] == '\n' {
				i += 2
				line++
				break
			}
			return nil, &ParseError{Line: line}
		}
		records = append(records, record)
	}

	return records, nil
}
