```go
package solution

import "errors"

// Count returns the number of business days (Monday through Friday, excluding
// holidays) in [from, to) when from <= to, or -Count(to, from, holidays) when
// to < from. All dates must be valid proleptic Gregorian dates in YYYY-MM-DD
// format.
func Count(from, to string, holidays []string) (int, error) {
	start, err := parseDate(from)
	if err != nil {
		return 0, err
	}
	end, err := parseDate(to)
	if err != nil {
		return 0, err
	}

	sign := 1
	if end < start {
		start, end = end, start
		sign = -1
	}

	var seen map[int]struct{}
	holidayCount := 0
	for _, h := range holidays {
		d, err := parseDate(h)
		if err != nil {
			return 0, err
		}
		if d >= start && d < end && d%7 < 5 {
			if seen == nil {
				seen = make(map[int]struct{})
			}
			if _, dup := seen[d]; !dup {
				seen[d] = struct{}{}
				holidayCount++
			}
		}
	}

	total := weekdaysBefore(end) - weekdaysBefore(start) - holidayCount
	return sign * total, nil
}

func parseDate(s string) (int, error) {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return 0, errors.New("invalid date format")
	}
	for _, i := range [8]int{0, 1, 2, 3, 5, 6, 8, 9} {
		if s[i] < '0' || s[i] > '9' {
			return 0, errors.New("invalid date format")
		}
	}

	y := int(s[0]-'0')*1000 + int(s[1]-'0')*100 + int(s[2]-'0')*10 + int(s[3]-'0')
	m := int(s[5]-'0')*10 + int(s[6]-'0')
	d := int(s[8]-'0')*10 + int(s[9]-'0')

	if m < 1 || m > 12 {
		return 0, errors.New("invalid month")
	}
	if d < 1 || d > daysInMonth(y, m) {
		return 0, errors.New("invalid day")
	}

	return daysFromCivil(y, m, d), nil
}

func isLeapYear(y int) bool {
	return y%4 == 0 && (y%100 != 0 || y%400 == 0)
}

func daysInMonth(y, m int) int {
	switch m {
	case 1, 3, 5, 7, 8, 10, 12:
		return 31
	case 4, 6, 9, 11:
		return 30
	case 2:
		if isLeapYear(y) {
			return 29
		}
		return 28
	default:
		return 0
	}
}

// daysFromCivil maps a proleptic Gregorian date (0000-01-01 through 9999-12-31)
// to a positive day number where day%7 gives the weekday with Monday=0 .. Sunday=6.
func daysFromCivil(y, m, d int) int {
	if m <= 2 {
		y--
	}
	era := y / 400
	if y < 0 {
		era = (y - 399) / 400
	}
	yoe := y - era*400
	mp := m - 3
	if mp < 0 {
		mp += 12
	}
	doy := (153*mp+2)/5 + d - 1
	doe := yoe*365 + yoe/4 - yoe/100 + doy
	return era*146097 + doe + 65
}

func weekdaysBefore(d int) int {
	return (d/7)*5 + min(d%7, 5)
}
