```go
package solution

import (
	"errors"
	"math"
	"strconv"
)

type tokenKind int

const (
	tokEOF tokenKind = iota
	tokNum
	tokPlus
	tokMinus
	tokStar
	tokSlash
	tokCaret
	tokLParen
	tokRParen
)

type token struct {
	kind tokenKind
	val  float64
}

type parser struct {
	s   string
	pos int
	cur token
}

func Eval(s string) (float64, error) {
	p := &parser{s: s}
	if err := p.advance(); err != nil {
		return 0, err
	}
	val, err := p.parseExpr()
	if err != nil {
		return 0, err
	}
	if p.cur.kind != tokEOF {
		return 0, errors.New("unexpected trailing token")
	}
	return val, nil
}

func isSpace(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\r'
}

func isDigit(b byte) bool {
	return b >= '0' && b <= '9'
}

func (p *parser) advance() error {
	tok, err := p.nextToken()
	if err != nil {
		return err
	}
	p.cur = tok
	return nil
}

func (p *parser) nextToken() (token, error) {
	for p.pos < len(p.s) && isSpace(p.s[p.pos]) {
		p.pos++
	}
	if p.pos >= len(p.s) {
		return token{kind: tokEOF}, nil
	}

	c := p.s[p.pos]
	switch c {
	case '+':
		p.pos++
		return token{kind: tokPlus}, nil
	case '-':
		p.pos++
		return token{kind: tokMinus}, nil
	case '*':
		p.pos++
		return token{kind: tokStar}, nil
	case '/':
		p.pos++
		return token{kind: tokSlash}, nil
	case '^':
		p.pos++
		return token{kind: tokCaret}, nil
	case '(':
		p.pos++
		return token{kind: tokLParen}, nil
	case ')':
		p.pos++
		return token{kind: tokRParen}, nil
	}

	if isDigit(c) || c == '.' {
		start := p.pos
		hasDigits := false
		for p.pos < len(p.s) && isDigit(p.s[p.pos]) {
			p.pos++
			hasDigits = true
		}
		if p.pos < len(p.s) && p.s[p.pos] == '.' {
			p.pos++
			for p.pos < len(p.s) && isDigit(p.s[p.pos]) {
				p.pos++
				hasDigits = true
			}
		}
		if !hasDigits {
			return token{}, errors.New("invalid number")
		}
		val, err := strconv.ParseFloat(p.s[start:p.pos], 64)
		if err != nil {
			return token{}, err
		}
		return token{kind: tokNum, val: val}, nil
	}

	return token{}, errors.New("invalid character")
}

func (p *parser) parseExpr() (float64, error) {
	lhs, err := p.parseTerm()
	if err != nil {
		return 0, err
	}
	for p.cur.kind == tokPlus || p.cur.kind == tokMinus {
		op := p.cur.kind
		if err := p.advance(); err != nil {
			return 0, err
		}
		rhs, err := p.parseTerm()
		if err != nil {
			return 0, err
		}
		if op == tokPlus {
			lhs += rhs
		} else {
			lhs -= rhs
		}
	}
	return lhs, nil
}

func (p *parser) parseTerm() (float64, error) {
	lhs, err := p.parseUnary()
	if err != nil {
		return 0, err
	}
	for p.cur.kind == tokStar || p.cur.kind == tokSlash {
		op := p.cur.kind
		if err := p.advance(); err != nil {
			return 0, err
		}
		rhs, err := p.parseUnary()
		if err != nil {
			return 0, err
		}
		if op == tokStar {
			lhs *= rhs
		} else {
			if rhs == 0 {
				return 0, errors.New("division by zero")
			}
			lhs /= rhs
		}
	}
	return lhs, nil
}

func (p *parser) parseUnary() (float64, error) {
	neg := false
	for p.cur.kind == tokPlus || p.cur.kind == tokMinus {
		if p.cur.kind == tokMinus {
			neg = !neg
		}
		if err := p.advance(); err != nil {
			return 0, err
		}
	}
	val, err := p.parsePower()
	if err != nil {
		return 0, err
	}
	if neg {
		val = -val
	}
	return val, nil
}

func (p *parser) parsePower() (float64, error) {
	base, err := p.parsePrimary()
	if err != nil {
		return 0, err
	}
	if p.cur.kind == tokCaret {
		if err := p.advance(); err != nil {
			return 0, err
		}
		exp, err := p.parseUnary()
		if err != nil {
			return 0, err
		}
		return math.Pow(base, exp), nil
	}
	return base, nil
}

func (p *parser) parsePrimary() (float64, error) {
	switch p.cur.kind {
	case tokNum:
		val := p.cur.val
		if err := p.advance(); err != nil {
			return 0, err
		}
		return val, nil
	case tokLParen:
		if err := p.advance(); err != nil {
			return 0, err
		}
		val, err := p.parseExpr()
		if err != nil {
			return 0, err
		}
		if p.cur.kind != tokRParen {
			return 0, errors.New("expected ')'")
		}
		if err := p.advance(); err != nil {
			return 0, err
		}
		return val, nil
	default:
		return 0, errors.New("unexpected token")
	}
}
