package solution

import (
	"context"
	"errors"
	"sync"
)

// ErrBadLimit is returned by Map when limit is not positive.
var ErrBadLimit = errors.New("parmap: limit must be positive")

// Map calls f once per element of in, running at most limit calls
// concurrently, and returns the results in input order.
func Map[T, R any](ctx context.Context, in []T, limit int, f func(context.Context, T) (R, error)) ([]R, error) {
	if limit <= 0 {
		return nil, ErrBadLimit
	}
	if len(in) == 0 {
		return []R{}, nil
	}

	workCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	results := make([]R, len(in))
	sem := make(chan struct{}, limit)
	ready := make(chan bool)

	var (
		wg       sync.WaitGroup
		mu       sync.Mutex
		firstErr error
	)

	processed := 0

dispatch:
	for i := range in {
		if workCtx.Err() != nil {
			break
		}
		select {
		case sem <- struct{}{}:
		case <-workCtx.Done():
			break dispatch
		}

		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			defer func() { <-sem }()

			// Last check before beginning the call, as close as possible
			// to the actual invocation of f.
			if workCtx.Err() != nil {
				ready <- false
				return
			}
			ready <- true

			r, err := f(workCtx, in[i])
			if err != nil {
				mu.Lock()
				if firstErr == nil {
					firstErr = err
				}
				mu.Unlock()
				// Cancel before releasing the semaphore slot so that no
				// new call can begin after this error has been observed.
				cancel()
				return
			}
			results[i] = r
		}(i)

		// Wait until goroutine i has begun (or declined) its call so that
		// calls start in increasing index order.
		if !<-ready {
			break
		}
		processed++
	}

	wg.Wait()
	cancel()

	mu.Lock()
	err := firstErr
	mu.Unlock()

	if err != nil {
		return nil, err
	}
	if processed < len(in) {
		if cerr := ctx.Err(); cerr != nil {
			return nil, cerr
		}
		return nil, context.Canceled
	}
	return results, nil
}
