package solution

// Set represents a set of integers stored as disjoint, maximally merged
// half-open intervals [lo, hi). The zero value is an empty set ready to use.
type Set struct {
	root *node
	rng  uint64
}

type node struct {
	lo, hi int
	cnt    int
	prio   uint64
	left   *node
	right  *node
}

func (s *Set) nextPrio() uint64 {
	s.rng += 0x9e3779b97f4a7c15
	z := s.rng
	z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9
	z = (z ^ (z >> 27)) * 0x94d049bb133111eb
	return z ^ (z >> 31)
}

func (s *Set) newNode(lo, hi int) *node {
	return &node{
		lo:   lo,
		hi:   hi,
		cnt:  1,
		prio: s.nextPrio(),
	}
}

func update(n *node) {
	if n == nil {
		return
	}
	c := 1
	if n.left != nil {
		c += n.left.cnt
	}
	if n.right != nil {
		c += n.right.cnt
	}
	n.cnt = c
}

func minNode(n *node) *node {
	for n.left != nil {
		n = n.left
	}
	return n
}

func maxNode(n *node) *node {
	for n.right != nil {
		n = n.right
	}
	return n
}

func splitByHiLess(n *node, v int) (l, r *node) {
	if n == nil {
		return nil, nil
	}
	if n.hi < v {
		l, r = splitByHiLess(n.right, v)
		n.right = l
		update(n)
		return n, r
	}
	l, r = splitByHiLess(n.left, v)
	n.left = r
	update(n)
	return l, n
}

func splitByHiLessEq(n *node, v int) (l, r *node) {
	if n == nil {
		return nil, nil
	}
	if n.hi <= v {
		l, r = splitByHiLessEq(n.right, v)
		n.right = l
		update(n)
		return n, r
	}
	l, r = splitByHiLessEq(n.left, v)
	n.left = r
	update(n)
	return l, n
}

func splitByLoLess(n *node, v int) (l, r *node) {
	if n == nil {
		return nil, nil
	}
	if n.lo < v {
		l, r = splitByLoLess(n.right, v)
		n.right = l
		update(n)
		return n, r
	}
	l, r = splitByLoLess(n.left, v)
	n.left = r
	update(n)
	return l, n
}

func splitByLoLessEq(n *node, v int) (l, r *node) {
	if n == nil {
		return nil, nil
	}
	if n.lo <= v {
		l, r = splitByLoLessEq(n.right, v)
		n.right = l
		update(n)
		return n, r
	}
	l, r = splitByLoLessEq(n.left, v)
	n.left = r
	update(n)
	return l, n
}

func merge(l, r *node) *node {
	if l == nil {
		return r
	}
	if r == nil {
		return l
	}
	if l.prio >= r.prio {
		l.right = merge(l.right, r)
		update(l)
		return l
	}
	r.left = merge(l, r.left)
	update(r)
	return r
}

// Add adds every integer in [lo, hi) to the set.
func (s *Set) Add(lo, hi int) {
	if lo >= hi {
		return
	}
	l, rest := splitByHiLess(s.root, lo)
	m, r := splitByLoLessEq(rest, hi)
	if m != nil {
		if mLo := minNode(m).lo; mLo < lo {
			lo = mLo
		}
		if mHi := maxNode(m).hi; mHi > hi {
			hi = mHi
		}
	}
	s.root = merge(merge(l, s.newNode(lo, hi)), r)
}

// Remove removes every integer in [lo, hi) from the set.
func (s *Set) Remove(lo, hi int) {
	if lo >= hi {
		return
	}
	l, rest := splitByHiLessEq(s.root, lo)
	m, r := splitByLoLess(rest, hi)
	if m == nil {
		s.root = merge(l, r)
		return
	}
	res := l
	if leftLo := minNode(m).lo; leftLo < lo {
		res = merge(res, s.newNode(leftLo, lo))
	}
	if rightHi := maxNode(m).hi; rightHi > hi {
		res = merge(res, s.newNode(hi, rightHi))
	}
	s.root = merge(res, r)
}

// Contains reports whether x is in the set.
func (s *Set) Contains(x int) bool {
	cur := s.root
	for cur != nil {
		if x < cur.lo {
			cur = cur.left
		} else if x >= cur.hi {
			cur = cur.right
		} else {
			return true
		}
	}
	return false
}

func appendIntervals(dst [][2]int, n *node) [][2]int {
	if n == nil {
		return dst
	}
	dst = appendIntervals(dst, n.left)
	dst = append(dst, [2]int{n.lo, n.hi})
	return appendIntervals(dst, n.right)
}

// Intervals returns a fresh copy of the canonical sorted, disjoint,
// maximally merged half-open intervals in the set.
func (s *Set) Intervals() [][2]int {
	if s.root == nil {
		return nil
	}
	res := make([][2]int, 0, s.root.cnt)
	return appendIntervals(res, s.root)
}
