package solution

import (
	"errors"
	"strings"
)

type version struct {
	major, minor, patch string
	pre                 []string
}

func isDigits(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func isNumericIdent(s string) bool {
	if !isDigits(s) {
		return false
	}
	if len(s) > 1 && s[0] == '0' {
		return false
	}
	return true
}

func isIdentChars(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '-') {
			return false
		}
	}
	return true
}

func parse(s string) (*version, error) {
	if len(s) > 0 && s[0] == 'v' {
		s = s[1:]
	}
	if idx := strings.IndexByte(s, '+'); idx >= 0 {
		build := s[idx+1:]
		s = s[:idx]
		if build == "" {
			return nil, errors.New("empty build metadata")
		}
		for _, id := range strings.Split(build, ".") {
			if !isIdentChars(id) {
				return nil, errors.New("invalid build identifier")
			}
		}
	}
	var pre []string
	if idx := strings.IndexByte(s, '-'); idx >= 0 {
		p := s[idx+1:]
		s = s[:idx]
		if p == "" {
			return nil, errors.New("empty pre-release")
		}
		pre = strings.Split(p, ".")
		for _, id := range pre {
			if !isIdentChars(id) {
				return nil, errors.New("invalid pre-release identifier")
			}
			if isDigits(id) && !isNumericIdent(id) {
				return nil, errors.New("leading zero in numeric pre-release identifier")
			}
		}
	}
	parts := strings.Split(s, ".")
	if len(parts) != 3 {
		return nil, errors.New("version core must have three components")
	}
	for _, p := range parts {
		if !isNumericIdent(p) {
			return nil, errors.New("invalid numeric identifier in version core")
		}
	}
	return &version{major: parts[0], minor: parts[1], patch: parts[2], pre: pre}, nil
}

// cmpNum compares two numeric identifiers without leading zeros.
func cmpNum(a, b string) int {
	if len(a) != len(b) {
		if len(a) < len(b) {
			return -1
		}
		return 1
	}
	return strings.Compare(a, b)
}

func cmpIdent(a, b string) int {
	an, bn := isDigits(a), isDigits(b)
	switch {
	case an && bn:
		return cmpNum(a, b)
	case an:
		return -1
	case bn:
		return 1
	default:
		return strings.Compare(a, b)
	}
}

// Compare compares two semantic version strings by precedence.
func Compare(a, b string) (int, error) {
	va, err := parse(a)
	if err != nil {
		return 0, err
	}
	vb, err := parse(b)
	if err != nil {
		return 0, err
	}
	if c := cmpNum(va.major, vb.major); c != 0 {
		return c, nil
	}
	if c := cmpNum(va.minor, vb.minor); c != 0 {
		return c, nil
	}
	if c := cmpNum(va.patch, vb.patch); c != 0 {
		return c, nil
	}
	if len(va.pre) == 0 && len(vb.pre) == 0 {
		return 0, nil
	}
	if len(va.pre) == 0 {
		return 1, nil
	}
	if len(vb.pre) == 0 {
		return -1, nil
	}
	n := len(va.pre)
	if len(vb.pre) < n {
		n = len(vb.pre)
	}
	for i := 0; i < n; i++ {
		if c := cmpIdent(va.pre[i], vb.pre[i]); c != 0 {
			return c, nil
		}
	}
	switch {
	case len(va.pre) < len(vb.pre):
		return -1, nil
	case len(va.pre) > len(vb.pre):
		return 1, nil
	}
	return 0, nil
}
