package solution

import "time"

type entry struct {
	key     string
	val     string
	expiry  time.Time
	prev    *entry
	next    *entry
	heapIdx int
}

type Cache struct {
	capacity int
	ttl      time.Duration
	now      func() time.Time
	entries  map[string]*entry
	root     entry // sentinel: root.next is MRU, root.prev is LRU
	expHeap  []*entry
}

func New(capacity int, ttl time.Duration, now func() time.Time) *Cache {
	c := &Cache{
		capacity: capacity,
		ttl:      ttl,
		now:      now,
		entries:  make(map[string]*entry),
	}
	c.root.next = &c.root
	c.root.prev = &c.root
	return c
}

func (c *Cache) Get(k string) (string, bool) {
	e, ok := c.entries[k]
	if !ok {
		return "", false
	}
	if !c.now().Before(e.expiry) {
		c.removeEntry(e)
		return "", false
	}
	c.moveToFront(e)
	return e.val, true
}

func (c *Cache) Put(k, v string) {
	now := c.now()
	expiry := now.Add(c.ttl)

	if e, ok := c.entries[k]; ok {
		e.val = v
		e.expiry = expiry
		c.heapFix(e.heapIdx)
		c.moveToFront(e)
		return
	}

	if len(c.entries) == c.capacity {
		c.evictExpired(now)
		if len(c.entries) == c.capacity {
			c.removeEntry(c.root.prev)
		}
	}

	e := &entry{
		key:    k,
		val:    v,
		expiry: expiry,
	}
	c.entries[k] = e
	c.pushFront(e)
	c.heapPush(e)
}

func (c *Cache) Len() int {
	if len(c.entries) == 0 {
		return 0
	}
	c.evictExpired(c.now())
	return len(c.entries)
}

func (c *Cache) removeEntry(e *entry) {
	delete(c.entries, e.key)
	c.unlink(e)
	c.heapRemove(e.heapIdx)
}

func (c *Cache) evictExpired(now time.Time) {
	for len(c.expHeap) > 0 && !now.Before(c.expHeap[0].expiry) {
		c.removeEntry(c.expHeap[0])
	}
}

func (c *Cache) pushFront(e *entry) {
	e.prev = &c.root
	e.next = c.root.next
	c.root.next.prev = e
	c.root.next = e
}

func (c *Cache) unlink(e *entry) {
	e.prev.next = e.next
	e.next.prev = e.prev
	e.prev = nil
	e.next = nil
}

func (c *Cache) moveToFront(e *entry) {
	if c.root.next == e {
		return
	}
	c.unlink(e)
	c.pushFront(e)
}

func (c *Cache) heapSwap(i, j int) {
	c.expHeap[i], c.expHeap[j] = c.expHeap[j], c.expHeap[i]
	c.expHeap[i].heapIdx = i
	c.expHeap[j].heapIdx = j
}

func (c *Cache) heapSiftUp(i int) {
	for i > 0 {
		p := (i - 1) / 2
		if !c.expHeap[i].expiry.Before(c.expHeap[p].expiry) {
			break
		}
		c.heapSwap(i, p)
		i = p
	}
}

func (c *Cache) heapSiftDown(i int) bool {
	n := len(c.expHeap)
	start := i
	for {
		left := 2*i + 1
		if left >= n {
			break
		}
		smallest := left
		if right := left + 1; right < n && c.expHeap[right].expiry.Before(c.expHeap[left].expiry) {
			smallest = right
		}
		if !c.expHeap[smallest].expiry.Before(c.expHeap[i].expiry) {
			break
		}
		c.heapSwap(i, smallest)
		i = smallest
	}
	return i > start
}

func (c *Cache) heapPush(e *entry) {
	e.heapIdx = len(c.expHeap)
	c.expHeap = append(c.expHeap, e)
	c.heapSiftUp(e.heapIdx)
}

func (c *Cache) heapRemove(i int) {
	last := len(c.expHeap) - 1
	if i != last {
		c.heapSwap(i, last)
	}
	c.expHeap[last].heapIdx = -1
	c.expHeap[last] = nil
	c.expHeap = c.expHeap[:last]
	if i < last {
		if !c.heapSiftDown(i) {
			c.heapSiftUp(i)
		}
	}
}

func (c *Cache) heapFix(i int) {
	if !c.heapSiftDown(i) {
		c.heapSiftUp(i)
	}
}
