package solution

import (
	"container/heap"
	"sort"
	"strings"
)

// CycleError reports a canonical cycle found in the dependency graph.
type CycleError struct {
	Cycle []string
}

func (e *CycleError) Error() string {
	if e == nil || len(e.Cycle) == 0 {
		return "dependency cycle detected"
	}
	parts := make([]string, 0, len(e.Cycle)+1)
	for _, c := range e.Cycle {
		parts = append(parts, quoteName(c))
	}
	parts = append(parts, quoteName(e.Cycle[0]))
	return "dependency cycle detected: " + strings.Join(parts, " -> ")
}

func quoteName(s string) string {
	return "\"" + s + "\""
}

type intHeap []int

func (h intHeap) Len() int            { return len(h) }
func (h intHeap) Less(i, j int) bool  { return h[i] < h[j] }
func (h intHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *intHeap) Push(x interface{}) { *h = append(*h, x.(int)) }
func (h *intHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

// Order returns the deterministic topological order of deps, or a *CycleError.
func Order(deps map[string][]string) ([]string, error) {
	// Collect node set.
	nameSet := make(map[string]struct{})
	for k, list := range deps {
		nameSet[k] = struct{}{}
		for _, d := range list {
			nameSet[d] = struct{}{}
		}
	}
	names := make([]string, 0, len(nameSet))
	for n := range nameSet {
		names = append(names, n)
	}
	sort.Strings(names)
	n := len(names)
	if n == 0 {
		return []string{}, nil
	}
	idx := make(map[string]int, n)
	for i, s := range names {
		idx[s] = i
	}

	// adj[a] = sorted, deduplicated dependencies of a (edges a -> d).
	adj := make([][]int, n)
	for k, list := range deps {
		a := idx[k]
		seen := make(map[int]struct{}, len(list))
		for _, d := range list {
			di := idx[d]
			if _, ok := seen[di]; ok {
				continue
			}
			seen[di] = struct{}{}
			adj[a] = append(adj[a], di)
		}
		sort.Ints(adj[a])
	}

	// Reverse edges: dependents[d] = nodes a that depend on d.
	dependents := make([][]int, n)
	indeg := make([]int, n)
	for a := 0; a < n; a++ {
		indeg[a] = len(adj[a])
		for _, d := range adj[a] {
			dependents[d] = append(dependents[d], a)
		}
	}

	// Kahn's algorithm with min-heap (index order == lexicographic order).
	h := &intHeap{}
	for i := 0; i < n; i++ {
		if indeg[i] == 0 {
			*h = append(*h, i)
		}
	}
	heap.Init(h)
	order := make([]string, 0, n)
	for h.Len() > 0 {
		v := heap.Pop(h).(int)
		order = append(order, names[v])
		for _, a := range dependents[v] {
			indeg[a]--
			if indeg[a] == 0 {
				heap.Push(h, a)
			}
		}
	}
	if len(order) == n {
		return order, nil
	}

	// Cycle exists: compute SCCs (iterative Tarjan).
	comp := tarjanSCC(n, adj)
	compSize := make(map[int]int)
	for _, c := range comp {
		compSize[c]++
	}
	n0 := -1
	for v := 0; v < n; v++ {
		onCycle := compSize[comp[v]] > 1
		if !onCycle {
			for _, d := range adj[v] {
				if d == v {
					onCycle = true
					break
				}
			}
		}
		if onCycle {
			n0 = v
			break
		}
	}
	if n0 < 0 {
		// Should not happen: Kahn failed so a cycle must exist.
		return nil, &CycleError{}
	}

	targetComp := comp[n0]
	visited := make([]bool, n)
	visited[n0] = true
	path := []int{n0}
	cur := n0

	// reach reports whether n0 is reachable from u using only unvisited nodes
	// (other than the target n0 itself), restricted to n0's SCC.
	mark := make([]int, n)
	stamp := 0
	reach := func(u int) bool {
		stamp++
		stack := []int{u}
		mark[u] = stamp
		for len(stack) > 0 {
			v := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			for _, w := range adj[v] {
				if w == n0 {
					return true
				}
				if visited[w] || comp[w] != targetComp || mark[w] == stamp {
					continue
				}
				mark[w] = stamp
				stack = append(stack, w)
			}
		}
		return false
	}

	for {
		closes := false
		for _, d := range adj[cur] {
			if d == n0 {
				closes = true
				break
			}
		}
		if closes {
			break
		}
		next := -1
		for _, u := range adj[cur] {
			if visited[u] || comp[u] != targetComp {
				continue
			}
			if reach(u) {
				next = u
				break
			}
		}
		if next < 0 {
			// Should not happen given invariants.
			break
		}
		visited[next] = true
		path = append(path, next)
		cur = next
	}

	cycle := make([]string, len(path))
	for i, v := range path {
		cycle[i] = names[v]
	}
	return nil, &CycleError{Cycle: cycle}
}

func tarjanSCC(n int, adj [][]int) []int {
	index := make([]int, n)
	low := make([]int, n)
	onStack := make([]bool, n)
	comp := make([]int, n)
	for i := range index {
		index[i] = -1
		comp[i] = -1
	}
	counter := 0
	compCount := 0
	var stack []int
	type frame struct {
		v   int
		pos int
	}
	for s := 0; s < n; s++ {
		if index[s] != -1 {
			continue
		}
		index[s] = counter
		low[s] = counter
		counter++
		stack = append(stack, s)
		onStack[s] = true
		calls := []frame{{v: s}}
		for len(calls) > 0 {
			top := &calls[len(calls)-1]
			v := top.v
			if top.pos < len(adj[v]) {
				w := adj[v][top.pos]
				top.pos++
				if index[w] == -1 {
					index[w] = counter
					low[w] = counter
					counter++
					stack = append(stack, w)
					onStack[w] = true
					calls = append(calls, frame{v: w})
				} else if onStack[w] {
					if index[w] < low[v] {
						low[v] = index[w]
					}
				}
				continue
			}
			calls = calls[:len(calls)-1]
			if low[v] == index[v] {
				for {
					w := stack[len(stack)-1]
					stack = stack[:len(stack)-1]
					onStack[w] = false
					comp[w] = compCount
					if w == v {
						break
					}
				}
				compCount++
			}
			if len(calls) > 0 {
				p := calls[len(calls)-1].v
				if low[v] < low[p] {
					low[p] = low[v]
				}
			}
		}
	}
	return comp
}
