package solution

import (
	"cmp"
	"errors"
	"strings"
)

var errInvalidVersion = errors.New("invalid semantic version")

type preIdent struct {
	val     string
	numeric bool
}

type version struct {
	major string
	minor string
	patch string
	pre   []preIdent
}

func Compare(a, b string) (int, error) {
	va, err := parseVersion(a)
	if err != nil {
		return 0, err
	}
	vb, err := parseVersion(b)
	if err != nil {
		return 0, err
	}

	if c := compareNumeric(va.major, vb.major); c != 0 {
		return c, nil
	}
	if c := compareNumeric(va.minor, vb.minor); c != 0 {
		return c, nil
	}
	if c := compareNumeric(va.patch, vb.patch); c != 0 {
		return c, nil
	}

	if len(va.pre) == 0 && len(vb.pre) == 0 {
		return 0, nil
	}
	if len(va.pre) == 0 {
		return 1, nil
	}
	if len(vb.pre) == 0 {
		return -1, nil
	}

	n := min(len(va.pre), len(vb.pre))
	for i := range n {
		pa, pb := va.pre[i], vb.pre[i]
		switch {
		case pa.numeric && pb.numeric:
			if c := compareNumeric(pa.val, pb.val); c != 0 {
				return c, nil
			}
		case pa.numeric:
			return -1, nil
		case pb.numeric:
			return 1, nil
		default:
			if c := cmp.Compare(pa.val, pb.val); c != 0 {
				return c, nil
			}
		}
	}

	return cmp.Compare(len(va.pre), len(vb.pre)), nil
}

func parseVersion(s string) (version, error) {
	if strings.HasPrefix(s, "v") {
		s = s[1:]
	}

	if plus := strings.IndexByte(s, '+'); plus >= 0 {
		if !isValidBuild(s[plus+1:]) {
			return version{}, errInvalidVersion
		}
		s = s[:plus]
	}

	var pre []preIdent
	if dash := strings.IndexByte(s, '-'); dash >= 0 {
		var ok bool
		pre, ok = parsePreRelease(s[dash+1:])
		if !ok {
			return version{}, errInvalidVersion
		}
		s = s[:dash]
	}

	dot1 := strings.IndexByte(s, '.')
	if dot1 < 0 {
		return version{}, errInvalidVersion
	}
	major := s[:dot1]
	rest := s[dot1+1:]

	dot2 := strings.IndexByte(rest, '.')
	if dot2 < 0 {
		return version{}, errInvalidVersion
	}
	minor := rest[:dot2]
	patch := rest[dot2+1:]

	if !isValidNumeric(major) || !isValidNumeric(minor) || !isValidNumeric(patch) {
		return version{}, errInvalidVersion
	}

	return version{
		major: major,
		minor: minor,
		patch: patch,
		pre:   pre,
	}, nil
}

func parsePreRelease(s string) ([]preIdent, bool) {
	if len(s) == 0 {
		return nil, false
	}
	var idents []preIdent
	for {
		dot := strings.IndexByte(s, '.')
		var part string
		if dot < 0 {
			part = s
		} else {
			part = s[:dot]
		}
		if len(part) == 0 {
			return nil, false
		}
		allDigits := true
		for i := range len(part) {
			b := part[i]
			if !isIdentChar(b) {
				return nil, false
			}
			if !isDigit(b) {
				allDigits = false
			}
		}
		if allDigits && len(part) > 1 && part[0] == '0' {
			return nil, false
		}
		idents = append(idents, preIdent{
			val:     part,
			numeric: allDigits,
		})
		if dot < 0 {
			return idents, true
		}
		s = s[dot+1:]
	}
}

func isValidBuild(s string) bool {
	if len(s) == 0 {
		return false
	}
	for {
		dot := strings.IndexByte(s, '.')
		var part string
		if dot < 0 {
			part = s
		} else {
			part = s[:dot]
		}
		if len(part) == 0 {
			return false
		}
		for i := range len(part) {
			if !isIdentChar(part[i]) {
				return false
			}
		}
		if dot < 0 {
			return true
		}
		s = s[dot+1:]
	}
}

func isValidNumeric(s string) bool {
	if len(s) == 0 {
		return false
	}
	if len(s) > 1 && s[0] == '0' {
		return false
	}
	for i := range len(s) {
		if !isDigit(s[i]) {
			return false
		}
	}
	return true
}

func compareNumeric(a, b string) int {
	if c := cmp.Compare(len(a), len(b)); c != 0 {
		return c
	}
	return cmp.Compare(a, b)
}

func isDigit(b byte) bool {
	return b >= '0' && b <= '9'
}

func isIdentChar(b byte) bool {
	return (b >= '0' && b <= '9') ||
		(b >= 'A' && b <= 'Z') ||
		(b >= 'a' && b <= 'z') ||
		b == '-'
}
