```go
package solution

import "strings"

type wrapUnit struct {
	text  string
	width int
	word  int
}

var wideRanges = [][2]rune{
	{0x1100, 0x115F},
	{0x2E80, 0xA4CF},
	{0xAC00, 0xD7A3},
	{0xF900, 0xFAFF},
	{0xFE30, 0xFE4F},
	{0xFF00, 0xFF60},
	{0xFFE0, 0xFFE6},
	{0x20000, 0x3FFFD},
}

func runeWidth(r rune) int {
	for _, rg := range wideRanges {
		if r >= rg[0] && r <= rg[1] {
			return 2
		}
	}
	return 1
}

func Wrap(s string, width int) []string {
	result := []string{}
	for _, para := range strings.Split(s, "\n") {
		result = append(result, wrapParagraph(para, width)...)
	}
	return result
}

func wrapParagraph(p string, width int) []string {
	words := strings.FieldsFunc(p, func(r rune) bool { return r == ' ' })
	if len(words) == 0 {
		return []string{""}
	}

	var units []wrapUnit
	for wi, w := range words {
		var narrow []rune
		flush := func() {
			for len(narrow) > 0 {
				n := len(narrow)
				if n > width {
					n = width
				}
				units = append(units, wrapUnit{text: string(narrow[:n]), width: n, word: wi})
				narrow = narrow[n:]
			}
			narrow = nil
		}
		for _, r := range w {
			if runeWidth(r) == 2 {
				flush()
				units = append(units, wrapUnit{text: string(r), width: 2, word: wi})
			} else {
				narrow = append(narrow, r)
			}
		}
		flush()
	}

	var lines []string
	var cur strings.Builder
	curW := 0
	empty := true
	prevWord := -1
	for _, u := range units {
		if empty {
			cur.WriteString(u.text)
			curW = u.width
			empty = false
		} else {
			joiner := ""
			if u.word != prevWord {
				joiner = " "
			}
			if curW+len(joiner)+u.width <= width {
				cur.WriteString(joiner)
				cur.WriteString(u.text)
				curW += len(joiner) + u.width
			} else {
				lines = append(lines, cur.String())
				cur.Reset()
				cur.WriteString(u.text)
				curW = u.width
			}
		}
		prevWord = u.word
	}
	lines = append(lines, cur.String())
	return lines
}
