package solution

import "errors"

var errInvalidDate = errors.New("invalid date")

func isDigit(c byte) bool {
	return c >= '0' && c <= '9'
}

func isLeap(y int64) bool {
	return (y%4 == 0 && y%100 != 0) || y%400 == 0
}

func daysInMonth(y, m int64) int64 {
	switch m {
	case 1, 3, 5, 7, 8, 10, 12:
		return 31
	case 4, 6, 9, 11:
		return 30
	case 2:
		if isLeap(y) {
			return 29
		}
		return 28
	}
	return 0
}

// floorDiv returns the floor of a/b for b > 0.
func floorDiv(a, b int64) int64 {
	q := a / b
	if (a%b != 0) && (a < 0) {
		q--
	}
	return q
}

// daysFromCivil returns the number of days since 1970-01-01 for the given
// proleptic Gregorian date.
func daysFromCivil(y, m, d int64) int64 {
	if m <= 2 {
		y--
	}
	era := floorDiv(y, 400)
	yoe := y - era*400
	var mp int64
	if m > 2 {
		mp = m - 3
	} else {
		mp = m + 9
	}
	doy := (153*mp+2)/5 + d - 1
	doe := yoe*365 + yoe/4 - yoe/100 + doy
	return era*146097 + doe - 719468
}

func parseDate(s string) (int64, error) {
	if len(s) != 10 {
		return 0, errInvalidDate
	}
	if s[4] != '-' || s[7] != '-' {
		return 0, errInvalidDate
	}
	for _, i := range []int{0, 1, 2, 3, 5, 6, 8, 9} {
		if !isDigit(s[i]) {
			return 0, errInvalidDate
		}
	}
	y := int64(s[0]-'0')*1000 + int64(s[1]-'0')*100 + int64(s[2]-'0')*10 + int64(s[3]-'0')
	m := int64(s[5]-'0')*10 + int64(s[6]-'0')
	d := int64(s[8]-'0')*10 + int64(s[9]-'0')
	if m < 1 || m > 12 {
		return 0, errInvalidDate
	}
	if d < 1 || d > daysInMonth(y, m) {
		return 0, errInvalidDate
	}
	return daysFromCivil(y, m, d), nil
}

// weekday returns 0 for Monday ... 6 for Sunday.
func weekday(z int64) int64 {
	// 1970-01-01 (z == 0) was a Thursday (index 3).
	return ((z+3)%7 + 7) % 7
}

// weekdaysBetween counts Monday-Friday days in [a, b), requires a <= b.
func weekdaysBetween(a, b int64) int64 {
	n := b - a
	full := n / 7
	rem := n % 7
	res := full * 5
	wd := weekday(a)
	for i := int64(0); i < rem; i++ {
		if (wd+i)%7 < 5 {
			res++
		}
	}
	return res
}

// Count returns the number of business days from `from` (inclusive) to `to`
// (exclusive), excluding the given holidays. If to < from, the result is
// the negation of Count(to, from, holidays).
func Count(from, to string, holidays []string) (int, error) {
	a, err := parseDate(from)
	if err != nil {
		return 0, err
	}
	b, err := parseDate(to)
	if err != nil {
		return 0, err
	}
	hs := make(map[int64]struct{}, len(holidays))
	for _, h := range holidays {
		z, err := parseDate(h)
		if err != nil {
			return 0, err
		}
		hs[z] = struct{}{}
	}

	sign := int64(1)
	if b < a {
		a, b = b, a
		sign = -1
	}

	count := weekdaysBetween(a, b)
	for z := range hs {
		if z >= a && z < b && weekday(z) < 5 {
			count--
		}
	}
	return int(sign * count), nil
}
