```go
package solution

import (
	"strings"
	"unicode/utf8"
)

// Wrap breaks s into lines whose display width is at most width.
func Wrap(s string, width int) []string {
	lines := make([]string, 0)
	for p := range strings.SplitSeq(s, "\n") {
		lines = wrapParagraph(lines, p, width)
	}
	return lines
}

func wrapParagraph(lines []string, p string, width int) []string {
	var cur strings.Builder
	curWidth := 0

	emitUnit := func(unit string, unitWidth int, newWord bool) {
		if curWidth == 0 {
			cur.WriteString(unit)
			curWidth = unitWidth
			return
		}
		joinerWidth := 0
		if newWord {
			joinerWidth = 1
		}
		if curWidth+joinerWidth+unitWidth <= width {
			if newWord {
				cur.WriteByte(' ')
			}
			cur.WriteString(unit)
			curWidth += joinerWidth + unitWidth
		} else {
			lines = append(lines, cur.String())
			cur.Reset()
			cur.WriteString(unit)
			curWidth = unitWidth
		}
	}

	for pos := 0; pos < len(p); {
		for pos < len(p) && p[pos] == ' ' {
			pos++
		}
		if pos >= len(p) {
			break
		}
		start := pos
		for pos < len(p) && p[pos] != ' ' {
			pos++
		}
		word := p[start:pos]

		firstUnit := true
		for i := 0; i < len(word); {
			r, size := utf8.DecodeRuneInString(word[i:])
			if isWide(r) {
				emitUnit(word[i:i+size], 2, firstUnit)
				firstUnit = false
				i += size
				continue
			}

			chunkStart := i
			chunkRunes := 1
			i += size
			for {
				if chunkRunes == width {
					emitUnit(word[chunkStart:i], chunkRunes, firstUnit)
					firstUnit = false
					chunkStart = i
					chunkRunes = 0
				}
				if i >= len(word) {
					break
				}
				r, size := utf8.DecodeRuneInString(word[i:])
				if isWide(r) {
					break
				}
				i += size
				chunkRunes++
			}
			if chunkRunes > 0 {
				emitUnit(word[chunkStart:i], chunkRunes, firstUnit)
				firstUnit = false
			}
		}
	}

	return append(lines, cur.String())
}

func isWide(r rune) bool {
	if r < 0x1100 {
		return false
	}
	return r <= 0x115F ||
		(r >= 0x2E80 && r <= 0xA4CF) ||
		(r >= 0xAC00 && r <= 0xD7A3) ||
		(r >= 0xF900 && r <= 0xFAFF) ||
		(r >= 0xFE30 && r <= 0xFE4F) ||
		(r >= 0xFF00 && r <= 0xFF60) ||
		(r >= 0xFFE0 && r <= 0xFFE6) ||
		(r >= 0x20000 && r <= 0x3FFFD)
}
