package solution

import (
	"strconv"
	"strings"
)

// ParseError reports a syntax error in the input, with the 1-based line number
// of the offending position.
type ParseError struct {
	Line int
}

func (e *ParseError) Error() string {
	return "csv parse error on line " + strconv.Itoa(e.Line)
}

// Parse parses s as strict CSV and returns its records.
func Parse(s string) ([][]string, error) {
	n := len(s)
	if n == 0 {
		return nil, nil
	}

	var records [][]string
	i := 0
	line := 1

	for {
		// Parse one record.
		var record []string
		for {
			// Parse one field.
			if i < n && s[i] == '"' {
				openLine := line
				i++
				var b strings.Builder
				for {
					if i >= n {
						return nil, &ParseError{Line: openLine}
					}
					c := s[i]
					if c == '"' {
						if i+1 < n && s[i+1] == '"' {
							b.WriteByte('"')
							i += 2
							continue
						}
						i++
						break
					}
					if c == '\n' {
						line++
					}
					b.WriteByte(c)
					i++
				}
				record = append(record, b.String())
			} else {
				start := i
				for i < n {
					c := s[i]
					if c == ',' || c == '\n' || (c == '\r' && i+1 < n && s[i+1] == '\n') {
						break
					}
					if c == '"' {
						return nil, &ParseError{Line: line}
					}
					i++
				}
				record = append(record, s[start:i])
			}

			// After a field: comma, line end, or end of input.
			if i >= n {
				records = append(records, record)
				return records, nil
			}
			c := s[i]
			if c == ',' {
				i++
				continue
			}
			if c == '\n' {
				i++
				line++
				break
			}
			if c == '\r' && i+1 < n && s[i+1] == '\n' {
				i += 2
				line++
				break
			}
			return nil, &ParseError{Line: line}
		}

		records = append(records, record)
		if i >= n {
			return records, nil
		}
	}
}
