package solution

import (
	"math"
	"sync"
	"time"
)

type Limiter struct {
	mu         sync.Mutex
	rate       float64
	burst      int
	now        func() time.Time
	watermark  time.Time
	baseTime   time.Time
	baseTokens float64
}

func New(rate float64, burst int, now func() time.Time) *Limiter {
	t := now()
	return &Limiter{
		rate:       rate,
		burst:      burst,
		now:        now,
		watermark:  t,
		baseTime:   t,
		baseTokens: float64(burst),
	}
}

func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

func (l *Limiter) AllowN(n int) bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	tokens := l.refillLocked(l.now())
	if n > l.burst {
		return false
	}
	need := float64(n)
	if tokens < need {
		return false
	}
	l.baseTokens = tokens - need
	l.baseTime = l.watermark
	return true
}

func (l *Limiter) Delay(n int) time.Duration {
	l.mu.Lock()
	defer l.mu.Unlock()

	tokens := l.refillLocked(l.now())
	if n > l.burst {
		return time.Duration(-1)
	}
	need := float64(n)
	if tokens >= need {
		return 0
	}
	missing := need - tokens
	ns := math.Ceil((missing * 1e9) / l.rate)
	if ns >= float64(math.MaxInt64) {
		return time.Duration(math.MaxInt64)
	}
	if ns < 1 {
		return 1
	}
	return time.Duration(ns)
}

func (l *Limiter) refillLocked(t time.Time) float64 {
	if t.After(l.watermark) {
		if l.watermark.Sub(l.baseTime) >= 1<<60 || t.Sub(l.baseTime) == math.MaxInt64 {
			l.baseTokens += tokensFromDuration(l.watermark.Sub(l.baseTime), l.rate)
			l.baseTime = l.watermark
			if maxTokens := float64(l.burst); l.baseTokens >= maxTokens {
				l.baseTokens = maxTokens
			}
		}
		l.watermark = t
	}
	tokens := l.baseTokens + tokensFromDuration(l.watermark.Sub(l.baseTime), l.rate)
	if maxTokens := float64(l.burst); tokens >= maxTokens {
		tokens = maxTokens
		l.baseTokens = maxTokens
		l.baseTime = l.watermark
	}
	return tokens
}

func tokensFromDuration(d time.Duration, rate float64) float64 {
	if d <= 0 {
		return 0
	}
	var tokens float64
	if sec := d / time.Second; sec > 0 {
		tokens += float64(sec) * rate
	}
	if nsec := d % time.Second; nsec > 0 {
		tokens += (float64(nsec) * rate) / 1e9
	}
	return tokens
}
