package solution

import (
	"context"
	"errors"
	"sync"
)

var ErrBadLimit = errors.New("parmap: limit must be positive")

func Map[T, R any](ctx context.Context, in []T, limit int, f func(context.Context, T) (R, error)) ([]R, error) {
	if limit <= 0 {
		return nil, ErrBadLimit
	}
	if len(in) == 0 {
		return make([]R, 0), nil
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}

	workCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	results := make([]R, len(in))

	var (
		mu       sync.Mutex
		next     int
		firstErr error
	)

	worker := func() {
		for {
			mu.Lock()
			if firstErr != nil || ctx.Err() != nil || next >= len(in) {
				mu.Unlock()
				return
			}
			i := next
			next++
			mu.Unlock()

			res, err := f(workCtx, in[i])
			if err != nil {
				mu.Lock()
				first := firstErr == nil
				if first {
					firstErr = err
				}
				mu.Unlock()
				if first {
					cancel()
				}
				return
			}
			results[i] = res
		}
	}

	numWorkers := min(limit, len(in))
	if numWorkers == 1 {
		worker()
	} else {
		var wg sync.WaitGroup
		for range numWorkers {
			mu.Lock()
			stop := firstErr != nil || ctx.Err() != nil || next >= len(in)
			mu.Unlock()
			if stop {
				break
			}
			wg.Add(1)
			go func() {
				defer wg.Done()
				worker()
			}()
		}
		wg.Wait()
	}

	if firstErr != nil {
		return nil, firstErr
	}
	if next < len(in) {
		return nil, ctx.Err()
	}
	return results, nil
}
