package solution

import "errors"

var errInvalidDate = errors.New("invalid date")

// Count returns the number of business days (Monday through Friday, excluding
// holidays) in the half-open interval [from, to), or the negated count of
// [to, from) if to < from.
func Count(from, to string, holidays []string) (int, error) {
	fromDay, err := parseDate(from)
	if err != nil {
		return 0, err
	}
	toDay, err := parseDate(to)
	if err != nil {
		return 0, err
	}

	start, end := fromDay, toDay
	sign := 1
	if toDay < fromDay {
		start, end = toDay, fromDay
		sign = -1
	}

	var seen map[int]struct{}
	holidayCount := 0
	for _, h := range holidays {
		day, err := parseDate(h)
		if err != nil {
			return 0, err
		}
		if day >= start && day < end && day%7 < 5 {
			if seen == nil {
				seen = make(map[int]struct{})
			}
			if _, ok := seen[day]; !ok {
				seen[day] = struct{}{}
				holidayCount++
			}
		}
	}

	total := weekdaysBefore(end) - weekdaysBefore(start) - holidayCount
	return sign * total, nil
}

func weekdaysBefore(day int) int {
	return (day/7)*5 + min(day%7, 5)
}

func parseDate(s string) (int, error) {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return 0, errInvalidDate
	}
	for _, i := range [8]int{0, 1, 2, 3, 5, 6, 8, 9} {
		if s[i] < '0' || s[i] > '9' {
			return 0, errInvalidDate
		}
	}

	year := int(s[0]-'0')*1000 + int(s[1]-'0')*100 + int(s[2]-'0')*10 + int(s[3]-'0')
	month := int(s[5]-'0')*10 + int(s[6]-'0')
	day := int(s[8]-'0')*10 + int(s[9]-'0')

	if month < 1 || month > 12 {
		return 0, errInvalidDate
	}
	if day < 1 || day > daysInMonth(year, month) {
		return 0, errInvalidDate
	}

	return dayNumber(year, month, day), nil
}

func isLeap(year int) bool {
	return year%4 == 0 && (year%100 != 0 || year%400 == 0)
}

func daysInMonth(year, month int) int {
	switch month {
	case 4, 6, 9, 11:
		return 30
	case 2:
		if isLeap(year) {
			return 29
		}
		return 28
	default:
		return 31
	}
}

// dayNumber maps a proleptic Gregorian date (0000-01-01 to 9999-12-31) to a
// non-negative day index where index % 7 is 0 for Monday through 6 for Sunday.
func dayNumber(year, month, day int) int {
	y := year + 400
	var mp int
	if month <= 2 {
		y--
		mp = month + 9
	} else {
		mp = month - 3
	}
	era := y / 400
	yoe := y - era*400
	doy := (153*mp+2)/5 + day - 1
	doe := yoe*365 + yoe/4 - yoe/100 + doy
	return era*146097 + doe - 146032
}
