package solution

import "sort"

// Set is a set of integers stored as sorted, disjoint, maximally merged
// half-open intervals. The zero value is an empty set ready to use.
type Set struct {
	iv [][2]int
}

// Add adds every integer in [lo, hi) to the set.
func (s *Set) Add(lo, hi int) {
	if lo >= hi {
		return
	}
	n := len(s.iv)
	// First interval that overlaps or touches [lo, hi): its end >= lo.
	i := sort.Search(n, func(k int) bool { return s.iv[k][1] >= lo })
	// First interval that starts strictly after hi (cannot touch).
	j := sort.Search(n, func(k int) bool { return s.iv[k][0] > hi })

	newLo, newHi := lo, hi
	if i < j {
		if s.iv[i][0] < newLo {
			newLo = s.iv[i][0]
		}
		if s.iv[j-1][1] > newHi {
			newHi = s.iv[j-1][1]
		}
	}

	res := make([][2]int, 0, n-(j-i)+1)
	res = append(res, s.iv[:i]...)
	res = append(res, [2]int{newLo, newHi})
	res = append(res, s.iv[j:]...)
	s.iv = res
}

// Remove removes every integer in [lo, hi) from the set.
func (s *Set) Remove(lo, hi int) {
	if lo >= hi {
		return
	}
	n := len(s.iv)
	// First interval whose end is after lo (actually overlaps).
	i := sort.Search(n, func(k int) bool { return s.iv[k][1] > lo })
	// First interval starting at or after hi (no overlap).
	j := sort.Search(n, func(k int) bool { return s.iv[k][0] >= hi })
	if i >= j {
		return
	}

	res := make([][2]int, 0, n-(j-i)+2)
	res = append(res, s.iv[:i]...)
	if s.iv[i][0] < lo {
		res = append(res, [2]int{s.iv[i][0], lo})
	}
	if s.iv[j-1][1] > hi {
		res = append(res, [2]int{hi, s.iv[j-1][1]})
	}
	res = append(res, s.iv[j:]...)
	s.iv = res
}

// Contains reports whether x is in the set.
func (s *Set) Contains(x int) bool {
	n := len(s.iv)
	i := sort.Search(n, func(k int) bool { return s.iv[k][1] > x })
	return i < n && s.iv[i][0] <= x
}

// Intervals returns a fresh copy of the canonical interval list.
func (s *Set) Intervals() [][2]int {
	out := make([][2]int, len(s.iv))
	copy(out, s.iv)
	return out
}
