package solution

import (
	"strconv"
	"strings"
)

type ParseError struct {
	Line int
}

func (e *ParseError) Error() string {
	return "parse error on line " + strconv.Itoa(e.Line)
}

func Parse(s string) ([][]string, error) {
	if len(s) == 0 {
		return nil, nil
	}

	var records [][]string
	i := 0
	line := 1

	for i < len(s) {
		var record []string
	recordLoop:
		for {
			if i < len(s) && s[i] == '"' {
				startLine := line
				i++ // consume opening '"'
				start := i
				var buf strings.Builder
				hasEscapes := false
				closed := false

				for i < len(s) {
					c := s[i]
					if c == '"' {
						if i+1 < len(s) && s[i+1] == '"' {
							hasEscapes = true
							buf.WriteString(s[start : i+1])
							i += 2
							start = i
							continue
						}
						if hasEscapes {
							buf.WriteString(s[start:i])
						}
						i++ // consume closing '"'
						closed = true
						break
					}
					if c == '\n' {
						line++
					}
					i++
				}

				if !closed {
					return nil, &ParseError{Line: startLine}
				}

				if hasEscapes {
					record = append(record, buf.String())
				} else {
					record = append(record, s[start:i-1])
				}

				if i == len(s) {
					break recordLoop
				}
				if s[i] == ',' {
					i++
					continue recordLoop
				}
				if s[i] == '\n' {
					line++
					i++
					break recordLoop
				}
				if s[i] == '\r' && i+1 < len(s) && s[i+1] == '\n' {
					line++
					i += 2
					break recordLoop
				}
				return nil, &ParseError{Line: line}
			}

			start := i
			for i < len(s) {
				c := s[i]
				if c == ',' {
					record = append(record, s[start:i])
					i++
					continue recordLoop
				}
				if c == '\n' {
					record = append(record, s[start:i])
					line++
					i++
					break recordLoop
				}
				if c == '\r' && i+1 < len(s) && s[i+1] == '\n' {
					record = append(record, s[start:i])
					line++
					i += 2
					break recordLoop
				}
				if c == '"' {
					return nil, &ParseError{Line: line}
				}
				i++
			}
			record = append(record, s[start:i])
			break recordLoop
		}
		records = append(records, record)
	}

	return records, nil
}
