package solution

import (
	"errors"
	"math"
	"strconv"
)

type tokenKind int

const (
	tokInvalid tokenKind = iota
	tokEOF
	tokNumber
	tokPlus
	tokMinus
	tokStar
	tokSlash
	tokCaret
	tokLParen
	tokRParen
)

type token struct {
	kind tokenKind
	val  float64
}

type parser struct {
	s   string
	pos int
	cur token
}

func Eval(s string) (float64, error) {
	p := &parser{s: s}
	p.next()
	val, err := p.parseExpr()
	if err != nil {
		return 0, err
	}
	if p.cur.kind != tokEOF {
		return 0, errors.New("unexpected trailing token")
	}
	return val, nil
}

func isDigit(c byte) bool {
	return c >= '0' && c <= '9'
}

func (p *parser) next() {
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			p.pos++
			continue
		}
		break
	}
	if p.pos >= len(p.s) {
		p.cur = token{kind: tokEOF}
		return
	}

	c := p.s[p.pos]
	switch c {
	case '+':
		p.pos++
		p.cur = token{kind: tokPlus}
	case '-':
		p.pos++
		p.cur = token{kind: tokMinus}
	case '*':
		p.pos++
		p.cur = token{kind: tokStar}
	case '/':
		p.pos++
		p.cur = token{kind: tokSlash}
	case '^':
		p.pos++
		p.cur = token{kind: tokCaret}
	case '(':
		p.pos++
		p.cur = token{kind: tokLParen}
	case ')':
		p.pos++
		p.cur = token{kind: tokRParen}
	default:
		if isDigit(c) || c == '.' {
			start := p.pos
			hasDigits := false
			for p.pos < len(p.s) && isDigit(p.s[p.pos]) {
				p.pos++
				hasDigits = true
			}
			if p.pos < len(p.s) && p.s[p.pos] == '.' {
				p.pos++
				for p.pos < len(p.s) && isDigit(p.s[p.pos]) {
					p.pos++
					hasDigits = true
				}
			}
			if !hasDigits {
				p.cur = token{kind: tokInvalid}
				return
			}
			val, err := strconv.ParseFloat(p.s[start:p.pos], 64)
			if err != nil && !errors.Is(err, strconv.ErrRange) {
				p.cur = token{kind: tokInvalid}
				return
			}
			p.cur = token{kind: tokNumber, val: val}
			return
		}
		p.pos++
		p.cur = token{kind: tokInvalid}
	}
}

func (p *parser) parseExpr() (float64, error) {
	left, err := p.parseTerm()
	if err != nil {
		return 0, err
	}
	for p.cur.kind == tokPlus || p.cur.kind == tokMinus {
		op := p.cur.kind
		p.next()
		right, err := p.parseTerm()
		if err != nil {
			return 0, err
		}
		if op == tokPlus {
			left += right
		} else {
			left -= right
		}
	}
	return left, nil
}

func (p *parser) parseTerm() (float64, error) {
	left, err := p.parseUnary()
	if err != nil {
		return 0, err
	}
	for p.cur.kind == tokStar || p.cur.kind == tokSlash {
		op := p.cur.kind
		p.next()
		right, err := p.parseUnary()
		if err != nil {
			return 0, err
		}
		if op == tokStar {
			left *= right
		} else {
			if right == 0 {
				return 0, errors.New("division by zero")
			}
			left /= right
		}
	}
	return left, nil
}

func (p *parser) parseUnary() (float64, error) {
	neg := false
	for p.cur.kind == tokPlus || p.cur.kind == tokMinus {
		if p.cur.kind == tokMinus {
			neg = !neg
		}
		p.next()
	}
	val, err := p.parsePower()
	if err != nil {
		return 0, err
	}
	if neg {
		return -val, nil
	}
	return val, nil
}

func (p *parser) parsePower() (float64, error) {
	base, err := p.parsePrimary()
	if err != nil {
		return 0, err
	}
	if p.cur.kind == tokCaret {
		p.next()
		exp, err := p.parseUnary()
		if err != nil {
			return 0, err
		}
		return math.Pow(base, exp), nil
	}
	return base, nil
}

func (p *parser) parsePrimary() (float64, error) {
	switch p.cur.kind {
	case tokNumber:
		val := p.cur.val
		p.next()
		return val, nil
	case tokLParen:
		p.next()
		val, err := p.parseExpr()
		if err != nil {
			return 0, err
		}
		if p.cur.kind != tokRParen {
			return 0, errors.New("expected ')'")
		}
		p.next()
		return val, nil
	default:
		return 0, errors.New("unexpected token")
	}
}
