package solution

import (
	"context"
	"errors"
	"sync"
)

// ErrBadLimit is returned by Map when limit is not positive.
var ErrBadLimit = errors.New("parmap: limit must be positive")

// Map calls f once per element of in, running at most limit calls concurrently,
// and returns the results in input order.
func Map[T, R any](ctx context.Context, in []T, limit int, f func(context.Context, T) (R, error)) ([]R, error) {
	if limit <= 0 {
		return nil, ErrBadLimit
	}
	if len(in) == 0 {
		return []R{}, nil
	}

	workCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	results := make([]R, len(in))
	sem := make(chan struct{}, limit)

	var (
		mu       sync.Mutex
		firstErr error
		wg       sync.WaitGroup
	)

	stopped := func() bool {
		return ctx.Err() != nil || workCtx.Err() != nil
	}

	started := 0
	for i := range in {
		if stopped() {
			break
		}

		// Acquire a concurrency slot, or give up if the work context is done.
		acquired := false
		select {
		case sem <- struct{}{}:
			acquired = true
		case <-workCtx.Done():
		}
		if !acquired {
			break
		}
		if stopped() {
			<-sem
			break
		}

		ready := make(chan struct{})
		skipped := false
		wg.Add(1)
		go func() {
			defer wg.Done()
			defer func() { <-sem }()

			// Last-moment check before beginning the call.
			if ctx.Err() != nil || workCtx.Err() != nil {
				skipped = true
				close(ready)
				return
			}
			close(ready)

			r, err := f(workCtx, in[i])
			if err != nil {
				mu.Lock()
				if firstErr == nil {
					firstErr = err
				}
				mu.Unlock()
				cancel()
				return
			}
			results[i] = r
		}()

		// Wait until this call has begun (or been skipped) before starting the next,
		// so that calls begin in increasing index order.
		<-ready
		if skipped {
			break
		}
		started++
	}

	wg.Wait()
	cancel()

	mu.Lock()
	err := firstErr
	mu.Unlock()

	if err != nil {
		return nil, err
	}
	if started < len(in) {
		if cerr := ctx.Err(); cerr != nil {
			return nil, cerr
		}
		return nil, context.Canceled
	}
	return results, nil
}
