package solution

type Set struct {
	root *node
	rng  uint64
}

type node struct {
	lo, hi      int
	prio        uint64
	size        int
	left, right *node
}

func (n *node) update() {
	sz := 1
	if n.left != nil {
		sz += n.left.size
	}
	if n.right != nil {
		sz += n.right.size
	}
	n.size = sz
}

func (s *Set) nextPrio() uint64 {
	s.rng += 0x9e3779b97f4a7c15
	z := s.rng
	z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9
	z = (z ^ (z >> 27)) * 0x94d049bb133111eb
	return z ^ (z >> 31)
}

func (s *Set) newNode(lo, hi int) *node {
	return &node{
		lo:   lo,
		hi:   hi,
		prio: s.nextPrio(),
		size: 1,
	}
}

func splitHi(n *node, x int, inclusive bool) (left, right *node) {
	if n == nil {
		return nil, nil
	}
	if n.hi < x || (inclusive && n.hi == x) {
		var rl *node
		rl, right = splitHi(n.right, x, inclusive)
		n.right = rl
		n.update()
		return n, right
	}
	var lr *node
	left, lr = splitHi(n.left, x, inclusive)
	n.left = lr
	n.update()
	return left, n
}

func splitLo(n *node, x int, inclusive bool) (left, right *node) {
	if n == nil {
		return nil, nil
	}
	if n.lo < x || (inclusive && n.lo == x) {
		var rl *node
		rl, right = splitLo(n.right, x, inclusive)
		n.right = rl
		n.update()
		return n, right
	}
	var lr *node
	left, lr = splitLo(n.left, x, inclusive)
	n.left = lr
	n.update()
	return left, n
}

func merge(a, b *node) *node {
	if a == nil {
		return b
	}
	if b == nil {
		return a
	}
	if a.prio > b.prio {
		a.right = merge(a.right, b)
		a.update()
		return a
	}
	b.left = merge(a, b.left)
	b.update()
	return b
}

func leftmost(n *node) *node {
	for n.left != nil {
		n = n.left
	}
	return n
}

func rightmost(n *node) *node {
	for n.right != nil {
		n = n.right
	}
	return n
}

func (s *Set) Add(lo, hi int) {
	if lo >= hi {
		return
	}
	left, rest := splitHi(s.root, lo, false)
	mid, right := splitLo(rest, hi, true)
	if mid != nil {
		if mid.size == 1 && mid.lo <= lo && mid.hi >= hi {
			s.root = merge(merge(left, mid), right)
			return
		}
		if first := leftmost(mid); first.lo < lo {
			lo = first.lo
		}
		if last := rightmost(mid); last.hi > hi {
			hi = last.hi
		}
	}
	s.root = merge(merge(left, s.newNode(lo, hi)), right)
}

func (s *Set) Remove(lo, hi int) {
	if lo >= hi || s.root == nil {
		return
	}
	left, rest := splitHi(s.root, lo, true)
	mid, right := splitLo(rest, hi, false)
	if mid == nil {
		s.root = merge(left, right)
		return
	}
	res := left
	if first := leftmost(mid); first.lo < lo {
		res = merge(res, s.newNode(first.lo, lo))
	}
	if last := rightmost(mid); last.hi > hi {
		res = merge(res, s.newNode(hi, last.hi))
	}
	s.root = merge(res, right)
}

func (s *Set) Contains(x int) bool {
	for n := s.root; n != nil; {
		if x < n.lo {
			n = n.left
		} else if x >= n.hi {
			n = n.right
		} else {
			return true
		}
	}
	return false
}

func (s *Set) Intervals() [][2]int {
	if s.root == nil {
		return nil
	}
	res := make([][2]int, s.root.size)
	fillIntervals(s.root, res, 0)
	return res
}

func fillIntervals(n *node, res [][2]int, idx int) int {
	if n == nil {
		return idx
	}
	idx = fillIntervals(n.left, res, idx)
	res[idx] = [2]int{n.lo, n.hi}
	return fillIntervals(n.right, res, idx+1)
}
