```go
package solution

import (
	"slices"
	"strings"
)

type CycleError struct {
	Cycle []string
}

func (e *CycleError) Error() string {
	if e == nil || len(e.Cycle) == 0 {
		return "dependency cycle detected"
	}
	var b strings.Builder
	b.WriteString("dependency cycle: ")
	for i, node := range e.Cycle {
		if i > 0 {
			b.WriteString(" -> ")
		}
		b.WriteString(node)
	}
	b.WriteString(" -> ")
	b.WriteString(e.Cycle[0])
	return b.String()
}

func Order(deps map[string][]string) ([]string, error) {
	if len(deps) == 0 {
		return []string{}, nil
	}

	idOf := make(map[string]int, len(deps))
	for u, ds := range deps {
		idOf[u] = 0
		for _, d := range ds {
			idOf[d] = 0
		}
	}

	n := len(idOf)
	names := make([]string, 0, n)
	for name := range idOf {
		names = append(names, name)
	}
	slices.Sort(names)
	for i, name := range names {
		idOf[name] = i
	}

	adj := make([][]int, n)
	dependents := make([][]int, n)
	inDegree := make([]int, n)
	for uName, ds := range deps {
		if len(ds) == 0 {
			continue
		}
		u := idOf[uName]
		list := make([]int, len(ds))
		for i, dName := range ds {
			list[i] = idOf[dName]
		}
		slices.Sort(list)
		list = slices.Compact(list)
		adj[u] = list
		inDegree[u] = len(list)
		for _, d := range list {
			dependents[d] = append(dependents[d], u)
		}
	}

	heap := make([]int, 0, n)
	for u := range n {
		if inDegree[u] == 0 {
			heap = append(heap, u)
		}
	}

	heapPush := func(x int) {
		heap = append(heap, x)
		i := len(heap) - 1
		for i > 0 {
			p := (i - 1) / 2
			if heap[p] <= heap[i] {
				break
			}
			heap[p], heap[i] = heap[i], heap[p]
			i = p
		}
	}

	heapPop := func() int {
		res := heap[0]
		last := heap[len(heap)-1]
		heap = heap[:len(heap)-1]
		if len(heap) > 0 {
			heap[0] = last
			i := 0
			for {
				l := 2*i + 1
				if l >= len(heap) {
					break
				}
				smallest := l
				if r := l + 1; r < len(heap) && heap[r] < heap[l] {
					smallest = r
				}
				if heap[i] <= heap[smallest] {
					break
				}
				heap[i], heap[smallest] = heap[smallest], heap[i]
				i = smallest
			}
		}
		return res
	}

	order := make([]string, 0, n)
	for len(heap) > 0 {
		u := heapPop()
		order = append(order, names[u])
		for _, v := range dependents[u] {
			inDegree[v]--
			if inDegree[v] == 0 {
				heapPush(v)
			}
		}
	}

	if len(order) == n {
		return order, nil
	}

	return nil, &CycleError{Cycle: findCanonicalCycle(adj, names)}
}

func tarjanSCC(adj [][]int) ([]int, []int) {
	n := len(adj)
	disc := make([]int, n)
	low := make([]int, n)
	onStack := make([]bool, n)
	tarjanStack := make([]int, 0, n)
	comp := make([]int, n)
	var compSizes []int
	timer := 0

	type frame struct {
		u   int
		idx int
	}
	callStack := make([]frame, 0, n)

	for start := range n {
		if disc[start] != 0 {
			continue
		}
		timer++
		disc[start] = timer
		low[start] = timer
		onStack[start] = true
		tarjanStack = append(tarjanStack, start)
		callStack = append(callStack, frame{u: start, idx: 0})

		for len(callStack) > 0 {
			top := &callStack[len(callStack)-1]
			u := top.u
			if top.idx < len(adj[u]) {
				v := adj[u][top.idx]
				top.idx++
				if disc[v] == 0 {
					timer++
					disc[v] = timer
					low[v] = timer
					onStack[v] = true
					tarjanStack = append(tarjanStack, v)
					callStack = append(callStack, frame{u: v, idx: 0})
				} else if onStack[v] {
					if disc[v] < low[u] {
						low[u] = disc[v]
					}
				}
			} else {
				callStack = callStack[:len(callStack)-1]
				if len(callStack) > 0 {
					parent := callStack[len(callStack)-1].u
					if low[u] < low[parent] {
						low[parent] = low[u]
					}
				}
				if low[u] == disc[u] {
					cID := len(compSizes)
					size := 0
					for {
						w := tarjanStack[len(tarjanStack)-1]
						tarjanStack = tarjanStack[:len(tarjanStack)-1]
						onStack[w] = false
						comp[w] = cID
						size++
						if w == u {
							break
						}
					}
					compSizes = append(compSizes, size)
				}
			}
		}
	}

	return comp, compSizes
}

func findCanonicalCycle(adj [][]int, names []string) []string {
	n := len(adj)
	comp, compSizes := tarjanSCC(adj)

	n0 := -1
	for u := range n {
		if compSizes[comp[u]] >= 2 {
			n0 = u
			break
		}
		if _, ok := slices.BinarySearch(adj[u], u); ok {
			n0 = u
			break
		}
	}

	if _, ok := slices.BinarySearch(adj[n0], n0); ok {
		return []string{names[n0]}
	}

	targetComp := comp[n0]
	localID := make([]int, n)
	for i := range localID {
		localID[i] = -1
	}
	sccNodes := make([]int, 0, compSizes[targetComp])
	for u := n0; u < n; u++ {
		if comp[u] == targetComp {
			localID[u] = len(sccNodes)
			sccNodes = append(sccNodes, u)
		}
	}

	m := len(sccNodes)
	fAdj := make([][]int, m)
	rAdj := make([][]int, m)
	for lu, u := range sccNodes {
		for _, v := range adj[u] {
			if lv := localID[v]; lv >= 0 {
				fAdj[lu] = append(fAdj[lu], lv)
				rAdj[lv] = append(rAdj[lv], lu)
			}
		}
	}

	inP := make([]bool, m)
	dead := make([]bool, m)
	inTree := make([]bool, m)
	children := make([][]int, m)

	invQueue := make([]int, 0, m)
	invalidate := func(root int) {
		if !inTree[root] {
			return
		}
		inTree[root] = false
		invQueue = append(invQueue[:0], root)
		for head := 0; head < len(invQueue); head++ {
			x := invQueue[head]
			for _, ch := range children[x] {
				if inTree[ch] {
					inTree[ch] = false
					invQueue = append(invQueue, ch)
				}
			}
			children[x] = children[x][:0]
		}
	}

	bfsQueue := make([]int, 0, m)
	rebuildTree := func() {
		clear(inTree)
		for i := range m {
			children[i] = children[i][:0]
		}
		inTree[0] = true
		bfsQueue = append(bfsQueue[:0], 0)
		for head := 0; head < len(bfsQueue); head++ {
			x := bfsQueue[head]
			for _, y := range rAdj[x] {
				if !inP[y] && !dead[y] && !inTree[y] {
					inTree[y] = true
					children[x] = append(children[x], y)
					bfsQueue = append(bfsQueue, y)
				}
			}
		}
		for i := 1; i < m; i++ {
			if !inP[i] && !dead[i] && !inTree[i] {
				dead[i] = true
			}
		}
	}

	path := make([]int, 1, m)
	path[0] = 0
	inP[0] = true
	var cands []int

	for {
		cur := path[len(path)-1]
		if len(fAdj[cur]) > 0 && fAdj[cur][0] == 0 {
			break
		}
		cands = cands[:0]
		for _, v := range fAdj[cur] {
			if !inP[v] && !dead[v] {
				cands = append(cands, v)
			}
		}
		var next int
		if len(cands) == 1 || inTree[cands[0]] {
			next = cands[0]
		} else {
			rebuildTree()
			for _, v := range cands {
				if inTree[v] {
					next = v
					break
				}
			}
		}
		path = append(path, next)
		inP[next] = true
		invalidate(next)
	}

	cycle := make([]string, len(path))
	for i, lu := range path {
		cycle[i] = names[sccNodes[lu]]
	}
	return cycle
}
