package solution

import (
	"errors"
	"strings"
)

type version struct {
	core [3]string
	pre  []string
}

func isAlnumHyphen(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '-'
}

func isAllDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func validNumeric(s string) bool {
	if !isAllDigits(s) {
		return false
	}
	if len(s) > 1 && s[0] == '0' {
		return false
	}
	return true
}

func validIdent(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if !isAlnumHyphen(s[i]) {
			return false
		}
	}
	return true
}

func parse(s string) (*version, error) {
	if strings.HasPrefix(s, "v") {
		s = s[1:]
	}
	if s == "" {
		return nil, errors.New("empty version")
	}

	main := s
	if i := strings.IndexByte(s, '+'); i >= 0 {
		main = s[:i]
		build := s[i+1:]
		if build == "" {
			return nil, errors.New("empty build metadata")
		}
		for _, id := range strings.Split(build, ".") {
			if !validIdent(id) {
				return nil, errors.New("invalid build identifier")
			}
		}
	}

	core := main
	var pre []string
	if i := strings.IndexByte(main, '-'); i >= 0 {
		core = main[:i]
		preStr := main[i+1:]
		if preStr == "" {
			return nil, errors.New("empty pre-release")
		}
		pre = strings.Split(preStr, ".")
		for _, id := range pre {
			if !validIdent(id) {
				return nil, errors.New("invalid pre-release identifier")
			}
			if isAllDigits(id) && !validNumeric(id) {
				return nil, errors.New("leading zero in numeric pre-release identifier")
			}
		}
	}

	parts := strings.Split(core, ".")
	if len(parts) != 3 {
		return nil, errors.New("version core must have three components")
	}
	v := &version{pre: pre}
	for i, p := range parts {
		if !validNumeric(p) {
			return nil, errors.New("invalid numeric identifier in version core")
		}
		v.core[i] = p
	}
	return v, nil
}

// compareNumeric compares two valid numeric identifiers (no leading zeros).
func compareNumeric(a, b string) int {
	if len(a) != len(b) {
		if len(a) < len(b) {
			return -1
		}
		return 1
	}
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

func compareStr(a, b string) int {
	if a < b {
		return -1
	}
	if a > b {
		return 1
	}
	return 0
}

func Compare(a, b string) (int, error) {
	va, err := parse(a)
	if err != nil {
		return 0, err
	}
	vb, err := parse(b)
	if err != nil {
		return 0, err
	}

	for i := 0; i < 3; i++ {
		if c := compareNumeric(va.core[i], vb.core[i]); c != 0 {
			return c, nil
		}
	}

	if len(va.pre) == 0 && len(vb.pre) == 0 {
		return 0, nil
	}
	if len(va.pre) == 0 {
		return 1, nil
	}
	if len(vb.pre) == 0 {
		return -1, nil
	}

	n := len(va.pre)
	if len(vb.pre) < n {
		n = len(vb.pre)
	}
	for i := 0; i < n; i++ {
		x, y := va.pre[i], vb.pre[i]
		xn, yn := isAllDigits(x), isAllDigits(y)
		var c int
		switch {
		case xn && yn:
			c = compareNumeric(x, y)
		case xn && !yn:
			c = -1
		case !xn && yn:
			c = 1
		default:
			c = compareStr(x, y)
		}
		if c != 0 {
			return c, nil
		}
	}

	switch {
	case len(va.pre) < len(vb.pre):
		return -1, nil
	case len(va.pre) > len(vb.pre):
		return 1, nil
	}
	return 0, nil
}
