package solution

import "time"

type entry struct {
	key     string
	value   string
	expiry  time.Time
	prev    *entry
	next    *entry
	heapIdx int
}

type Cache struct {
	capacity int
	ttl      time.Duration
	now      func() time.Time
	entries  map[string]*entry
	root     entry // circular sentinel: root.next is MRU, root.prev is LRU
	expHeap  []*entry
}

func New(capacity int, ttl time.Duration, now func() time.Time) *Cache {
	c := &Cache{
		capacity: capacity,
		ttl:      ttl,
		now:      now,
		entries:  make(map[string]*entry),
	}
	c.root.next = &c.root
	c.root.prev = &c.root
	return c
}

func (c *Cache) Get(k string) (string, bool) {
	e, ok := c.entries[k]
	if !ok {
		return "", false
	}
	if !c.now().Before(e.expiry) {
		c.removeEntry(e)
		return "", false
	}
	c.moveToFront(e)
	return e.value, true
}

func (c *Cache) Put(k, v string) {
	t := c.now()
	if e, ok := c.entries[k]; ok {
		if t.Before(e.expiry) {
			e.value = v
			e.expiry = t.Add(c.ttl)
			c.heapFix(e.heapIdx)
			c.moveToFront(e)
			return
		}
		c.removeEntry(e)
	}

	if len(c.entries) == c.capacity {
		c.removeExpired(t)
		if len(c.entries) == c.capacity {
			c.removeEntry(c.root.prev)
		}
	}

	e := &entry{
		key:    k,
		value:  v,
		expiry: t.Add(c.ttl),
	}
	c.entries[k] = e
	c.pushFront(e)
	c.heapPush(e)
}

func (c *Cache) Len() int {
	if len(c.entries) == 0 {
		return 0
	}
	c.removeExpired(c.now())
	return len(c.entries)
}

func (c *Cache) removeExpired(t time.Time) {
	for len(c.expHeap) > 0 && !t.Before(c.expHeap[0].expiry) {
		c.removeEntry(c.expHeap[0])
	}
}

func (c *Cache) removeEntry(e *entry) {
	delete(c.entries, e.key)
	c.unlink(e)
	c.heapRemove(e.heapIdx)
}

func (c *Cache) pushFront(e *entry) {
	e.prev = &c.root
	e.next = c.root.next
	c.root.next.prev = e
	c.root.next = e
}

func (c *Cache) unlink(e *entry) {
	e.prev.next = e.next
	e.next.prev = e.prev
	e.prev = nil
	e.next = nil
}

func (c *Cache) moveToFront(e *entry) {
	if c.root.next == e {
		return
	}
	e.prev.next = e.next
	e.next.prev = e.prev
	e.prev = &c.root
	e.next = c.root.next
	c.root.next.prev = e
	c.root.next = e
}

func (c *Cache) heapSwap(i, j int) {
	c.expHeap[i], c.expHeap[j] = c.expHeap[j], c.expHeap[i]
	c.expHeap[i].heapIdx = i
	c.expHeap[j].heapIdx = j
}

func (c *Cache) siftUp(i int) {
	for i > 0 {
		parent := (i - 1) / 2
		if !c.expHeap[i].expiry.Before(c.expHeap[parent].expiry) {
			break
		}
		c.heapSwap(i, parent)
		i = parent
	}
}

func (c *Cache) siftDown(i int) bool {
	start := i
	n := len(c.expHeap)
	for {
		left := 2*i + 1
		if left >= n {
			break
		}
		smallest := left
		if right := left + 1; right < n && c.expHeap[right].expiry.Before(c.expHeap[left].expiry) {
			smallest = right
		}
		if !c.expHeap[smallest].expiry.Before(c.expHeap[i].expiry) {
			break
		}
		c.heapSwap(i, smallest)
		i = smallest
	}
	return i > start
}

func (c *Cache) heapPush(e *entry) {
	e.heapIdx = len(c.expHeap)
	c.expHeap = append(c.expHeap, e)
	c.siftUp(e.heapIdx)
}

func (c *Cache) heapFix(i int) {
	if !c.siftDown(i) {
		c.siftUp(i)
	}
}

func (c *Cache) heapRemove(i int) {
	last := len(c.expHeap) - 1
	if i != last {
		c.heapSwap(i, last)
	}
	c.expHeap[last].heapIdx = -1
	c.expHeap[last] = nil
	c.expHeap = c.expHeap[:last]
	if i != last {
		c.heapFix(i)
	}
}
