package solution

import (
	"errors"
	"strings"
)

type version struct {
	major string
	minor string
	patch string
	pre   string
}

// Compare parses two Semantic Versioning 2.0.0 strings and compares their precedence.
func Compare(a, b string) (int, error) {
	va, err := parse(a)
	if err != nil {
		return 0, err
	}
	vb, err := parse(b)
	if err != nil {
		return 0, err
	}

	if c := compareNumeric(va.major, vb.major); c != 0 {
		return c, nil
	}
	if c := compareNumeric(va.minor, vb.minor); c != 0 {
		return c, nil
	}
	if c := compareNumeric(va.patch, vb.patch); c != 0 {
		return c, nil
	}

	if va.pre == vb.pre {
		return 0, nil
	}
	if va.pre == "" {
		return 1, nil
	}
	if vb.pre == "" {
		return -1, nil
	}

	pa, pb := va.pre, vb.pre
	for {
		idA, restA, moreA := strings.Cut(pa, ".")
		idB, restB, moreB := strings.Cut(pb, ".")
		if idA != idB {
			numA := isAllDigits(idA)
			numB := isAllDigits(idB)
			if numA && numB {
				return compareNumeric(idA, idB), nil
			}
			if numA != numB {
				if numA {
					return -1, nil
				}
				return 1, nil
			}
			return strings.Compare(idA, idB), nil
		}
		if !moreA || !moreB {
			if !moreA && !moreB {
				return 0, nil
			}
			if !moreA {
				return -1, nil
			}
			return 1, nil
		}
		pa, pb = restA, restB
	}
}

func parse(s string) (version, error) {
	if s == "" {
		return version{}, errors.New("empty version")
	}
	if s[0] == 'v' {
		s = s[1:]
	}

	if corePre, build, hasBuild := strings.Cut(s, "+"); hasBuild {
		if !validBuild(build) {
			return version{}, errors.New("invalid build metadata")
		}
		s = corePre
	}

	var pre string
	if core, pr, hasPre := strings.Cut(s, "-"); hasPre {
		if !validPreRelease(pr) {
			return version{}, errors.New("invalid pre-release")
		}
		pre = pr
		s = core
	}

	major, rest, ok := strings.Cut(s, ".")
	if !ok {
		return version{}, errors.New("missing minor version")
	}
	minor, patch, ok := strings.Cut(rest, ".")
	if !ok {
		return version{}, errors.New("missing patch version")
	}
	if !validNumeric(major) || !validNumeric(minor) || !validNumeric(patch) {
		return version{}, errors.New("invalid core version")
	}

	return version{
		major: major,
		minor: minor,
		patch: patch,
		pre:   pre,
	}, nil
}

func compareNumeric(a, b string) int {
	if len(a) != len(b) {
		if len(a) < len(b) {
			return -1
		}
		return 1
	}
	return strings.Compare(a, b)
}

func isDigit(c byte) bool {
	return c >= '0' && c <= '9'
}

func isIdentChar(c byte) bool {
	return (c >= '0' && c <= '9') ||
		(c >= 'A' && c <= 'Z') ||
		(c >= 'a' && c <= 'z') ||
		c == '-'
}

func isAllDigits(s string) bool {
	for i := 0; i < len(s); i++ {
		if !isDigit(s[i]) {
			return false
		}
	}
	return true
}

func validNumeric(s string) bool {
	if len(s) == 0 {
		return false
	}
	if len(s) > 1 && s[0] == '0' {
		return false
	}
	return isAllDigits(s)
}

func validBuild(s string) bool {
	if len(s) == 0 {
		return false
	}
	for {
		id, rest, more := strings.Cut(s, ".")
		if len(id) == 0 {
			return false
		}
		for i := 0; i < len(id); i++ {
			if !isIdentChar(id[i]) {
				return false
			}
		}
		if !more {
			return true
		}
		s = rest
	}
}

func validPreRelease(s string) bool {
	if len(s) == 0 {
		return false
	}
	for {
		id, rest, more := strings.Cut(s, ".")
		if len(id) == 0 {
			return false
		}
		allDigits := true
		for i := 0; i < len(id); i++ {
			c := id[i]
			if !isIdentChar(c) {
				return false
			}
			if !isDigit(c) {
				allDigits = false
			}
		}
		if allDigits && len(id) > 1 && id[0] == '0' {
			return false
		}
		if !more {
			return true
		}
		s = rest
	}
}
