package solution

import "strings"

type wideRange struct {
	lo, hi rune
}

var wideRanges = []wideRange{
	{0x1100, 0x115F},
	{0x2E80, 0xA4CF},
	{0xAC00, 0xD7A3},
	{0xF900, 0xFAFF},
	{0xFE30, 0xFE4F},
	{0xFF00, 0xFF60},
	{0xFFE0, 0xFFE6},
	{0x20000, 0x3FFFD},
}

func isWide(r rune) bool {
	for _, wr := range wideRanges {
		if r >= wr.lo && r <= wr.hi {
			return true
		}
	}
	return false
}

func runeWidth(r rune) int {
	if isWide(r) {
		return 2
	}
	return 1
}

type unit struct {
	text  string
	width int
	word  int
}

// Wrap breaks s into lines whose display width is at most width.
func Wrap(s string, width int) []string {
	lines := make([]string, 0)
	for _, para := range strings.Split(s, "\n") {
		lines = append(lines, wrapParagraph(para, width)...)
	}
	if len(lines) == 0 {
		lines = append(lines, "")
	}
	return lines
}

func wrapParagraph(p string, width int) []string {
	words := strings.FieldsFunc(p, func(r rune) bool { return r == ' ' })
	if len(words) == 0 {
		return []string{""}
	}

	var units []unit
	for wi, w := range words {
		var narrow []rune
		flush := func() {
			if len(narrow) == 0 {
				return
			}
			for start := 0; start < len(narrow); start += width {
				end := start + width
				if end > len(narrow) {
					end = len(narrow)
				}
				units = append(units, unit{
					text:  string(narrow[start:end]),
					width: end - start,
					word:  wi,
				})
			}
			narrow = narrow[:0]
		}
		for _, r := range w {
			if isWide(r) {
				flush()
				units = append(units, unit{text: string(r), width: 2, word: wi})
			} else {
				narrow = append(narrow, r)
			}
		}
		flush()
	}

	var out []string
	var cur strings.Builder
	curW := 0
	empty := true
	prevWord := -1
	for _, u := range units {
		if empty {
			cur.WriteString(u.text)
			curW = u.width
			empty = false
			prevWord = u.word
			continue
		}
		joinW := 0
		join := ""
		if u.word != prevWord {
			joinW = 1
			join = " "
		}
		if curW+joinW+u.width <= width {
			cur.WriteString(join)
			cur.WriteString(u.text)
			curW += joinW + u.width
		} else {
			out = append(out, cur.String())
			cur.Reset()
			cur.WriteString(u.text)
			curW = u.width
		}
		prevWord = u.word
	}
	if !empty {
		out = append(out, cur.String())
	}
	if len(out) == 0 {
		out = append(out, "")
	}
	return out
}

var _ = runeWidth
