```go
package solution

import (
	"container/heap"
	"sort"
	"strconv"
	"strings"
)

// CycleError reports a canonical cycle found in the dependency graph.
type CycleError struct {
	Cycle []string
}

func (e *CycleError) Error() string {
	if e == nil || len(e.Cycle) == 0 {
		return "dependency cycle detected"
	}
	parts := make([]string, 0, len(e.Cycle)+1)
	for _, n := range e.Cycle {
		parts = append(parts, strconv.Quote(n))
	}
	parts = append(parts, strconv.Quote(e.Cycle[0]))
	return "dependency cycle detected: " + strings.Join(parts, " -> ")
}

type intHeap []int

func (h intHeap) Len() int            { return len(h) }
func (h intHeap) Less(i, j int) bool  { return h[i] < h[j] }
func (h intHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *intHeap) Push(x interface{}) { *h = append(*h, x.(int)) }
func (h *intHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

// Order returns a deterministic topological order of the nodes in deps, or a
// *CycleError describing the canonical cycle if the graph is cyclic.
func Order(deps map[string][]string) ([]string, error) {
	// Collect node set.
	nameSet := make(map[string]struct{})
	for a, ds := range deps {
		nameSet[a] = struct{}{}
		for _, d := range ds {
			nameSet[d] = struct{}{}
		}
	}
	names := make([]string, 0, len(nameSet))
	for n := range nameSet {
		names = append(names, n)
	}
	sort.Strings(names)
	n := len(names)
	if n == 0 {
		return []string{}, nil
	}
	idx := make(map[string]int, n)
	for i, s := range names {
		idx[s] = i
	}

	// Build adjacency (a -> d), sorted and deduplicated, plus reverse.
	adj := make([][]int, n)
	for a, ds := range deps {
		ai := idx[a]
		if len(ds) == 0 {
			continue
		}
		seen := make(map[int]struct{}, len(ds))
		list := make([]int, 0, len(ds))
		for _, d := range ds {
			di := idx[d]
			if _, ok := seen[di]; ok {
				continue
			}
			seen[di] = struct{}{}
			list = append(list, di)
		}
		sort.Ints(list)
		adj[ai] = list
	}
	rev := make([][]int, n)
	for a := 0; a < n; a++ {
		for _, d := range adj[a] {
			rev[d] = append(rev[d], a)
		}
	}

	// Kahn's algorithm with min-heap (index order == lexicographic order).
	remaining := make([]int, n)
	h := &intHeap{}
	for a := 0; a < n; a++ {
		remaining[a] = len(adj[a])
		if remaining[a] == 0 {
			*h = append(*h, a)
		}
	}
	heap.Init(h)
	order := make([]string, 0, n)
	for h.Len() > 0 {
		v := heap.Pop(h).(int)
		order = append(order, names[v])
		for _, w := range rev[v] {
			remaining[w]--
			if remaining[w] == 0 {
				heap.Push(h, w)
			}
		}
	}
	if len(order) == n {
		return order, nil
	}

	// Cycle exists: compute SCCs (iterative Tarjan).
	comp, compSize := tarjan(n, adj)

	hasEdge := func(a, b int) bool {
		l := adj[a]
		i := sort.SearchInts(l, b)
		return i < len(l) && l[i] == b
	}

	n0 := -1
	for v := 0; v < n; v++ {
		if compSize[comp[v]] > 1 || hasEdge(v, v) {
			n0 = v
			break
		}
	}
	if n0 < 0 {
		// Should be impossible: Kahn failed so a cycle exists.
		return nil, &CycleError{}
	}

	c0 := comp[n0]
	visited := make([]bool, n)
	reach := make([]int, n) // stamp array
	stamp := 0
	visited[n0] = true
	path := []int{n0}
	cur := n0
	queue := make([]int, 0)
	for {
		if hasEdge(cur, n0) {
			break
		}
		// Reverse BFS from n0 over unvisited nodes of the same SCC.
		stamp++
		queue = queue[:0]
		queue = append(queue, n0)
		for qi := 0; qi < len(queue); qi++ {
			x := queue[qi]
			for _, p := range rev[x] {
				if comp[p] != c0 || visited[p] || reach[p] == stamp {
					continue
				}
				reach[p] = stamp
				queue = append(queue, p)
			}
		}
		next := -1
		for _, w := range adj[cur] {
			if comp[w] == c0 && !visited[w] && reach[w] == stamp {
				next = w
				break
			}
		}
		if next < 0 {
			// Should be impossible by invariant.
			break
		}
		visited[next] = true
		path = append(path, next)
		cur = next
	}

	cycle := make([]string, len(path))
	for i, v := range path {
		cycle[i] = names[v]
	}
	return nil, &CycleError{Cycle: cycle}
}

func tarjan(n int, adj [][]int) ([]int, []int) {
	index := make([]int, n)
	low := make([]int, n)
	onStack := make([]bool, n)
	comp := make([]int, n)
	for i := range index {
		index[i] = -1
	}
	var compSize []int
	stack := make([]int, 0, n)
	type frame struct{ v, i int }
	var call []frame
	counter := 0

	for s := 0; s < n; s++ {
		if index[s] != -1 {
			continue
		}
		index[s] = counter
		low[s] = counter
		counter++
		stack = append(stack, s)
		onStack[s] = true
		call = append(call, frame{s, 0})
		for len(call) > 0 {
			top := &call[len(call)-1]
			v := top.v
			if top.i < len(adj[v]) {
				w := adj[v][top.i]
				top.i++
				if index[w] == -1 {
					index[w] = counter
					low[w] = counter
					counter++
					stack = append(stack, w)
					onStack[w] = true
					call = append(call, frame{w, 0})
				} else if onStack[w] && index[w] < low[v] {
					low[v] = index[w]
				}
				continue
			}
			call = call[:len(call)-1]
			if low[v] == index[v] {
				id := len(compSize)
				size := 0
				for {
					x := stack[len(stack)-1]
					stack = stack[:len(stack)-1]
					onStack[x] = false
					comp[x] = id
					size++
					if x == v {
						break
					}
				}
				compSize = append(compSize, size)
			}
			if len(call) > 0 {
				p := call[len(call)-1].v
				if low[v] < low[p] {
					low[p] = low[v]
				}
			}
		}
	}
	return comp, compSize
}
