package solution

import (
	"math"
	"sync"
	"time"
)

const (
	crystallizeThreshold = 1 << 60
	maxDurationFloat     = float64(math.MaxInt64)
)

// Limiter is a token-bucket rate limiter driven by an injected clock.
type Limiter struct {
	mu         sync.Mutex
	rate       float64
	burst      int
	now        func() time.Time
	watermark  time.Time
	baseTime   time.Time
	baseTokens float64
}

// New returns a new Limiter with the given refill rate (tokens per second),
// burst capacity, and clock function. The bucket starts full.
func New(rate float64, burst int, now func() time.Time) *Limiter {
	t := now()
	return &Limiter{
		rate:       rate,
		burst:      burst,
		now:        now,
		watermark:  t,
		baseTime:   t,
		baseTokens: float64(burst),
	}
}

func (l *Limiter) refill(t time.Time) float64 {
	if t.After(l.watermark) {
		l.watermark = t
	}
	elapsed := l.watermark.Sub(l.baseTime)
	if elapsed <= 0 {
		return l.baseTokens
	}
	tokens := l.baseTokens + l.rate*elapsed.Seconds()
	maxTokens := float64(l.burst)
	if tokens >= maxTokens {
		l.baseTokens = maxTokens
		l.baseTime = l.watermark
		return maxTokens
	}
	if elapsed >= crystallizeThreshold {
		l.baseTokens = tokens
		l.baseTime = l.watermark
	}
	return tokens
}

// Allow reports whether one token is available and consumes it if so.
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// AllowN reports whether n tokens are available and consumes them if so.
func (l *Limiter) AllowN(n int) bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	tokens := l.refill(l.now())
	if n > l.burst {
		return false
	}
	need := float64(n)
	if tokens < need {
		return false
	}
	l.baseTokens = tokens - need
	l.baseTime = l.watermark
	return true
}

// Delay reports how long a caller must wait before n tokens are available,
// without consuming any tokens. It returns -1 if n exceeds the burst capacity.
func (l *Limiter) Delay(n int) time.Duration {
	l.mu.Lock()
	defer l.mu.Unlock()

	tokens := l.refill(l.now())
	if n > l.burst {
		return time.Duration(-1)
	}
	need := float64(n)
	if tokens >= need {
		return 0
	}
	missing := need - tokens
	ns := (missing * float64(time.Second)) / l.rate
	if ns >= maxDurationFloat {
		return time.Duration(math.MaxInt64)
	}
	d := time.Duration(math.Ceil(ns))
	if d < 1 {
		return 1
	}
	return d
}
