package solution

import "errors"

var errInvalidDate = errors.New("invalid date")

func isDigit(c byte) bool {
	return c >= '0' && c <= '9'
}

func isLeap(y int) bool {
	return (y%4 == 0 && y%100 != 0) || y%400 == 0
}

func daysInMonth(y, m int) int {
	switch m {
	case 1, 3, 5, 7, 8, 10, 12:
		return 31
	case 4, 6, 9, 11:
		return 30
	case 2:
		if isLeap(y) {
			return 29
		}
		return 28
	}
	return 0
}

// daysFromCivil returns the number of days since 1970-01-01 in the
// proleptic Gregorian calendar.
func daysFromCivil(y, m, d int) int64 {
	if m <= 2 {
		y--
	}
	var era int
	if y >= 0 {
		era = y / 400
	} else {
		era = (y - 399) / 400
	}
	yoe := y - era*400
	var mp int
	if m > 2 {
		mp = m - 3
	} else {
		mp = m + 9
	}
	doy := (153*mp+2)/5 + d - 1
	doe := yoe*365 + yoe/4 - yoe/100 + doy
	return int64(era)*146097 + int64(doe) - 719468
}

func parseDate(s string) (int64, error) {
	if len(s) != 10 {
		return 0, errInvalidDate
	}
	if s[4] != '-' || s[7] != '-' {
		return 0, errInvalidDate
	}
	for _, i := range []int{0, 1, 2, 3, 5, 6, 8, 9} {
		if !isDigit(s[i]) {
			return 0, errInvalidDate
		}
	}
	y := int(s[0]-'0')*1000 + int(s[1]-'0')*100 + int(s[2]-'0')*10 + int(s[3]-'0')
	m := int(s[5]-'0')*10 + int(s[6]-'0')
	d := int(s[8]-'0')*10 + int(s[9]-'0')
	if m < 1 || m > 12 {
		return 0, errInvalidDate
	}
	if d < 1 || d > daysInMonth(y, m) {
		return 0, errInvalidDate
	}
	return daysFromCivil(y, m, d), nil
}

// shifted maps a day number to a non-negative value where multiples of 7
// correspond to Mondays. 1970-01-01 (day 0) is a Thursday, so day -3 is a Monday.
func shifted(n int64) int64 {
	return n + 3 + 7*200000
}

// weekdaysBefore returns the number of weekdays in [epochMonday, n).
func weekdaysBefore(n int64) int64 {
	m := shifted(n)
	r := m % 7
	if r > 5 {
		r = 5
	}
	return (m/7)*5 + r
}

func isWeekday(n int64) bool {
	return shifted(n)%7 < 5
}

// Count returns the number of business days in [from, to), negated if to < from.
func Count(from, to string, holidays []string) (int, error) {
	a, err := parseDate(from)
	if err != nil {
		return 0, err
	}
	b, err := parseDate(to)
	if err != nil {
		return 0, err
	}
	hdays := make([]int64, 0, len(holidays))
	for _, h := range holidays {
		hd, err := parseDate(h)
		if err != nil {
			return 0, err
		}
		hdays = append(hdays, hd)
	}

	sign := int64(1)
	if b < a {
		a, b = b, a
		sign = -1
	}

	count := weekdaysBefore(b) - weekdaysBefore(a)
	seen := make(map[int64]struct{}, len(hdays))
	for _, hd := range hdays {
		if hd < a || hd >= b || !isWeekday(hd) {
			continue
		}
		if _, ok := seen[hd]; ok {
			continue
		}
		seen[hd] = struct{}{}
		count--
	}
	return int(sign * count), nil
}
