// ParseError reports a CSV syntax error and the 1-based line where it occurred.
type ParseError struct {
	Line int
}

func (e *ParseError) Error() string {
	return "csv parse error on line " + strconv.Itoa(e.Line)
}

// Parse parses s as strict CSV and returns its records.
func Parse(s string) ([][]string, error) {
	n := len(s)
	if n == 0 {
		return [][]string{}, nil
	}

	records := [][]string{}
	i := 0
	line := 1

	for {
		record := []string{}
		endRecord := false

		for !endRecord {
			var field string

			if i < n && s[i] == '"' {
				openLine := line
				i++
				var b strings.Builder
				for {
					if i >= n {
						return nil, &ParseError{Line: openLine}
					}
					c := s[i]
					if c == '"' {
						if i+1 < n && s[i+1] == '"' {
							b.WriteByte('"')
							i += 2
							continue
						}
						i++
						break
					}
					if c == '\n' {
						line++
					}
					b.WriteByte(c)
					i++
				}
				field = b.String()
			} else {
				start := i
				for i < n {
					c := s[i]
					if c == ',' || c == '\n' || (c == '\r' && i+1 < n && s[i+1] == '\n') {
						break
					}
					if c == '"' {
						return nil, &ParseError{Line: line}
					}
					i++
				}
				field = s[start:i]
			}

			record = append(record, field)

			// Handle what follows the field.
			if i >= n {
				endRecord = true
				break
			}
			switch {
			case s[i] == ',':
				i++
			case s[i] == '\n':
				i++
				line++
				endRecord = true
			case s[i] == '\r' && i+1 < n && s[i+1] == '\n':
				i += 2
				line++
				endRecord = true
			default:
				return nil, &ParseError{Line: line}
			}
		}

		records = append(records, record)
		if i >= n {
			break
		}
	}

	return records, nil
}
