}

func Parse(s string) ([][]string, error) {
	if len(s) == 0 {
		return nil, nil
	}

	var records [][]string
	i := 0
	line := 1

	for i < len(s) {
		var record []string
		for {
			if i < len(s) && s[i] == '"' {
				startLine := line
				i++
				segStart := i
				var b strings.Builder
				hasEscaped := false
				closed := false
				var field string

				for i < len(s) {
					c := s[i]
					if c == '"' {
						if i+1 < len(s) && s[i+1] == '"' {
							b.WriteString(s[segStart : i+1])
							hasEscaped = true
							i += 2
							segStart = i
							continue
						}
						if hasEscaped {
							b.WriteString(s[segStart:i])
							field = b.String()
						} else {
							field = s[segStart:i]
						}
						i++
						closed = true
						break
					}
					if c == '\n' {
						line++
					}
					i++
				}

				if !closed {
					return nil, &ParseError{Line: startLine}
				}

				record = append(record, field)

				if i == len(s) {
					break
				}
				if s[i] == ',' {
					i++
					continue
				}
				if s[i] == '\n' {
					i++
					line++
					break
				}
				if s[i] == '\r' && i+1 < len(s) && s[i+1] == '\n' {
					i += 2
					line++
					break
				}
				return nil, &ParseError{Line: line}
			}

			start := i
			for i < len(s) {
				c := s[i]
				if c == ',' || c == '\n' {
					break
				}
				if c == '\r' && i+1 < len(s) && s[i+1] == '\n' {
					break
				}
				if c == '"' {
					return nil, &ParseError{Line: line}
				}
				i++
			}

			record = append(record, s[start:i])

			if i == len(s) {
				break
			}
			if s[i] == ',' {
				i++
				continue
			}
			if s[i] == '\n' {
				i++
				line++
				break
			}
			i += 2
			line++
			break
		}
		records = append(records, record)
	}

	return records, nil
