package solution

import (
	"context"
	"errors"
	"sync"
	"sync/atomic"
)

var ErrBadLimit = errors.New("parmap: limit must be positive")

func Map[T, R any](ctx context.Context, in []T, limit int, f func(context.Context, T) (R, error)) ([]R, error) {
	if limit <= 0 {
		return nil, ErrBadLimit
	}
	if len(in) == 0 {
		return []R{}, nil
	}
	if err := ctx.Err(); err != nil {
		return nil, err
	}

	workCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	maxWorkers := min(limit, len(in))
	results := make([]R, len(in))

	jobs := make(chan int)
	started := make(chan struct{}, 1)

	var (
		wg        sync.WaitGroup
		errOnce   sync.Once
		firstErr  error
		completed atomic.Int64
	)

	worker := func() {
		defer wg.Done()
		for idx := range jobs {
			if workCtx.Err() != nil || ctx.Err() != nil {
				started <- struct{}{}
				return
			}
			started <- struct{}{}
			res, err := f(workCtx, in[idx])
			if err != nil {
				errOnce.Do(func() {
					firstErr = err
					cancel()
				})
				return
			}
			results[idx] = res
			completed.Add(1)
			if workCtx.Err() != nil || ctx.Err() != nil {
				return
			}
		}
	}

	numWorkers := 0
dispatch:
	for i := range in {
		if workCtx.Err() != nil || ctx.Err() != nil {
			break
		}
		select {
		case jobs <- i:
			<-started
		default:
			if numWorkers < maxWorkers {
				numWorkers++
				wg.Add(1)
				go worker()
			}
			select {
			case <-workCtx.Done():
				break dispatch
			case <-ctx.Done():
				break dispatch
			case jobs <- i:
				<-started
			}
		}
	}

	close(jobs)
	wg.Wait()

	if completed.Load() == int64(len(in)) {
		return results, nil
	}
	if firstErr != nil {
		return nil, firstErr
	}
	return nil, ctx.Err()
}
