package solution

import (
	"strings"
	"unicode/utf8"
)

func Wrap(s string, width int) []string {
	paragraphs := strings.Split(s, "\n")
	res := make([]string, 0, len(paragraphs))
	var line strings.Builder

	for _, p := range paragraphs {
		line.Reset()
		curWidth := 0

		addUnit := func(unit string, unitWidth int, newWord bool) {
			if curWidth == 0 {
				line.WriteString(unit)
				curWidth = unitWidth
				return
			}
			joinerWidth := 0
			if newWord {
				joinerWidth = 1
			}
			if curWidth <= width-unitWidth-joinerWidth {
				if newWord {
					line.WriteByte(' ')
				}
				line.WriteString(unit)
				curWidth += joinerWidth + unitWidth
				return
			}
			res = append(res, line.String())
			line.Reset()
			line.WriteString(unit)
			curWidth = unitWidth
		}

		i := 0
		for i < len(p) {
			for i < len(p) && p[i] == ' ' {
				i++
			}
			if i == len(p) {
				break
			}

			firstUnit := true
			for i < len(p) && p[i] != ' ' {
				r, size := utf8.DecodeRuneInString(p[i:])
				if isWide(r) {
					addUnit(p[i:i+size], 2, firstUnit)
					firstUnit = false
					i += size
					continue
				}

				chunkStart := i
				runCount := 0
				for i < len(p) && p[i] != ' ' {
					r, size := utf8.DecodeRuneInString(p[i:])
					if isWide(r) {
						break
					}
					i += size
					runCount++
					if runCount == width {
						addUnit(p[chunkStart:i], runCount, firstUnit)
						firstUnit = false
						chunkStart = i
						runCount = 0
					}
				}
				if runCount > 0 {
					addUnit(p[chunkStart:i], runCount, firstUnit)
					firstUnit = false
				}
			}
		}

		res = append(res, line.String())
	}

	return res
}

func isWide(r rune) bool {
	if r < 0x1100 {
		return false
	}
	return r <= 0x115F ||
		(r >= 0x2E80 && r <= 0xA4CF) ||
		(r >= 0xAC00 && r <= 0xD7A3) ||
		(r >= 0xF900 && r <= 0xFAFF) ||
		(r >= 0xFE30 && r <= 0xFE4F) ||
		(r >= 0xFF00 && r <= 0xFF60) ||
		(r >= 0xFFE0 && r <= 0xFFE6) ||
		(r >= 0x20000 && r <= 0x3FFFD)
}
