package solution

import (
	"errors"
	"math"
	"strconv"
)

type tokKind int

const (
	tNum tokKind = iota
	tOp
	tEOF
)

type token struct {
	kind tokKind
	op   byte
	val  float64
}

func tokenize(s string) ([]token, error) {
	var toks []token
	i := 0
	n := len(s)
	isDigit := func(c byte) bool { return c >= '0' && c <= '9' }
	for i < n {
		c := s[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			i++
		case c == '+' || c == '-' || c == '*' || c == '/' || c == '^' || c == '(' || c == ')':
			toks = append(toks, token{kind: tOp, op: c})
			i++
		case isDigit(c):
			start := i
			for i < n && isDigit(s[i]) {
				i++
			}
			if i < n && s[i] == '.' {
				i++
				for i < n && isDigit(s[i]) {
					i++
				}
			}
			v, err := strconv.ParseFloat(s[start:i], 64)
			if err != nil {
				return nil, errors.New("invalid number")
			}
			toks = append(toks, token{kind: tNum, val: v})
		case c == '.':
			start := i
			i++
			if i >= n || !isDigit(s[i]) {
				return nil, errors.New("invalid number")
			}
			for i < n && isDigit(s[i]) {
				i++
			}
			v, err := strconv.ParseFloat(s[start:i], 64)
			if err != nil {
				return nil, errors.New("invalid number")
			}
			toks = append(toks, token{kind: tNum, val: v})
		default:
			return nil, errors.New("invalid character")
		}
	}
	toks = append(toks, token{kind: tEOF})
	return toks, nil
}

type parser struct {
	toks []token
	pos  int
}

func (p *parser) peek() token { return p.toks[p.pos] }

func (p *parser) isOp(c byte) bool {
	t := p.toks[p.pos]
	return t.kind == tOp && t.op == c
}

func (p *parser) expr() (float64, error) {
	v, err := p.term()
	if err != nil {
		return 0, err
	}
	for p.isOp('+') || p.isOp('-') {
		op := p.peek().op
		p.pos++
		r, err := p.term()
		if err != nil {
			return 0, err
		}
		if op == '+' {
			v += r
		} else {
			v -= r
		}
	}
	return v, nil
}

func (p *parser) term() (float64, error) {
	v, err := p.unary()
	if err != nil {
		return 0, err
	}
	for p.isOp('*') || p.isOp('/') {
		op := p.peek().op
		p.pos++
		r, err := p.unary()
		if err != nil {
			return 0, err
		}
		if op == '*' {
			v *= r
		} else {
			if r == 0 {
				return 0, errors.New("division by zero")
			}
			v /= r
		}
	}
	return v, nil
}

func (p *parser) unary() (float64, error) {
	if p.isOp('+') {
		p.pos++
		return p.unary()
	}
	if p.isOp('-') {
		p.pos++
		v, err := p.unary()
		if err != nil {
			return 0, err
		}
		return -v, nil
	}
	return p.power()
}

func (p *parser) power() (float64, error) {
	b, err := p.primary()
	if err != nil {
		return 0, err
	}
	if p.isOp('^') {
		p.pos++
		e, err := p.unary()
		if err != nil {
			return 0, err
		}
		return math.Pow(b, e), nil
	}
	return b, nil
}

func (p *parser) primary() (float64, error) {
	t := p.peek()
	if t.kind == tNum {
		p.pos++
		return t.val, nil
	}
	if p.isOp('(') {
		p.pos++
		v, err := p.expr()
		if err != nil {
			return 0, err
		}
		if !p.isOp(')') {
			return 0, errors.New("expected )")
		}
		p.pos++
		return v, nil
	}
	return 0, errors.New("unexpected token")
}

// Eval parses and evaluates an arithmetic expression.
func Eval(s string) (float64, error) {
	toks, err := tokenize(s)
	if err != nil {
		return 0, err
	}
	p := &parser{toks: toks}
	v, err := p.expr()
	if err != nil {
		return 0, err
	}
	if p.peek().kind != tEOF {
		return 0, errors.New("unexpected trailing input")
	}
	return v, nil
}
