package solution

import "sort"

// Set is a set of integers stored as sorted, disjoint, maximally merged
// half-open intervals. The zero value is an empty set ready to use.
type Set struct {
	iv [][2]int
}

// replace substitutes s.iv[i:j] with pieces, building a fresh slice.
func (s *Set) replace(i, j int, pieces [][2]int) {
	n := make([][2]int, 0, len(s.iv)-(j-i)+len(pieces))
	n = append(n, s.iv[:i]...)
	n = append(n, pieces...)
	n = append(n, s.iv[j:]...)
	s.iv = n
}

// Add adds every integer in [lo, hi) to the set.
func (s *Set) Add(lo, hi int) {
	if lo >= hi {
		return
	}
	// First interval that overlaps or touches [lo, hi) from the left.
	i := sort.Search(len(s.iv), func(k int) bool { return s.iv[k][1] >= lo })
	// First interval starting strictly after hi (cannot touch or overlap).
	j := sort.Search(len(s.iv), func(k int) bool { return s.iv[k][0] > hi })
	newLo, newHi := lo, hi
	if i < j {
		if s.iv[i][0] < newLo {
			newLo = s.iv[i][0]
		}
		if s.iv[j-1][1] > newHi {
			newHi = s.iv[j-1][1]
		}
	}
	s.replace(i, j, [][2]int{{newLo, newHi}})
}

// Remove removes every integer in [lo, hi) from the set.
func (s *Set) Remove(lo, hi int) {
	if lo >= hi {
		return
	}
	// First interval whose end is beyond lo (overlaps the removal range).
	i := sort.Search(len(s.iv), func(k int) bool { return s.iv[k][1] > lo })
	// First interval starting at or after hi (unaffected).
	j := sort.Search(len(s.iv), func(k int) bool { return s.iv[k][0] >= hi })
	if i >= j {
		return
	}
	var pieces [][2]int
	if s.iv[i][0] < lo {
		pieces = append(pieces, [2]int{s.iv[i][0], lo})
	}
	if s.iv[j-1][1] > hi {
		pieces = append(pieces, [2]int{hi, s.iv[j-1][1]})
	}
	s.replace(i, j, pieces)
}

// Contains reports whether x is in the set.
func (s *Set) Contains(x int) bool {
	i := sort.Search(len(s.iv), func(k int) bool { return s.iv[k][1] > x })
	return i < len(s.iv) && s.iv[i][0] <= x
}

// Intervals returns a fresh copy of the canonical interval list.
func (s *Set) Intervals() [][2]int {
	out := make([][2]int, len(s.iv))
	copy(out, s.iv)
	return out
}
