package solution

import "errors"

var errInvalidDate = errors.New("invalid date")

func Count(from, to string, holidays []string) (int, error) {
	start, err := parseDate(from)
	if err != nil {
		return 0, err
	}
	end, err := parseDate(to)
	if err != nil {
		return 0, err
	}

	sign := 1
	if end < start {
		start, end = end, start
		sign = -1
	}

	var seen map[int]struct{}
	for _, h := range holidays {
		d, err := parseDate(h)
		if err != nil {
			return 0, err
		}
		if d >= start && d < end && d%7 < 5 {
			if seen == nil {
				seen = make(map[int]struct{})
			}
			seen[d] = struct{}{}
		}
	}

	total := weekdaysBefore(end) - weekdaysBefore(start) - len(seen)
	return sign * total, nil
}

func weekdaysBefore(day int) int {
	return (day/7)*5 + min(day%7, 5)
}

func parseDate(s string) (int, error) {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return 0, errInvalidDate
	}
	if !isDigit(s[0]) || !isDigit(s[1]) || !isDigit(s[2]) || !isDigit(s[3]) ||
		!isDigit(s[5]) || !isDigit(s[6]) ||
		!isDigit(s[8]) || !isDigit(s[9]) {
		return 0, errInvalidDate
	}

	y := int(s[0]-'0')*1000 + int(s[1]-'0')*100 + int(s[2]-'0')*10 + int(s[3]-'0')
	m := int(s[5]-'0')*10 + int(s[6]-'0')
	d := int(s[8]-'0')*10 + int(s[9]-'0')

	if m < 1 || m > 12 || d < 1 || d > daysInMonth(y, m) {
		return 0, errInvalidDate
	}

	return dayIndex(y, m, d), nil
}

func isDigit(b byte) bool {
	return b >= '0' && b <= '9'
}

func daysInMonth(y, m int) int {
	switch m {
	case 1, 3, 5, 7, 8, 10, 12:
		return 31
	case 4, 6, 9, 11:
		return 30
	case 2:
		if y%4 == 0 && (y%100 != 0 || y%400 == 0) {
			return 29
		}
		return 28
	default:
		return 0
	}
}

// dayIndex returns a non-negative serial day number for a proleptic Gregorian
// date (0000-01-01 to 9999-12-31) aligned so that dayIndex%7 is the weekday
// with 0=Monday, ..., 4=Friday, 5=Saturday, 6=Sunday.
func dayIndex(y, m, d int) int {
	if m <= 2 {
		y--
	}
	var era int
	if y >= 0 {
		era = y / 400
	} else {
		era = (y - 399) / 400
	}
	yoe := y - era*400
	var mp int
	if m > 2 {
		mp = m - 3
	} else {
		mp = m + 9
	}
	doy := (153*mp+2)/5 + d - 1
	doe := yoe*365 + yoe/4 - yoe/100 + doy
	return era*146097 + doe + 65
}
