package solution

import (
	"container/list"
	"time"
)

type entry struct {
	key    string
	value  string
	expiry time.Time
}

// Cache is an LRU cache with per-entry TTL driven by an injected clock.
// It is not safe for concurrent use.
type Cache struct {
	capacity int
	ttl      time.Duration
	now      func() time.Time
	ll       *list.List // front = MRU, back = LRU
	items    map[string]*list.Element
}

// New creates a cache. Callers guarantee capacity >= 1, ttl > 0, now != nil.
func New(capacity int, ttl time.Duration, now func() time.Time) *Cache {
	return &Cache{
		capacity: capacity,
		ttl:      ttl,
		now:      now,
		ll:       list.New(),
		items:    make(map[string]*list.Element, capacity),
	}
}

func isExpired(e *entry, t time.Time) bool {
	return !t.Before(e.expiry)
}

// Get returns the value for k if it has a live entry and marks it MRU.
// It does not change the entry's expiry.
func (c *Cache) Get(k string) (string, bool) {
	t := c.now()
	el, ok := c.items[k]
	if !ok {
		return "", false
	}
	e := el.Value.(*entry)
	if isExpired(e, t) {
		return "", false
	}
	c.ll.MoveToFront(el)
	return e.value, true
}

// Put inserts or updates k with value v.
func (c *Cache) Put(k, v string) {
	t := c.now()

	if el, ok := c.items[k]; ok {
		e := el.Value.(*entry)
		if !isExpired(e, t) {
			e.value = v
			e.expiry = t.Add(c.ttl)
			c.ll.MoveToFront(el)
			return
		}
		// Discard the expired entry for k.
		c.ll.Remove(el)
		delete(c.items, k)
	}

	if c.ll.Len() >= c.capacity {
		// Remove all expired entries.
		for el := c.ll.Front(); el != nil; {
			next := el.Next()
			e := el.Value.(*entry)
			if isExpired(e, t) {
				c.ll.Remove(el)
				delete(c.items, e.key)
			}
			el = next
		}
		// Still full: evict the LRU entry.
		if c.ll.Len() >= c.capacity {
			if back := c.ll.Back(); back != nil {
				e := back.Value.(*entry)
				c.ll.Remove(back)
				delete(c.items, e.key)
			}
		}
	}

	e := &entry{key: k, value: v, expiry: t.Add(c.ttl)}
	c.items[k] = c.ll.PushFront(e)
}

// Len returns the number of live entries at the current time.
func (c *Cache) Len() int {
	t := c.now()
	n := 0
	for el := c.ll.Front(); el != nil; el = el.Next() {
		if !isExpired(el.Value.(*entry), t) {
			n++
		}
	}
	return n
}
