package solution

import (
	"context"
	"errors"
	"sync"
)

// ErrBadLimit is returned by Map when limit is not positive.
var ErrBadLimit = errors.New("parmap: limit must be positive")

// Map calls f once per element of in, running up to limit calls concurrently,
// and returns the results in input order.
func Map[T, R any](ctx context.Context, in []T, limit int, f func(context.Context, T) (R, error)) ([]R, error) {
	if limit <= 0 {
		return nil, ErrBadLimit
	}
	if len(in) == 0 {
		return []R{}, nil
	}

	workCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	var (
		mu       sync.Mutex
		firstErr error
		wg       sync.WaitGroup
	)

	results := make([]R, len(in))
	sem := make(chan struct{}, limit)
	startedCh := make(chan bool)

	stopped := func() bool {
		return ctx.Err() != nil || workCtx.Err() != nil
	}

	started := 0
	for i := range in {
		if stopped() {
			break
		}
		// Acquire a concurrency slot, unless work is being stopped.
		select {
		case sem <- struct{}{}:
		case <-workCtx.Done():
		}
		if stopped() {
			// We may have acquired a slot; release it if so.
			select {
			case <-sem:
			default:
			}
			break
		}

		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			defer func() { <-sem }()

			if stopped() {
				startedCh <- false
				return
			}
			startedCh <- true

			r, err := f(workCtx, in[i])
			if err != nil {
				mu.Lock()
				if firstErr == nil {
					firstErr = err
				}
				mu.Unlock()
				cancel()
				return
			}
			results[i] = r
		}(i)

		// Wait until the goroutine for index i has committed to starting
		// (or declined), so calls begin in increasing index order.
		if !<-startedCh {
			break
		}
		started++
	}

	wg.Wait()
	cancel()

	mu.Lock()
	err := firstErr
	mu.Unlock()

	if err != nil {
		return nil, err
	}
	if started < len(in) {
		if cerr := ctx.Err(); cerr != nil {
			return nil, cerr
		}
		if cerr := workCtx.Err(); cerr != nil {
			return nil, cerr
		}
		return nil, context.Canceled
	}
	return results, nil
}
