```go
package solution

import "time"

type entry struct {
	key     string
	val     string
	expiry  time.Time
	prev    *entry
	next    *entry
	heapIdx int
}

type Cache struct {
	capacity int
	ttl      time.Duration
	now      func() time.Time

	entries map[string]*entry
	head    *entry // MRU
	tail    *entry // LRU
	heap    []*entry
}

func New(capacity int, ttl time.Duration, now func() time.Time) *Cache {
	return &Cache{
		capacity: capacity,
		ttl:      ttl,
		now:      now,
		entries:  make(map[string]*entry),
	}
}

func (c *Cache) Get(k string) (string, bool) {
	e, ok := c.entries[k]
	if !ok {
		return "", false
	}
	if !c.now().Before(e.expiry) {
		c.removeEntry(e)
		return "", false
	}
	c.moveToFront(e)
	return e.val, true
}

func (c *Cache) Put(k, v string) {
	now := c.now()
	expiry := now.Add(c.ttl)

	if e, ok := c.entries[k]; ok {
		e.val = v
		e.expiry = expiry
		c.heapFix(e.heapIdx)
		c.moveToFront(e)
		return
	}

	if len(c.entries) == c.capacity {
		c.purgeExpired(now)
		if len(c.entries) == c.capacity {
			c.removeEntry(c.tail)
		}
	}

	e := &entry{
		key:    k,
		val:    v,
		expiry: expiry,
	}
	c.entries[k] = e
	c.pushFront(e)
	c.heapPush(e)
}

func (c *Cache) Len() int {
	if len(c.entries) == 0 {
		return 0
	}
	c.purgeExpired(c.now())
	return len(c.entries)
}

func (c *Cache) purgeExpired(now time.Time) {
	for len(c.heap) > 0 && !now.Before(c.heap[0].expiry) {
		c.removeEntry(c.heap[0])
	}
}

func (c *Cache) removeEntry(e *entry) {
	delete(c.entries, e.key)
	c.removeList(e)
	c.heapRemove(e.heapIdx)
}

func (c *Cache) pushFront(e *entry) {
	e.prev = nil
	e.next = c.head
	if c.head != nil {
		c.head.prev = e
	} else {
		c.tail = e
	}
	c.head = e
}

func (c *Cache) removeList(e *entry) {
	if e.prev != nil {
		e.prev.next = e.next
	} else {
		c.head = e.next
	}
	if e.next != nil {
		e.next.prev = e.prev
	} else {
		c.tail = e.prev
	}
	e.prev = nil
	e.next = nil
}

func (c *Cache) moveToFront(e *entry) {
	if c.head == e {
		return
	}
	c.removeList(e)
	c.pushFront(e)
}

func (c *Cache) heapSwap(i, j int) {
	c.heap[i], c.heap[j] = c.heap[j], c.heap[i]
	c.heap[i].heapIdx = i
	c.heap[j].heapIdx = j
}

func (c *Cache) heapUp(i int) {
	for i > 0 {
		parent := (i - 1) / 2
		if !c.heap[i].expiry.Before(c.heap[parent].expiry) {
			break
		}
		c.heapSwap(i, parent)
		i = parent
	}
}

func (c *Cache) heapDown(i int) bool {
	n := len(c.heap)
	i0 := i
	for {
		left := 2*i + 1
		if left >= n || left < 0 {
			break
		}
		smallest := left
		if right := left + 1; right < n && c.heap[right].expiry.Before(c.heap[left].expiry) {
			smallest = right
		}
		if !c.heap[smallest].expiry.Before(c.heap[i].expiry) {
			break
		}
		c.heapSwap(i, smallest)
		i = smallest
	}
	return i > i0
}

func (c *Cache) heapPush(e *entry) {
	e.heapIdx = len(c.heap)
	c.heap = append(c.heap, e)
	c.heapUp(e.heapIdx)
}

func (c *Cache) heapFix(i int) {
	if !c.heapDown(i) {
		c.heapUp(i)
	}
}

func (c *Cache) heapRemove(i int) {
	last := len(c.heap) - 1
	if i != last {
		c.heapSwap(i, last)
	}
	e := c.heap[last]
	c.heap[last] = nil
	c.heap = c.heap[:last]
	e.heapIdx = -1
	if i != last {
		c.heapFix(i)
	}
}
