```go
package solution

import (
	"slices"
	"strings"
)

type CycleError struct {
	Cycle []string
}

func (e *CycleError) Error() string {
	if e == nil || len(e.Cycle) == 0 {
		return "dependency cycle detected"
	}
	var b strings.Builder
	b.WriteString("dependency cycle: ")
	for i, node := range e.Cycle {
		if i > 0 {
			b.WriteString(" -> ")
		}
		b.WriteString(node)
	}
	b.WriteString(" -> ")
	b.WriteString(e.Cycle[0])
	return b.String()
}

func Order(deps map[string][]string) ([]string, error) {
	if len(deps) == 0 {
		return []string{}, nil
	}

	nodeID := make(map[string]int, len(deps))
	for k, list := range deps {
		nodeID[k] = 0
		for _, d := range list {
			nodeID[d] = 0
		}
	}

	n := len(nodeID)
	nodes := make([]string, 0, n)
	for name := range nodeID {
		nodes = append(nodes, name)
	}
	slices.Sort(nodes)
	for i, name := range nodes {
		nodeID[name] = i
	}

	depAdj := make([][]int, n)
	revAdj := make([][]int, n)
	inDeg := make([]int, n)
	hasSelfLoop := make([]bool, n)

	for k, list := range deps {
		if len(list) == 0 {
			continue
		}
		u := nodeID[k]
		adj := make([]int, len(list))
		for i, d := range list {
			adj[i] = nodeID[d]
		}
		slices.Sort(adj)
		adj = slices.Compact(adj)
		depAdj[u] = adj
		inDeg[u] = len(adj)
		for _, v := range adj {
			if v == u {
				hasSelfLoop[u] = true
			}
			revAdj[v] = append(revAdj[v], u)
		}
	}

	h := make(intHeap, 0, n)
	for u := 0; u < n; u++ {
		if inDeg[u] == 0 {
			h = append(h, u)
		}
	}

	order := make([]string, 0, n)
	for len(h) > 0 {
		d := h.pop()
		order = append(order, nodes[d])
		for _, u := range revAdj[d] {
			inDeg[u]--
			if inDeg[u] == 0 {
				h.push(u)
			}
		}
	}

	if len(order) == n {
		return order, nil
	}

	cycle := findCanonicalCycle(nodes, depAdj, revAdj, hasSelfLoop)
	return nil, &CycleError{Cycle: cycle}
}

func findCanonicalCycle(nodes []string, depAdj, revAdj [][]int, hasSelfLoop []bool) []string {
	n := len(nodes)

	// Iterative Kosaraju's algorithm to compute strongly connected components.
	visited := make([]bool, n)
	finishOrder := make([]int, 0, n)
	type frame struct {
		u   int
		idx int
	}
	stack := make([]frame, 0, n)
	for start := 0; start < n; start++ {
		if visited[start] {
			continue
		}
		visited[start] = true
		stack = append(stack, frame{u: start, idx: 0})
		for len(stack) > 0 {
			top := &stack[len(stack)-1]
			adj := depAdj[top.u]
			if top.idx < len(adj) {
				v := adj[top.idx]
				top.idx++
				if !visited[v] {
					visited[v] = true
					stack = append(stack, frame{u: v, idx: 0})
				}
			} else {
				finishOrder = append(finishOrder, top.u)
				stack = stack[:len(stack)-1]
			}
		}
	}

	scc := make([]int, n)
	for i := range scc {
		scc[i] = -1
	}
	var sccSize []int
	bfsQueue := make([]int, 0, n)
	for i := n - 1; i >= 0; i-- {
		start := finishOrder[i]
		if scc[start] != -1 {
			continue
		}
		id := len(sccSize)
		scc[start] = id
		size := 0
		bfsQueue = append(bfsQueue[:0], start)
		for head := 0; head < len(bfsQueue); head++ {
			u := bfsQueue[head]
			size++
			for _, v := range revAdj[u] {
				if scc[v] == -1 {
					scc[v] = id
					bfsQueue = append(bfsQueue, v)
				}
			}
		}
		sccSize = append(sccSize, size)
	}

	n0 := -1
	for u := 0; u < n; u++ {
		if hasSelfLoop[u] || sccSize[scc[u]] >= 2 {
			n0 = u
			break
		}
	}
	if hasSelfLoop[n0] {
		return []string{nodes[n0]}
	}

	targetSCC := scc[n0]
	sccNodes := make([]int, 0, sccSize[targetSCC])
	for u := 0; u < n; u++ {
		if scc[u] == targetSCC {
			sccNodes = append(sccNodes, u)
		}
	}

	hasEdgeToN0 := make([]bool, n)
	for _, u := range revAdj[n0] {
		hasEdgeToN0[u] = true
	}

	inPath := make([]bool, n)
	dead := make([]bool, n)
	validGen := make([]int, n)
	treeHead := make([]int, n)
	treeNext := make([]int, n)
	curGen := 0
	brkStack := make([]int, 0, sccSize[targetSCC])

	rebuildTree := func() {
		curGen++
		validGen[n0] = curGen
		treeHead[n0] = -1
		bfsQueue = append(bfsQueue[:0], n0)
		for head := 0; head < len(bfsQueue); head++ {
			x := bfsQueue[head]
			for _, y := range revAdj[x] {
				if scc[y] == targetSCC && !inPath[y] && !dead[y] && validGen[y] != curGen {
					validGen[y] = curGen
					treeHead[y] = -1
					treeNext[y] = treeHead[x]
					treeHead[x] = y
					bfsQueue = append(bfsQueue, y)
				}
			}
		}
		alive := sccNodes[:0]
		for _, x := range sccNodes {
			if inPath[x] || dead[x] {
				continue
			}
			if validGen[x] != curGen {
				dead[x] = true
				continue
			}
			alive = append(alive, x)
		}
		sccNodes = alive
	}

	markBroken := func(root int) {
		if validGen[root] != curGen {
			return
		}
		validGen[root] = 0
		brkStack = append(brkStack[:0], root)
		for len(brkStack) > 0 {
			x := brkStack[len(brkStack)-1]
			brkStack = brkStack[:len(brkStack)-1]
			for c := treeHead[x]; c != -1; c = treeNext[c] {
				if validGen[c] == curGen {
					validGen[c] = 0
					brkStack = append(brkStack, c)
				}
			}
		}
	}

	inPath[n0] = true
	rebuildTree()

	path := []string{nodes[n0]}
	u := n0
	for {
		if hasEdgeToN0[u] {
			return path
		}
		rebuilt := false
		nextNode := -1
		adj := depAdj[u]
		for idx, v := range adj {
			if scc[v] != targetSCC || inPath[v] || dead[v] {
				continue
			}
			if validGen[v] == curGen {
				nextNode = v
				break
			}
			if !rebuilt {
				hasAnother := false
				for _, w := range adj[idx+1:] {
					if scc[w] == targetSCC && !inPath[w] && !dead[w] {
						hasAnother = true
						break
					}
				}
				if !hasAnother {
					nextNode = v
					break
				}
				rebuildTree()
				rebuilt = true
				if validGen[v] == curGen {
					nextNode = v
					break
				}
			}
		}
		inPath[nextNode] = true
		markBroken(nextNode)
		path = append(path, nodes[nextNode])
		u = nextNode
	}
}

type intHeap []int

func (h *intHeap) push(x int) {
	*h = append(*h, x)
	s := *h
	i := len(s) - 1
	for i > 0 {
		p := (i - 1) / 2
		if s[p] <= s[i] {
			break
		}
		s[p], s[i] = s[i], s[p]
		i = p
	}
}

func (h *intHeap) pop() int {
	s := *h
	top := s[0]
	last := len(s) - 1
	s[0] = s[last]
	s = s[:last]
	*h = s
	i := 0
	for {
		l := 2*i + 1
		if l >= last {
			break
		}
		smallest := l
		if r := l + 1; r < last && s[r] < s[l] {
			smallest = r
		}
		if s[i] <= s[smallest] {
			break
		}
		s[i], s[smallest] = s[smallest], s[i]
		i = smallest
	}
	return top
}
