package solution

import (
	"math"
	"sync"
	"time"
)

// Limiter is a token-bucket rate limiter driven by an injected clock.
type Limiter struct {
	mu        sync.Mutex
	rate      float64
	burst     int
	tokens    float64
	watermark time.Time
	now       func() time.Time
}

// New creates a limiter whose bucket starts full.
func New(rate float64, burst int, now func() time.Time) *Limiter {
	return &Limiter{
		rate:      rate,
		burst:     burst,
		tokens:    float64(burst),
		watermark: now(),
		now:       now,
	}
}

// refill must be called with l.mu held.
func (l *Limiter) refill() {
	t := l.now()
	if !t.After(l.watermark) {
		return
	}
	elapsed := t.Sub(l.watermark).Seconds()
	l.watermark = t
	tokens := l.tokens + l.rate*elapsed
	if b := float64(l.burst); tokens > b || math.IsNaN(tokens) {
		tokens = b
	}
	l.tokens = tokens
}

// Allow reports whether one token is available and consumes it if so.
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// AllowN reports whether n tokens are available and consumes them if so.
func (l *Limiter) AllowN(n int) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill()
	if n > l.burst {
		return false
	}
	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		return true
	}
	return false
}

// Delay returns how long until n tokens will be available, without consuming.
func (l *Limiter) Delay(n int) time.Duration {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill()
	if n > l.burst {
		return time.Duration(-1)
	}
	need := float64(n)
	if l.tokens >= need {
		return 0
	}
	ns := math.Ceil((need - l.tokens) / l.rate * 1e9)
	if ns >= float64(math.MaxInt64) {
		return time.Duration(math.MaxInt64)
	}
	if ns < 1 {
		ns = 1
	}
	return time.Duration(int64(ns))
}
