package solution

// Set represents a set of integers stored as a treap of disjoint,
// non-adjacent half-open intervals [lo, hi).
// The zero value is an empty set ready to use.
type Set struct {
	root *node
	rng  uint64
}

type node struct {
	lo, hi int
	prio   uint64
	size   int
	left   *node
	right  *node
}

func (n *node) update() {
	size := 1
	if n.left != nil {
		size += n.left.size
	}
	if n.right != nil {
		size += n.right.size
	}
	n.size = size
}

func (s *Set) nextRand() uint64 {
	s.rng += 0x9e3779b97f4a7c15
	z := s.rng
	z = (z ^ (z >> 30)) * 0xbf58476d1ce4e5b9
	z = (z ^ (z >> 27)) * 0x94d049bb133111eb
	return z ^ (z >> 31)
}

// Add inserts all integers in the half-open interval [lo, hi) into the set.
func (s *Set) Add(lo, hi int) {
	if lo >= hi {
		return
	}

	left, rest := splitByHiLess(s.root, lo)
	mid, right := splitByLoLessEq(rest, hi)

	var merged *node
	if mid != nil {
		if first := minNode(mid); first.lo < lo {
			lo = first.lo
		}
		if last := maxNode(mid); last.hi > hi {
			hi = last.hi
		}
		mid.lo = lo
		mid.hi = hi
		mid.prio = s.nextRand()
		mid.size = 1
		mid.left = nil
		mid.right = nil
		merged = mid
	} else {
		merged = &node{
			lo:   lo,
			hi:   hi,
			prio: s.nextRand(),
			size: 1,
		}
	}

	s.root = merge(merge(left, merged), right)
}

// Remove deletes all integers in the half-open interval [lo, hi) from the set.
func (s *Set) Remove(lo, hi int) {
	if lo >= hi || s.root == nil {
		return
	}

	left, rest := splitByHiLessEq(s.root, lo)
	mid, right := splitByLoLess(rest, hi)

	if mid == nil {
		s.root = merge(left, right)
		return
	}

	firstLo := minNode(mid).lo
	lastHi := maxNode(mid).hi

	if firstLo < lo {
		left = merge(left, &node{
			lo:   firstLo,
			hi:   lo,
			prio: s.nextRand(),
			size: 1,
		})
	}
	if lastHi > hi {
		right = merge(&node{
			lo:   hi,
			hi:   lastHi,
			prio: s.nextRand(),
			size: 1,
		}, right)
	}

	s.root = merge(left, right)
}

// Contains reports whether x is in the set.
func (s *Set) Contains(x int) bool {
	for n := s.root; n != nil; {
		if x < n.lo {
			n = n.left
		} else if x >= n.hi {
			n = n.right
		} else {
			return true
		}
	}
	return false
}

// Intervals returns a fresh slice containing the canonical list of
// half-open intervals [lo, hi) representing the set.
func (s *Set) Intervals() [][2]int {
	if s.root == nil {
		return nil
	}
	res := make([][2]int, 0, s.root.size)
	appendInOrder(s.root, &res)
	return res
}

func appendInOrder(n *node, dst *[][2]int) {
	if n == nil {
		return
	}
	appendInOrder(n.left, dst)
	*dst = append(*dst, [2]int{n.lo, n.hi})
	appendInOrder(n.right, dst)
}

func minNode(n *node) *node {
	for n.left != nil {
		n = n.left
	}
	return n
}

func maxNode(n *node) *node {
	for n.right != nil {
		n = n.right
	}
	return n
}

// splitByHiLess splits n into nodes with hi < lo and nodes with hi >= lo.
func splitByHiLess(n *node, lo int) (left, right *node) {
	if n == nil {
		return nil, nil
	}
	if n.hi < lo {
		var r *node
		n.right, r = splitByHiLess(n.right, lo)
		n.update()
		return n, r
	}
	var l *node
	l, n.left = splitByHiLess(n.left, lo)
	n.update()
	return l, n
}

// splitByHiLessEq splits n into nodes with hi <= lo and nodes with hi > lo.
func splitByHiLessEq(n *node, lo int) (left, right *node) {
	if n == nil {
		return nil, nil
	}
	if n.hi <= lo {
		var r *node
		n.right, r = splitByHiLessEq(n.right, lo)
		n.update()
		return n, r
	}
	var l *node
	l, n.left = splitByHiLessEq(n.left, lo)
	n.update()
	return l, n
}

// splitByLoLess splits n into nodes with lo < hi and nodes with lo >= hi.
func splitByLoLess(n *node, hi int) (left, right *node) {
	if n == nil {
		return nil, nil
	}
	if n.lo < hi {
		var r *node
		n.right, r = splitByLoLess(n.right, hi)
		n.update()
		return n, r
	}
	var l *node
	l, n.left = splitByLoLess(n.left, hi)
	n.update()
	return l, n
}

// splitByLoLessEq splits n into nodes with lo <= hi and nodes with lo > hi.
func splitByLoLessEq(n *node, hi int) (left, right *node) {
	if n == nil {
		return nil, nil
	}
	if n.lo <= hi {
		var r *node
		n.right, r = splitByLoLessEq(n.right, hi)
		n.update()
		return n, r
	}
	var l *node
	l, n.left = splitByLoLessEq(n.left, hi)
	n.update()
	return l, n
}

func merge(a, b *node) *node {
	if a == nil {
		return b
	}
	if b == nil {
		return a
	}
	if a.prio > b.prio {
		a.right = merge(a.right, b)
		a.update()
		return a
	}
	b.left = merge(a, b.left)
	b.update()
	return b
}
