package solution

import (
	"errors"
	"strings"
)

type version struct {
	major, minor, patch string
	pre                 []string
}

func isDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func isNumericIdent(s string) bool {
	if !isDigits(s) {
		return false
	}
	if len(s) > 1 && s[0] == '0' {
		return false
	}
	return true
}

func isIdentChars(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= '0' && c <= '9':
		case c >= 'a' && c <= 'z':
		case c >= 'A' && c <= 'Z':
		case c == '-':
		default:
			return false
		}
	}
	return true
}

func parse(s string) (*version, error) {
	if strings.HasPrefix(s, "v") {
		s = s[1:]
	}
	if s == "" {
		return nil, errors.New("empty version")
	}
	rest := s
	if idx := strings.IndexByte(rest, '+'); idx >= 0 {
		build := rest[idx+1:]
		rest = rest[:idx]
		if build == "" {
			return nil, errors.New("empty build metadata")
		}
		for _, id := range strings.Split(build, ".") {
			if !isIdentChars(id) {
				return nil, errors.New("invalid build identifier")
			}
		}
	}
	var pre []string
	if idx := strings.IndexByte(rest, '-'); idx >= 0 {
		preStr := rest[idx+1:]
		rest = rest[:idx]
		if preStr == "" {
			return nil, errors.New("empty pre-release")
		}
		for _, id := range strings.Split(preStr, ".") {
			if !isIdentChars(id) {
				return nil, errors.New("invalid pre-release identifier")
			}
			if isDigits(id) && !isNumericIdent(id) {
				return nil, errors.New("leading zero in numeric pre-release identifier")
			}
			pre = append(pre, id)
		}
	}
	parts := strings.Split(rest, ".")
	if len(parts) != 3 {
		return nil, errors.New("version core must have three components")
	}
	for _, p := range parts {
		if !isNumericIdent(p) {
			return nil, errors.New("invalid numeric identifier in version core")
		}
	}
	return &version{major: parts[0], minor: parts[1], patch: parts[2], pre: pre}, nil
}

// compareNum compares two valid numeric identifiers (no leading zeros).
func compareNum(a, b string) int {
	if len(a) != len(b) {
		if len(a) < len(b) {
			return -1
		}
		return 1
	}
	return strings.Compare(a, b)
}

func comparePreIdent(a, b string) int {
	an, bn := isDigits(a), isDigits(b)
	switch {
	case an && bn:
		return compareNum(a, b)
	case an:
		return -1
	case bn:
		return 1
	default:
		return strings.Compare(a, b)
	}
}

// Compare compares two semantic version strings.
func Compare(a, b string) (int, error) {
	va, err := parse(a)
	if err != nil {
		return 0, err
	}
	vb, err := parse(b)
	if err != nil {
		return 0, err
	}
	if c := compareNum(va.major, vb.major); c != 0 {
		return c, nil
	}
	if c := compareNum(va.minor, vb.minor); c != 0 {
		return c, nil
	}
	if c := compareNum(va.patch, vb.patch); c != 0 {
		return c, nil
	}
	la, lb := len(va.pre), len(vb.pre)
	if la == 0 && lb == 0 {
		return 0, nil
	}
	if la == 0 {
		return 1, nil
	}
	if lb == 0 {
		return -1, nil
	}
	for i := 0; i < la && i < lb; i++ {
		if c := comparePreIdent(va.pre[i], vb.pre[i]); c != 0 {
			return c, nil
		}
	}
	switch {
	case la < lb:
		return -1, nil
	case la > lb:
		return 1, nil
	}
	return 0, nil
}
