package solution

import (
	"container/heap"
	"sort"
	"strings"
)

// CycleError reports a dependency cycle in canonical form.
type CycleError struct {
	Cycle []string
}

func (e *CycleError) Error() string {
	if e == nil || len(e.Cycle) == 0 {
		return "dependency cycle detected"
	}
	parts := make([]string, 0, len(e.Cycle)+1)
	for _, s := range e.Cycle {
		parts = append(parts, "\""+s+"\"")
	}
	parts = append(parts, "\""+e.Cycle[0]+"\"")
	return "dependency cycle detected: " + strings.Join(parts, " -> ")
}

type intHeap []int

func (h intHeap) Len() int            { return len(h) }
func (h intHeap) Less(i, j int) bool  { return h[i] < h[j] }
func (h intHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *intHeap) Push(x interface{}) { *h = append(*h, x.(int)) }
func (h *intHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

// Order returns the deterministic topological order of the nodes in deps,
// or a *CycleError describing the canonical cycle.
func Order(deps map[string][]string) ([]string, error) {
	// Collect node set.
	set := make(map[string]struct{})
	for a, ds := range deps {
		set[a] = struct{}{}
		for _, d := range ds {
			set[d] = struct{}{}
		}
	}
	names := make([]string, 0, len(set))
	for s := range set {
		names = append(names, s)
	}
	sort.Strings(names)
	n := len(names)
	if n == 0 {
		return make([]string, 0), nil
	}
	id := make(map[string]int, n)
	for i, s := range names {
		id[s] = i
	}

	// Adjacency: adj[a] = sorted unique dependency ids (edges a -> d).
	adj := make([][]int, n)
	for a, ds := range deps {
		ai := id[a]
		seen := make(map[int]struct{}, len(ds))
		lst := make([]int, 0, len(ds))
		for _, d := range ds {
			di := id[d]
			if _, ok := seen[di]; ok {
				continue
			}
			seen[di] = struct{}{}
			lst = append(lst, di)
		}
		sort.Ints(lst)
		adj[ai] = lst
	}
	// Reverse adjacency: rev[d] = nodes a with edge a -> d.
	rev := make([][]int, n)
	for a := 0; a < n; a++ {
		for _, d := range adj[a] {
			rev[d] = append(rev[d], a)
		}
	}

	// Kahn's algorithm with min-heap.
	indeg := make([]int, n)
	h := &intHeap{}
	for a := 0; a < n; a++ {
		indeg[a] = len(adj[a])
		if indeg[a] == 0 {
			*h = append(*h, a)
		}
	}
	heap.Init(h)
	order := make([]string, 0, n)
	for h.Len() > 0 {
		u := heap.Pop(h).(int)
		order = append(order, names[u])
		for _, a := range rev[u] {
			indeg[a]--
			if indeg[a] == 0 {
				heap.Push(h, a)
			}
		}
	}
	if len(order) == n {
		return order, nil
	}

	// Cycle exists: find SCCs (iterative Tarjan).
	index := make([]int, n)
	low := make([]int, n)
	onStack := make([]bool, n)
	compSize := make([]int, n)
	comp := make([]int, n)
	for i := range index {
		index[i] = -1
	}
	stack := make([]int, 0, n)
	type frame struct{ v, ei int }
	counter := 0
	compCount := 0
	for s := 0; s < n; s++ {
		if index[s] != -1 {
			continue
		}
		index[s] = counter
		low[s] = counter
		counter++
		stack = append(stack, s)
		onStack[s] = true
		call := []frame{{s, 0}}
		for len(call) > 0 {
			top := &call[len(call)-1]
			v := top.v
			if top.ei < len(adj[v]) {
				w := adj[v][top.ei]
				top.ei++
				if index[w] == -1 {
					index[w] = counter
					low[w] = counter
					counter++
					stack = append(stack, w)
					onStack[w] = true
					call = append(call, frame{w, 0})
				} else if onStack[w] {
					if index[w] < low[v] {
						low[v] = index[w]
					}
				}
				continue
			}
			call = call[:len(call)-1]
			if low[v] == index[v] {
				size := 0
				for {
					x := stack[len(stack)-1]
					stack = stack[:len(stack)-1]
					onStack[x] = false
					comp[x] = compCount
					size++
					if x == v {
						break
					}
				}
				compSize[compCount] = size
				compCount++
			}
			if len(call) > 0 {
				p := call[len(call)-1].v
				if low[v] < low[p] {
					low[p] = low[v]
				}
			}
		}
	}

	hasEdge := func(a, b int) bool {
		l := adj[a]
		i := sort.SearchInts(l, b)
		return i < len(l) && l[i] == b
	}

	n0 := -1
	for v := 0; v < n; v++ {
		if compSize[comp[v]] > 1 || hasEdge(v, v) {
			n0 = v
			break
		}
	}
	if n0 == -1 {
		// Should be unreachable; fall back to a generic error.
		return nil, &CycleError{Cycle: nil}
	}

	// Greedy construction of the lexicographically smallest simple cycle.
	inPath := make([]bool, n)
	inPath[n0] = true
	path := []int{n0}
	cur := n0
	canReach := make([]bool, n)
	queue := make([]int, 0, n)
	for {
		if hasEdge(cur, n0) {
			break
		}
		// Compute nodes (not in path) that can reach n0 using only nodes not in path.
		for i := range canReach {
			canReach[i] = false
		}
		queue = queue[:0]
		queue = append(queue, n0)
		for qi := 0; qi < len(queue); qi++ {
			x := queue[qi]
			for _, u := range rev[x] {
				if inPath[u] || canReach[u] {
					continue
				}
				canReach[u] = true
				queue = append(queue, u)
			}
		}
		next := -1
		for _, w := range adj[cur] {
			if !inPath[w] && canReach[w] {
				next = w
				break
			}
		}
		if next == -1 {
			// Should be unreachable given n0 lies on a cycle.
			break
		}
		inPath[next] = true
		path = append(path, next)
		cur = next
	}

	cycle := make([]string, len(path))
	for i, v := range path {
		cycle[i] = names[v]
	}
	return nil, &CycleError{Cycle: cycle}
}
