package solution

import (
	"errors"
	"strings"
)

var errInvalidVersion = errors.New("invalid semantic version")

type preID struct {
	val     string
	numeric bool
}

type version struct {
	major string
	minor string
	patch string
	pre   []preID
}

// Compare parses two Semantic Versioning 2.0.0 strings and returns -1 if a < b,
// 0 if a == b, and 1 if a > b according to SemVer precedence rules.
func Compare(a, b string) (int, error) {
	va, err := parseVersion(a)
	if err != nil {
		return 0, err
	}
	vb, err := parseVersion(b)
	if err != nil {
		return 0, err
	}

	if c := cmpNumeric(va.major, vb.major); c != 0 {
		return c, nil
	}
	if c := cmpNumeric(va.minor, vb.minor); c != 0 {
		return c, nil
	}
	if c := cmpNumeric(va.patch, vb.patch); c != 0 {
		return c, nil
	}

	aHasPre := len(va.pre) > 0
	bHasPre := len(vb.pre) > 0
	if !aHasPre && !bHasPre {
		return 0, nil
	}
	if aHasPre && !bHasPre {
		return -1, nil
	}
	if !aHasPre && bHasPre {
		return 1, nil
	}

	minLen := min(len(va.pre), len(vb.pre))
	for i := 0; i < minLen; i++ {
		pa, pb := va.pre[i], vb.pre[i]
		if pa.numeric && pb.numeric {
			if c := cmpNumeric(pa.val, pb.val); c != 0 {
				return c, nil
			}
		} else if pa.numeric != pb.numeric {
			if pa.numeric {
				return -1, nil
			}
			return 1, nil
		} else {
			if c := strings.Compare(pa.val, pb.val); c != 0 {
				return c, nil
			}
		}
	}

	if len(va.pre) < len(vb.pre) {
		return -1, nil
	}
	if len(va.pre) > len(vb.pre) {
		return 1, nil
	}
	return 0, nil
}

func parseVersion(s string) (version, error) {
	if len(s) == 0 {
		return version{}, errInvalidVersion
	}
	if s[0] == 'v' {
		s = s[1:]
	}

	major, rest, ok := strings.Cut(s, ".")
	if !ok || !isValidNumeric(major) {
		return version{}, errInvalidVersion
	}

	minor, rest, ok := strings.Cut(rest, ".")
	if !ok || !isValidNumeric(minor) {
		return version{}, errInvalidVersion
	}

	var patch string
	if patchEnd := strings.IndexAny(rest, "-+"); patchEnd == -1 {
		patch = rest
		rest = ""
	} else {
		patch = rest[:patchEnd]
		rest = rest[patchEnd:]
	}
	if !isValidNumeric(patch) {
		return version{}, errInvalidVersion
	}

	var pre []preID
	if len(rest) > 0 && rest[0] == '-' {
		rest = rest[1:]
		preStr := rest
		if plusIdx := strings.IndexByte(rest, '+'); plusIdx != -1 {
			preStr = rest[:plusIdx]
			rest = rest[plusIdx:]
		} else {
			rest = ""
		}
		var err error
		pre, err = parsePrerelease(preStr)
		if err != nil {
			return version{}, err
		}
	}

	if len(rest) > 0 {
		if rest[0] != '+' || !isValidBuild(rest[1:]) {
			return version{}, errInvalidVersion
		}
	}

	return version{
		major: major,
		minor: minor,
		patch: patch,
		pre:   pre,
	}, nil
}

func isValidNumeric(s string) bool {
	if len(s) == 0 {
		return false
	}
	if len(s) > 1 && s[0] == '0' {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func isIdentChar(c byte) bool {
	return (c >= '0' && c <= '9') ||
		(c >= 'A' && c <= 'Z') ||
		(c >= 'a' && c <= 'z') ||
		c == '-'
}

func parsePrerelease(s string) ([]preID, error) {
	if len(s) == 0 {
		return nil, errInvalidVersion
	}
	ids := make([]preID, 0, strings.Count(s, ".")+1)
	for {
		var part string
		var hasMore bool
		part, s, hasMore = strings.Cut(s, ".")
		if len(part) == 0 {
			return nil, errInvalidVersion
		}
		allDigits := true
		for i := 0; i < len(part); i++ {
			c := part[i]
			if c >= '0' && c <= '9' {
				continue
			}
			if (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || c == '-' {
				allDigits = false
				continue
			}
			return nil, errInvalidVersion
		}
		if allDigits && len(part) > 1 && part[0] == '0' {
			return nil, errInvalidVersion
		}
		ids = append(ids, preID{val: part, numeric: allDigits})
		if !hasMore {
			break
		}
	}
	return ids, nil
}

func isValidBuild(s string) bool {
	if len(s) == 0 {
		return false
	}
	for {
		var part string
		var hasMore bool
		part, s, hasMore = strings.Cut(s, ".")
		if len(part) == 0 {
			return false
		}
		for i := 0; i < len(part); i++ {
			if !isIdentChar(part[i]) {
				return false
			}
		}
		if !hasMore {
			break
		}
	}
	return true
}

func cmpNumeric(a, b string) int {
	if len(a) != len(b) {
		if len(a) < len(b) {
			return -1
		}
		return 1
	}
	return strings.Compare(a, b)
}
