package solution

import "strings"

type unit struct {
	text  string
	width int
	word  int
}

func runeWidth(r rune) int {
	switch {
	case r >= 0x1100 && r <= 0x115F,
		r >= 0x2E80 && r <= 0xA4CF,
		r >= 0xAC00 && r <= 0xD7A3,
		r >= 0xF900 && r <= 0xFAFF,
		r >= 0xFE30 && r <= 0xFE4F,
		r >= 0xFF00 && r <= 0xFF60,
		r >= 0xFFE0 && r <= 0xFFE6,
		r >= 0x20000 && r <= 0x3FFFD:
		return 2
	}
	return 1
}

// Wrap breaks s into lines whose display width is at most width.
func Wrap(s string, width int) []string {
	lines := []string{}
	for _, para := range strings.Split(s, "\n") {
		lines = append(lines, wrapParagraph(para, width)...)
	}
	return lines
}

func wrapParagraph(p string, width int) []string {
	words := strings.FieldsFunc(p, func(r rune) bool { return r == ' ' })
	if len(words) == 0 {
		return []string{""}
	}

	var units []unit
	for wi, w := range words {
		var narrow []rune
		flush := func() {
			if len(narrow) == 0 {
				return
			}
			for start := 0; start < len(narrow); start += width {
				end := start + width
				if end > len(narrow) {
					end = len(narrow)
				}
				units = append(units, unit{text: string(narrow[start:end]), width: end - start, word: wi})
			}
			narrow = narrow[:0]
		}
		for _, r := range w {
			if runeWidth(r) == 2 {
				flush()
				units = append(units, unit{text: string(r), width: 2, word: wi})
			} else {
				narrow = append(narrow, r)
			}
		}
		flush()
	}

	var lines []string
	var cur strings.Builder
	curW := 0
	empty := true
	prevWord := -1
	for _, u := range units {
		if empty {
			cur.WriteString(u.text)
			curW = u.width
			empty = false
		} else {
			jw := 0
			if u.word != prevWord {
				jw = 1
			}
			if curW+jw+u.width <= width {
				if jw == 1 {
					cur.WriteByte(' ')
				}
				cur.WriteString(u.text)
				curW += jw + u.width
			} else {
				lines = append(lines, cur.String())
				cur.Reset()
				cur.WriteString(u.text)
				curW = u.width
			}
		}
		prevWord = u.word
	}
	lines = append(lines, cur.String())
	return lines
}
