package solution

import (
	"context"
	"errors"
	"sync"
)

var ErrBadLimit = errors.New("parmap: limit must be positive")

func Map[T, R any](ctx context.Context, in []T, limit int, f func(context.Context, T) (R, error)) ([]R, error) {
	if limit <= 0 {
		return nil, ErrBadLimit
	}
	if len(in) == 0 {
		return []R{}, nil
	}
	if ctx.Err() != nil {
		return nil, ctx.Err()
	}

	workCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	type task struct {
		idx int
		val T
	}

	results := make([]R, len(in))
	tasks := make(chan task)
	ack := make(chan bool)
	maxWorkers := min(limit, len(in))
	workers := 0

	var (
		wg       sync.WaitGroup
		errOnce  sync.Once
		firstErr error
	)

	spawnWorker := func() {
		workers++
		wg.Add(1)
		go func() {
			defer wg.Done()
			for t := range tasks {
				if workCtx.Err() != nil {
					ack <- false
					return
				}
				ack <- true

				res, err := f(workCtx, t.val)
				if err != nil {
					errOnce.Do(func() {
						firstErr = err
						cancel()
					})
					return
				}
				results[t.idx] = res
			}
		}()
	}

	started := 0
loop:
	for i, v := range in {
		if workCtx.Err() != nil {
			break
		}
		t := task{idx: i, val: v}
		select {
		case <-workCtx.Done():
			break loop
		case tasks <- t:
		default:
			if workers < maxWorkers {
				spawnWorker()
			}
			select {
			case <-workCtx.Done():
				break loop
			case tasks <- t:
			}
		}
		if !<-ack {
			break
		}
		started++
	}

	close(tasks)
	wg.Wait()

	if firstErr != nil {
		return nil, firstErr
	}
	if started < len(in) {
		return nil, ctx.Err()
	}
	return results, nil
}
