package solution

import (
	"math"
	"sync"
	"time"
)

const maxRefillSpan = time.Duration(1 << 61)

type Limiter struct {
	mu         sync.Mutex
	rate       float64
	burst      int
	now        func() time.Time
	baseTokens float64
	baseTime   time.Time
	watermark  time.Time
}

func New(rate float64, burst int, now func() time.Time) *Limiter {
	t := now()
	return &Limiter{
		rate:       rate,
		burst:      burst,
		now:        now,
		baseTokens: float64(burst),
		baseTime:   t,
		watermark:  t,
	}
}

func (l *Limiter) refill(t time.Time) float64 {
	if t.After(l.watermark) {
		l.watermark = t
	}
	span := l.watermark.Sub(l.baseTime)
	if span <= 0 {
		return l.baseTokens
	}
	tokens := l.baseTokens + l.rate*span.Seconds()
	if tokens >= float64(l.burst) {
		tokens = float64(l.burst)
		l.baseTokens = tokens
		l.baseTime = l.watermark
	} else if span >= maxRefillSpan {
		l.baseTokens = tokens
		l.baseTime = l.watermark
	}
	return tokens
}

func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

func (l *Limiter) AllowN(n int) bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	tokens := l.refill(l.now())
	if n > l.burst || tokens < float64(n) {
		return false
	}
	l.baseTokens = tokens - float64(n)
	l.baseTime = l.watermark
	return true
}

func (l *Limiter) Delay(n int) time.Duration {
	l.mu.Lock()
	defer l.mu.Unlock()

	tokens := l.refill(l.now())
	if n > l.burst {
		return time.Duration(-1)
	}
	if tokens >= float64(n) {
		return 0
	}
	missing := float64(n) - tokens
	nanos := math.Ceil((missing * float64(time.Second)) / l.rate)
	if nanos >= float64(math.MaxInt64) {
		return time.Duration(math.MaxInt64)
	}
	if nanos < 1 {
		return 1
	}
	return time.Duration(nanos)
}
