package solution

import (
	"strings"
	"unicode/utf8"
)

func Wrap(s string, width int) []string {
	out := make([]string, 0, strings.Count(s, "\n")+1)
	var line strings.Builder

	for para := range strings.SplitSeq(s, "\n") {
		line.Reset()
		lineWidth := 0

		addUnit := func(unit string, unitWidth int, firstInWord bool) {
			if lineWidth == 0 {
				line.WriteString(unit)
				lineWidth = unitWidth
				return
			}
			joinerWidth := 0
			if firstInWord {
				joinerWidth = 1
			}
			if unitWidth <= width-lineWidth-joinerWidth {
				if firstInWord {
					line.WriteByte(' ')
				}
				line.WriteString(unit)
				lineWidth += joinerWidth + unitWidth
			} else {
				out = append(out, line.String())
				line.Reset()
				line.WriteString(unit)
				lineWidth = unitWidth
			}
		}

		n := len(para)
		for i := 0; i < n; {
			for i < n && para[i] == ' ' {
				i++
			}
			if i >= n {
				break
			}
			wordStart := i
			for i < n && para[i] != ' ' {
				i++
			}
			word := para[wordStart:i]

			firstInWord := true
			narrowStart := 0
			narrowRunes := 0
			for j := 0; j < len(word); {
				r, size := utf8.DecodeRuneInString(word[j:])
				if isWide(r) {
					if narrowRunes > 0 {
						addUnit(word[narrowStart:j], narrowRunes, firstInWord)
						firstInWord = false
						narrowRunes = 0
					}
					addUnit(word[j:j+size], 2, firstInWord)
					firstInWord = false
					j += size
					narrowStart = j
				} else {
					if narrowRunes == 0 {
						narrowStart = j
					}
					narrowRunes++
					j += size
					if narrowRunes == width {
						addUnit(word[narrowStart:j], narrowRunes, firstInWord)
						firstInWord = false
						narrowRunes = 0
						narrowStart = j
					}
				}
			}
			if narrowRunes > 0 {
				addUnit(word[narrowStart:], narrowRunes, firstInWord)
			}
		}

		if lineWidth > 0 {
			out = append(out, line.String())
		} else {
			out = append(out, "")
		}
	}

	return out
}

func isWide(r rune) bool {
	if r < 0x1100 {
		return false
	}
	return r <= 0x115F ||
		(r >= 0x2E80 && r <= 0xA4CF) ||
		(r >= 0xAC00 && r <= 0xD7A3) ||
		(r >= 0xF900 && r <= 0xFAFF) ||
		(r >= 0xFE30 && r <= 0xFE4F) ||
		(r >= 0xFF00 && r <= 0xFF60) ||
		(r >= 0xFFE0 && r <= 0xFFE6) ||
		(r >= 0x20000 && r <= 0x3FFFD)
}
