```go
package solution

import (
	"slices"
	"strings"
)

type CycleError struct {
	Cycle []string
}

func (e *CycleError) Error() string {
	if e == nil || len(e.Cycle) == 0 {
		return "dependency cycle"
	}
	var b strings.Builder
	b.WriteString("dependency cycle: ")
	for i, node := range e.Cycle {
		if i > 0 {
			b.WriteString(" -> ")
		}
		b.WriteString(node)
	}
	b.WriteString(" -> ")
	b.WriteString(e.Cycle[0])
	return b.String()
}

func Order(deps map[string][]string) ([]string, error) {
	if len(deps) == 0 {
		return []string{}, nil
	}

	nodeSet := make(map[string]struct{}, len(deps))
	for u, ds := range deps {
		nodeSet[u] = struct{}{}
		for _, d := range ds {
			nodeSet[d] = struct{}{}
		}
	}

	n := len(nodeSet)
	nodes := make([]string, 0, n)
	for name := range nodeSet {
		nodes = append(nodes, name)
	}
	slices.Sort(nodes)

	idOf := make(map[string]int, n)
	for i, name := range nodes {
		idOf[name] = i
	}

	adj := make([][]int, n)
	rev := make([][]int, n)
	hasSelfLoop := make([]bool, n)
	inDeg := make([]int, n)

	for uName, ds := range deps {
		if len(ds) == 0 {
			continue
		}
		u := idOf[uName]
		list := make([]int, len(ds))
		for i, dName := range ds {
			list[i] = idOf[dName]
		}
		slices.Sort(list)
		list = slices.Compact(list)
		adj[u] = list
		inDeg[u] = len(list)
		for _, v := range list {
			if v == u {
				hasSelfLoop[u] = true
			}
			rev[v] = append(rev[v], u)
		}
	}

	var ready intMinHeap
	for i := 0; i < n; i++ {
		if inDeg[i] == 0 {
			ready.push(i)
		}
	}

	order := make([]string, 0, n)
	for len(ready) > 0 {
		v := ready.pop()
		order = append(order, nodes[v])
		for _, u := range rev[v] {
			inDeg[u]--
			if inDeg[u] == 0 {
				ready.push(u)
			}
		}
	}

	if len(order) == n {
		return order, nil
	}

	cycleIDs := findCanonicalCycle(n, adj, hasSelfLoop)
	cycle := make([]string, len(cycleIDs))
	for i, id := range cycleIDs {
		cycle[i] = nodes[id]
	}
	return nil, &CycleError{Cycle: cycle}
}

func findCanonicalCycle(n int, adj [][]int, hasSelfLoop []bool) []int {
	// Iterative Tarjan's strongly connected components algorithm.
	type frame struct {
		u  int
		ei int
	}

	disc := make([]int, n)
	low := make([]int, n)
	onStack := make([]bool, n)
	compID := make([]int, n)
	var compSize []int
	tarjanStack := make([]int, 0, n)
	callStack := make([]frame, 0, n)
	index := 0

	for start := 0; start < n; start++ {
		if disc[start] != 0 {
			continue
		}
		index++
		disc[start] = index
		low[start] = index
		tarjanStack = append(tarjanStack, start)
		onStack[start] = true
		callStack = append(callStack, frame{u: start, ei: 0})

		for len(callStack) > 0 {
			top := &callStack[len(callStack)-1]
			u := top.u
			if top.ei < len(adj[u]) {
				v := adj[u][top.ei]
				top.ei++
				if disc[v] == 0 {
					index++
					disc[v] = index
					low[v] = index
					tarjanStack = append(tarjanStack, v)
					onStack[v] = true
					callStack = append(callStack, frame{u: v, ei: 0})
				} else if onStack[v] && disc[v] < low[u] {
					low[u] = disc[v]
				}
			} else {
				callStack = callStack[:len(callStack)-1]
				if len(callStack) > 0 {
					parent := callStack[len(callStack)-1].u
					if low[u] < low[parent] {
						low[parent] = low[u]
					}
				}
				if low[u] == disc[u] {
					cid := len(compSize)
					size := 0
					for {
						w := tarjanStack[len(tarjanStack)-1]
						tarjanStack = tarjanStack[:len(tarjanStack)-1]
						onStack[w] = false
						compID[w] = cid
						size++
						if w == u {
							break
						}
					}
					compSize = append(compSize, size)
				}
			}
		}
	}

	// Find n0: lexicographically smallest node that lies on any cycle.
	n0 := -1
	for i := 0; i < n; i++ {
		if hasSelfLoop[i] || compSize[compID[i]] >= 2 {
			n0 = i
			break
		}
	}

	if hasSelfLoop[n0] {
		return []int{n0}
	}

	// Greedily build the lexicographically smallest simple cycle starting at n0.
	// Maintain a witness path w = [n0, ..., last] where w[k] -> w[k-1] -> ... -> n0
	// avoids all forbidden vertices.
	n0Comp := compID[n0]
	dead := make([]bool, n)
	for i := 0; i < n; i++ {
		if compID[i] != n0Comp {
			dead[i] = true
		}
	}

	forbidden := make([]bool, n)
	posInW := make([]int, n)
	for i := range posInW {
		posInW[i] = -1
	}
	w := []int{n0}
	posInW[n0] = 0

	vis := make([]int, n)
	parent := make([]int, n)
	queue := make([]int, 0)
	stamp := 0

	cycle := []int{n0}
	curr := n0

	for {
		if _, ok := slices.BinarySearch(adj[curr], n0); ok {
			return cycle
		}

		next := -1
		for _, x := range adj[curr] {
			if forbidden[x] || dead[x] {
				continue
			}
			if posInW[x] != -1 {
				cut := posInW[x] + 1
				for i := cut; i < len(w); i++ {
					posInW[w[i]] = -1
				}
				w = w[:cut]
				next = x
				break
			}

			stamp++
			queue = queue[:0]
			queue = append(queue, x)
			vis[x] = stamp
			parent[x] = -1

			target := -1
			hitFrom := -1
			for head := 0; head < len(queue) && target == -1; head++ {
				u := queue[head]
				for _, v := range adj[u] {
					if forbidden[v] || dead[v] {
						continue
					}
					if posInW[v] != -1 {
						target = v
						hitFrom = u
						break
					}
					if vis[v] != stamp {
						vis[v] = stamp
						parent[v] = u
						queue = append(queue, v)
					}
				}
			}

			if target == -1 {
				for _, v := range queue {
					dead[v] = true
				}
				continue
			}

			cut := posInW[target] + 1
			for i := cut; i < len(w); i++ {
				posInW[w[i]] = -1
			}
			w = w[:cut]
			for cur := hitFrom; cur != -1; cur = parent[cur] {
				posInW[cur] = len(w)
				w = append(w, cur)
			}
			next = x
			break
		}

		cycle = append(cycle, next)
		curr = next
		posInW[curr] = -1
		w = w[:len(w)-1]
		forbidden[curr] = true
	}
}

type intMinHeap []int

func (h *intMinHeap) push(x int) {
	*h = append(*h, x)
	i := len(*h) - 1
	for i > 0 {
		p := (i - 1) / 2
		if (*h)[p] <= (*h)[i] {
			break
		}
		(*h)[p], (*h)[i] = (*h)[i], (*h)[p]
		i = p
	}
}

func (h *intMinHeap) pop() int {
	old := *h
	res := old[0]
	last := len(old) - 1
	old[0] = old[last]
	*h = old[:last]
	n := last
	i := 0
	for {
		l := 2*i + 1
		if l >= n {
			break
		}
		smallest := l
		if r := l + 1; r < n && (*h)[r] < (*h)[l] {
			smallest = r
		}
		if (*h)[i] <= (*h)[smallest] {
			break
		}
		(*h)[i], (*h)[smallest] = (*h)[smallest], (*h)[i]
		i = smallest
	}
	return res
}
