package solution

import (
	"container/list"
	"time"
)

type entry struct {
	key    string
	value  string
	expiry time.Time
}

type Cache struct {
	capacity int
	ttl      time.Duration
	now      func() time.Time
	list     *list.List
	items    map[string]*list.Element
}

func New(capacity int, ttl time.Duration, now func() time.Time) *Cache {
	return &Cache{
		capacity: capacity,
		ttl:      ttl,
		now:      now,
		list:     list.New(),
		items:    make(map[string]*list.Element, capacity),
	}
}

func (c *Cache) Get(k string) (string, bool) {
	elem, ok := c.items[k]
	if !ok {
		return "", false
	}
	ent := elem.Value.(*entry)
	if !c.now().Before(ent.expiry) {
		c.removeElement(elem)
		return "", false
	}
	c.list.MoveToFront(elem)
	return ent.value, true
}

func (c *Cache) Put(k, v string) {
	now := c.now()
	exp := now.Add(c.ttl)

	if elem, ok := c.items[k]; ok {
		ent := elem.Value.(*entry)
		if now.Before(ent.expiry) {
			ent.value = v
			ent.expiry = exp
			c.list.MoveToFront(elem)
			return
		}
		c.removeElement(elem)
	}

	if c.list.Len() == c.capacity {
		c.removeExpired(now)
		if c.list.Len() == c.capacity {
			c.removeElement(c.list.Back())
		}
	}

	elem := c.list.PushFront(&entry{
		key:    k,
		value:  v,
		expiry: exp,
	})
	c.items[k] = elem
}

func (c *Cache) Len() int {
	now := c.now()
	count := 0
	for elem := c.list.Front(); elem != nil; elem = elem.Next() {
		if now.Before(elem.Value.(*entry).expiry) {
			count++
		}
	}
	return count
}

func (c *Cache) removeExpired(now time.Time) {
	for elem := c.list.Front(); elem != nil; {
		next := elem.Next()
		if !now.Before(elem.Value.(*entry).expiry) {
			c.removeElement(elem)
		}
		elem = next
	}
}

func (c *Cache) removeElement(elem *list.Element) {
	if elem == nil {
		return
	}
	ent := elem.Value.(*entry)
	delete(c.items, ent.key)
	c.list.Remove(elem)
}
