import (
	"fmt"
	"strings"
)

type ParseError struct {
	Line int
}

func (e *ParseError) Error() string {
	return fmt.Sprintf("csv parse error on line %d", e.Line)
}

func Parse(s string) ([][]string, error) {
	if len(s) == 0 {
		return nil, nil
	}

	var records [][]string
	i := 0
	line := 1

	for i < len(s) {
		var record []string
		for {
			var field string
			if i < len(s) && s[i] == '"' {
				startLine := line
				i++ // consume opening quote
				var b strings.Builder
				for {
					if i >= len(s) {
						return nil, &ParseError{Line: startLine}
					}
					if s[i] == '"' {
						if i+1 < len(s) && s[i+1] == '"' {
							b.WriteByte('"')
							i += 2
						} else {
							i++ // consume closing quote
							break
						}
					} else {
						if s[i] == '\n' {
							line++
						}
						b.WriteByte(s[i])
						i++
					}
				}
				field = b.String()

				if i < len(s) && s[i] != ',' && s[i] != '\n' && !(s[i] == '\r' && i+1 < len(s) && s[i+1] == '\n') {
					return nil, &ParseError{Line: line}
				}
			} else {
				start := i
				for i < len(s) {
					c := s[i]
					if c == ',' || c == '\n' || (c == '\r' && i+1 < len(s) && s[i+1] == '\n') {
						break
					}
					if c == '"' {
						return nil, &ParseError{Line: line}
					}
					i++
				}
				field = s[start:i]
			}

			record = append(record, field)

			if i >= len(s) {
				break
			}
			if s[i] == ',' {
				i++
				continue
			}
			if s[i] == '\n' {
				i++
				line++
				break
			}
			if s[i] == '\r' && i+1 < len(s) && s[i+1] == '\n' {
				i += 2
				line++
				break
			}
		}
		records = append(records, record)
	}

	return records, nil
}
