import (
	"slices"
	"sort"
)

type Set struct {
	intervals [][2]int
}

func (s *Set) Add(lo, hi int) {
	if lo >= hi {
		return
	}

	start := sort.Search(len(s.intervals), func(i int) bool {
		return s.intervals[i][1] >= lo
	})

	end := start
	for end < len(s.intervals) && s.intervals[end][0] <= hi {
		end++
	}

	if start < end {
		lo = min(lo, s.intervals[start][0])
		hi = max(hi, s.intervals[end-1][1])
	}

	s.intervals = slices.Replace(s.intervals, start, end, [2]int{lo, hi})
}

func (s *Set) Remove(lo, hi int) {
	if lo >= hi {
		return
	}

	start := sort.Search(len(s.intervals), func(i int) bool {
		return s.intervals[i][1] > lo
	})

	end := start
	for end < len(s.intervals) && s.intervals[end][0] < hi {
		end++
	}

	if start == end {
		return
	}

	var repl [2][2]int
	n := 0
	if s.intervals[start][0] < lo {
		repl[n] = [2]int{s.intervals[start][0], lo}
		n++
	}
	if s.intervals[end-1][1] > hi {
		repl[n] = [2]int{hi, s.intervals[end-1][1]}
		n++
	}

	s.intervals = slices.Replace(s.intervals, start, end, repl[:n]...)
}

func (s *Set) Contains(x int) bool {
	i := sort.Search(len(s.intervals), func(i int) bool {
		return s.intervals[i][1] > x
	})
	return i < len(s.intervals) && s.intervals[i][0] <= x
}

func (s *Set) Intervals() [][2]int {
	return slices.Clone(s.intervals)
}
