package solution

import "errors"

var errInvalidDate = errors.New("invalid date")

var daysInMonth = [13]int{0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31}

func isLeap(y int) bool {
	return y%4 == 0 && (y%100 != 0 || y%400 == 0)
}

func isDigit(b byte) bool {
	return b >= '0' && b <= '9'
}

func daysFromCivil(y, m, d int) int {
	if m <= 2 {
		y--
	}
	era := y / 400
	if y < 0 {
		era = (y - 399) / 400
	}
	yoe := y - era*400
	mp := m - 3
	if m <= 2 {
		mp = m + 9
	}
	doy := (153*mp+2)/5 + d - 1
	doe := yoe*365 + yoe/4 - yoe/100 + doy
	return era*146097 + doe - 719468
}

func parseDate(s string) (int, error) {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return 0, errInvalidDate
	}
	if !isDigit(s[0]) || !isDigit(s[1]) || !isDigit(s[2]) || !isDigit(s[3]) ||
		!isDigit(s[5]) || !isDigit(s[6]) || !isDigit(s[8]) || !isDigit(s[9]) {
		return 0, errInvalidDate
	}
	y := int(s[0]-'0')*1000 + int(s[1]-'0')*100 + int(s[2]-'0')*10 + int(s[3]-'0')
	m := int(s[5]-'0')*10 + int(s[6]-'0')
	d := int(s[8]-'0')*10 + int(s[9]-'0')

	if m < 1 || m > 12 {
		return 0, errInvalidDate
	}
	maxDay := daysInMonth[m]
	if m == 2 && isLeap(y) {
		maxDay = 29
	}
	if d < 1 || d > maxDay {
		return 0, errInvalidDate
	}

	return daysFromCivil(y, m, d), nil
}

// weekday returns 0 for Monday through 6 for Sunday.
func weekday(day int) int {
	w := (day + 3) % 7
	if w < 0 {
		w += 7
	}
	return w
}

// Count returns the number of business days in [from, to) excluding holidays.
func Count(from, to string, holidays []string) (int, error) {
	start, err := parseDate(from)
	if err != nil {
		return 0, err
	}
	end, err := parseDate(to)
	if err != nil {
		return 0, err
	}

	sign := 1
	if end < start {
		start, end = end, start
		sign = -1
	}

	total := end - start
	count := (total / 7) * 5
	rem := total % 7
	for i := range rem {
		if weekday(start+i) < 5 {
			count++
		}
	}

	var seen map[int]struct{}
	for _, h := range holidays {
		hd, err := parseDate(h)
		if err != nil {
			return 0, err
		}
		if hd >= start && hd < end && weekday(hd) < 5 {
			if seen == nil {
				seen = make(map[int]struct{})
			}
			if _, ok := seen[hd]; !ok {
				seen[hd] = struct{}{}
				count--
			}
		}
	}

	return sign * count, nil
}
