import (
	"context"
	"errors"
	"sync"
)

var ErrBadLimit = errors.New("parmap: limit must be positive")

func Map[T, R any](ctx context.Context, in []T, limit int, f func(context.Context, T) (R, error)) ([]R, error) {
	if limit <= 0 {
		return nil, ErrBadLimit
	}
	if len(in) == 0 {
		return make([]R, 0), nil
	}

	workCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	results := make([]R, len(in))
	sem := make(chan struct{}, limit)

	var (
		wg       sync.WaitGroup
		errOnce  sync.Once
		firstErr error
	)

	allStarted := true

loop:
	for i := range in {
		if workCtx.Err() != nil {
			allStarted = false
			break
		}

		select {
		case <-workCtx.Done():
			allStarted = false
			break loop
		case sem <- struct{}{}:
		}

		if workCtx.Err() != nil {
			<-sem
			allStarted = false
			break
		}

		started := make(chan struct{})
		wg.Add(1)
		go func(idx int, item T) {
			defer wg.Done()
			defer func() { <-sem }()

			close(started)
			res, err := f(workCtx, item)
			if err != nil {
				errOnce.Do(func() {
					firstErr = err
					cancel()
				})
				return
			}
			results[idx] = res
		}(i, in[i])

		<-started
	}

	wg.Wait()

	if firstErr != nil {
		return nil, firstErr
	}
	if !allStarted {
		return nil, ctx.Err()
	}
	return results, nil
}
