package solution

import (
	"math"
	"sync"
	"time"
)

type Limiter struct {
	mu        sync.Mutex
	rate      float64
	burst     int
	now       func() time.Time
	tokens    float64
	watermark time.Time
}

func New(rate float64, burst int, now func() time.Time) *Limiter {
	return &Limiter{
		rate:      rate,
		burst:     burst,
		now:       now,
		tokens:    float64(burst),
		watermark: now(),
	}
}

func (l *Limiter) refill() {
	t := l.now()
	if t.After(l.watermark) {
		elapsed := t.Sub(l.watermark).Seconds()
		l.tokens += elapsed * l.rate
		if maxTokens := float64(l.burst); l.tokens > maxTokens {
			l.tokens = maxTokens
		}
		l.watermark = t
	}
}

func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

func (l *Limiter) AllowN(n int) bool {
	l.mu.Lock()
	defer l.mu.Unlock()

	l.refill()
	if n > l.burst {
		return false
	}
	needed := float64(n)
	if l.tokens < needed {
		return false
	}
	l.tokens -= needed
	return true
}

func (l *Limiter) Delay(n int) time.Duration {
	l.mu.Lock()
	defer l.mu.Unlock()

	l.refill()
	if n > l.burst {
		return time.Duration(-1)
	}
	needed := float64(n)
	if l.tokens >= needed {
		return 0
	}
	missing := needed - l.tokens
	nanos := math.Ceil((missing / l.rate) * float64(time.Second))
	if nanos >= float64(math.MaxInt64) {
		return time.Duration(math.MaxInt64)
	}
	return time.Duration(nanos)
}
