package solution

import (
	"errors"
	"fmt"
	"math"
	"strconv"
)

func Eval(s string) (float64, error) {
	p := parser{s: s}
	val, err := p.parseExpr()
	if err != nil {
		return 0, err
	}
	p.skipWhitespace()
	if p.pos != len(p.s) {
		return 0, fmt.Errorf("unexpected character %q at position %d", p.s[p.pos], p.pos)
	}
	return val, nil
}

type parser struct {
	s   string
	pos int
}

func (p *parser) skipWhitespace() {
	for p.pos < len(p.s) {
		switch p.s[p.pos] {
		case ' ', '\t', '\n', '\r':
			p.pos++
		default:
			return
		}
	}
}

func (p *parser) parseExpr() (float64, error) {
	left, err := p.parseTerm()
	if err != nil {
		return 0, err
	}
	for {
		p.skipWhitespace()
		if p.pos >= len(p.s) {
			break
		}
		op := p.s[p.pos]
		if op != '+' && op != '-' {
			break
		}
		p.pos++
		right, err := p.parseTerm()
		if err != nil {
			return 0, err
		}
		if op == '+' {
			left += right
		} else {
			left -= right
		}
	}
	return left, nil
}

func (p *parser) parseTerm() (float64, error) {
	left, err := p.parseUnary()
	if err != nil {
		return 0, err
	}
	for {
		p.skipWhitespace()
		if p.pos >= len(p.s) {
			break
		}
		op := p.s[p.pos]
		if op != '*' && op != '/' {
			break
		}
		p.pos++
		right, err := p.parseUnary()
		if err != nil {
			return 0, err
		}
		if op == '*' {
			left *= right
		} else {
			if right == 0 {
				return 0, errors.New("division by zero")
			}
			left /= right
		}
	}
	return left, nil
}

func (p *parser) parseUnary() (float64, error) {
	p.skipWhitespace()
	if p.pos < len(p.s) {
		switch p.s[p.pos] {
		case '+':
			p.pos++
			return p.parseUnary()
		case '-':
			p.pos++
			val, err := p.parseUnary()
			if err != nil {
				return 0, err
			}
			return -val, nil
		}
	}
	return p.parsePower()
}

func (p *parser) parsePower() (float64, error) {
	base, err := p.parsePrimary()
	if err != nil {
		return 0, err
	}
	p.skipWhitespace()
	if p.pos < len(p.s) && p.s[p.pos] == '^' {
		p.pos++
		exp, err := p.parseUnary()
		if err != nil {
			return 0, err
		}
		return math.Pow(base, exp), nil
	}
	return base, nil
}

func (p *parser) parsePrimary() (float64, error) {
	p.skipWhitespace()
	if p.pos >= len(p.s) {
		return 0, errors.New("unexpected end of input")
	}
	ch := p.s[p.pos]
	if ch == '(' {
		p.pos++
		val, err := p.parseExpr()
		if err != nil {
			return 0, err
		}
		p.skipWhitespace()
		if p.pos >= len(p.s) || p.s[p.pos] != ')' {
			return 0, errors.New("missing closing parenthesis")
		}
		p.pos++
		return val, nil
	}
	if isDigit(ch) || ch == '.' {
		return p.parseNumber()
	}
	return 0, fmt.Errorf("unexpected character %q at position %d", ch, p.pos)
}

func (p *parser) parseNumber() (float64, error) {
	start := p.pos
	hasDigits := false
	for p.pos < len(p.s) && isDigit(p.s[p.pos]) {
		p.pos++
		hasDigits = true
	}
	if p.pos < len(p.s) && p.s[p.pos] == '.' {
		p.pos++
		for p.pos < len(p.s) && isDigit(p.s[p.pos]) {
			p.pos++
			hasDigits = true
		}
	}
	if !hasDigits {
		return 0, fmt.Errorf("invalid number at position %d", start)
	}
	return strconv.ParseFloat(p.s[start:p.pos], 64)
}

func isDigit(b byte) bool {
	return b >= '0' && b <= '9'
}
