package solution

import (
	"strings"
	"unicode/utf8"
)

func isWide(r rune) bool {
	return (r >= 0x1100 && r <= 0x115F) ||
		(r >= 0x2E80 && r <= 0xA4CF) ||
		(r >= 0xAC00 && r <= 0xD7A3) ||
		(r >= 0xF900 && r <= 0xFAFF) ||
		(r >= 0xFE30 && r <= 0xFE4F) ||
		(r >= 0xFF00 && r <= 0xFF60) ||
		(r >= 0xFFE0 && r <= 0xFFE6) ||
		(r >= 0x20000 && r <= 0x3FFFD)
}

func Wrap(s string, width int) []string {
	paragraphs := strings.Split(s, "\n")
	out := make([]string, 0, len(paragraphs))
	for _, p := range paragraphs {
		out = wrapParagraph(p, width, out)
	}
	return out
}

func wrapParagraph(p string, width int, out []string) []string {
	var line strings.Builder
	lineWidth := 0
	hasUnit := false

	appendUnit := func(u string, uWidth int, newWord bool) {
		if !hasUnit {
			line.WriteString(u)
			lineWidth = uWidth
			hasUnit = true
			return
		}
		joiner := 0
		if newWord {
			joiner = 1
		}
		if lineWidth+joiner+uWidth <= width {
			if newWord {
				line.WriteByte(' ')
			}
			line.WriteString(u)
			lineWidth += joiner + uWidth
		} else {
			out = append(out, line.String())
			line.Reset()
			line.WriteString(u)
			lineWidth = uWidth
		}
	}

	i := 0
	n := len(p)
	for i < n {
		for i < n && p[i] == ' ' {
			i++
		}
		if i >= n {
			break
		}
		newWord := true
		for i < n && p[i] != ' ' {
			r, size := utf8.DecodeRuneInString(p[i:])
			if isWide(r) {
				appendUnit(p[i:i+size], 2, newWord)
				newWord = false
				i += size
			} else {
				chunkStart := i
				chunkRunes := 0
				for i < n && p[i] != ' ' {
					r2, size2 := utf8.DecodeRuneInString(p[i:])
					if isWide(r2) {
						break
					}
					i += size2
					chunkRunes++
					if chunkRunes == width {
						appendUnit(p[chunkStart:i], chunkRunes, newWord)
						newWord = false
						chunkStart = i
						chunkRunes = 0
					}
				}
				if chunkRunes > 0 {
					appendUnit(p[chunkStart:i], chunkRunes, newWord)
					newWord = false
				}
			}
		}
	}

	if !hasUnit {
		return append(out, "")
	}
	return append(out, line.String())
}
