package solution

import (
	"cmp"
	"errors"
	"strings"
)

var errInvalidVersion = errors.New("invalid semantic version")

type preIdent struct {
	raw     string
	numeric bool
}

type semver struct {
	major string
	minor string
	patch string
	pre   []preIdent
}

func Compare(a, b string) (int, error) {
	va, err := parse(a)
	if err != nil {
		return 0, err
	}
	vb, err := parse(b)
	if err != nil {
		return 0, err
	}

	if c := compareNumeric(va.major, vb.major); c != 0 {
		return c, nil
	}
	if c := compareNumeric(va.minor, vb.minor); c != 0 {
		return c, nil
	}
	if c := compareNumeric(va.patch, vb.patch); c != 0 {
		return c, nil
	}

	if len(va.pre) == 0 && len(vb.pre) == 0 {
		return 0, nil
	}
	if len(va.pre) == 0 {
		return 1, nil
	}
	if len(vb.pre) == 0 {
		return -1, nil
	}

	for i := 0; i < len(va.pre) && i < len(vb.pre); i++ {
		pa, pb := va.pre[i], vb.pre[i]
		switch {
		case pa.numeric && pb.numeric:
			if c := compareNumeric(pa.raw, pb.raw); c != 0 {
				return c, nil
			}
		case pa.numeric:
			return -1, nil
		case pb.numeric:
			return 1, nil
		default:
			if c := strings.Compare(pa.raw, pb.raw); c != 0 {
				return c, nil
			}
		}
	}

	return cmp.Compare(len(va.pre), len(vb.pre)), nil
}

func parse(s string) (semver, error) {
	if strings.HasPrefix(s, "v") {
		s = s[1:]
	}

	var v semver

	if coreAndPre, build, hasBuild := strings.Cut(s, "+"); hasBuild {
		if err := validateBuild(build); err != nil {
			return semver{}, err
		}
		s = coreAndPre
	}

	if core, pre, hasPre := strings.Cut(s, "-"); hasPre {
		parsedPre, err := parsePrerelease(pre)
		if err != nil {
			return semver{}, err
		}
		v.pre = parsedPre
		s = core
	}

	major, rest, ok := strings.Cut(s, ".")
	if !ok {
		return semver{}, errInvalidVersion
	}
	minor, patch, ok := strings.Cut(rest, ".")
	if !ok {
		return semver{}, errInvalidVersion
	}
	if !isValidNumeric(major) || !isValidNumeric(minor) || !isValidNumeric(patch) {
		return semver{}, errInvalidVersion
	}

	v.major = major
	v.minor = minor
	v.patch = patch
	return v, nil
}

func isValidNumeric(s string) bool {
	if len(s) == 0 {
		return false
	}
	if len(s) > 1 && s[0] == '0' {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func isIdentChar(c byte) bool {
	return (c >= '0' && c <= '9') ||
		(c >= 'A' && c <= 'Z') ||
		(c >= 'a' && c <= 'z') ||
		c == '-'
}

func validateBuild(s string) error {
	if len(s) == 0 {
		return errInvalidVersion
	}
	for {
		part, rest, hasMore := strings.Cut(s, ".")
		if len(part) == 0 {
			return errInvalidVersion
		}
		for i := 0; i < len(part); i++ {
			if !isIdentChar(part[i]) {
				return errInvalidVersion
			}
		}
		if !hasMore {
			return nil
		}
		s = rest
	}
}

func parsePrerelease(s string) ([]preIdent, error) {
	if len(s) == 0 {
		return nil, errInvalidVersion
	}
	var out []preIdent
	for {
		part, rest, hasMore := strings.Cut(s, ".")
		if len(part) == 0 {
			return nil, errInvalidVersion
		}
		allDigits := true
		for i := 0; i < len(part); i++ {
			c := part[i]
			if !isIdentChar(c) {
				return nil, errInvalidVersion
			}
			if c < '0' || c > '9' {
				allDigits = false
			}
		}
		if allDigits && len(part) > 1 && part[0] == '0' {
			return nil, errInvalidVersion
		}
		out = append(out, preIdent{raw: part, numeric: allDigits})
		if !hasMore {
			return out, nil
		}
		s = rest
	}
}

func compareNumeric(a, b string) int {
	if c := cmp.Compare(len(a), len(b)); c != 0 {
		return c
	}
	return strings.Compare(a, b)
}
