package solution

import (
	"slices"
	"strings"
)

type CycleError struct {
	Cycle []string
}

func (e *CycleError) Error() string {
	if e == nil || len(e.Cycle) == 0 {
		return "dependency cycle detected"
	}
	return "dependency cycle: " + strings.Join(e.Cycle, " -> ") + " -> " + e.Cycle[0]
}

func Order(deps map[string][]string) ([]string, error) {
	if len(deps) == 0 {
		return []string{}, nil
	}

	// Collect all distinct node names.
	nodeSet := make(map[string]struct{}, len(deps))
	for a, ds := range deps {
		nodeSet[a] = struct{}{}
		for _, d := range ds {
			nodeSet[d] = struct{}{}
		}
	}

	n := len(nodeSet)
	names := make([]string, 0, n)
	for name := range nodeSet {
		names = append(names, name)
	}
	slices.Sort(names)

	idOf := make(map[string]int, n)
	for i, name := range names {
		idOf[name] = i
	}

	// Build deduplicated, sorted adjacency list (a -> d) and reverse adjacency list (d -> a).
	adj := make([][]int, n)
	revAdj := make([][]int, n)
	remDeps := make([]int, n)

	for a, ds := range deps {
		if len(ds) == 0 {
			continue
		}
		u := idOf[a]
		list := make([]int, len(ds))
		for i, d := range ds {
			list[i] = idOf[d]
		}
		slices.Sort(list)
		list = slices.Compact(list)
		adj[u] = list
		remDeps[u] = len(list)
		for _, v := range list {
			revAdj[v] = append(revAdj[v], u)
		}
	}

	// Kahn's algorithm picking the lexicographically smallest available node.
	var h intHeap
	for i := 0; i < n; i++ {
		if remDeps[i] == 0 {
			h.push(i)
		}
	}

	order := make([]string, 0, n)
	for len(h) > 0 {
		u := h.pop()
		order = append(order, names[u])
		for _, depOfU := range revAdj[u] {
			remDeps[depOfU]--
			if remDeps[depOfU] == 0 {
				h.push(depOfU)
			}
		}
	}

	if len(order) == n {
		return order, nil
	}

	// Cycle exists: find all nodes on any cycle using Tarjan's SCC algorithm.
	index := make([]int, n)
	for i := range index {
		index[i] = -1
	}
	lowlink := make([]int, n)
	onStack := make([]bool, n)
	stack := make([]int, 0, n)
	inCycle := make([]bool, n)
	curIdx := 0

	var strongConnect func(v int)
	strongConnect = func(v int) {
		index[v] = curIdx
		lowlink[v] = curIdx
		curIdx++
		stack = append(stack, v)
		onStack[v] = true

		for _, w := range adj[v] {
			if w == v {
				inCycle[v] = true
			}
			if index[w] == -1 {
				strongConnect(w)
				if lowlink[w] < lowlink[v] {
					lowlink[v] = lowlink[w]
				}
			} else if onStack[w] {
				if index[w] < lowlink[v] {
					lowlink[v] = index[w]
				}
			}
		}

		if lowlink[v] == index[v] {
			var comp []int
			for {
				w := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				onStack[w] = false
				comp = append(comp, w)
				if w == v {
					break
				}
			}
			if len(comp) > 1 {
				for _, w := range comp {
					inCycle[w] = true
				}
			}
		}
	}

	for v := 0; v < n; v++ {
		if index[v] == -1 {
			strongConnect(v)
		}
	}

	// n0 is the lexicographically smallest node on any cycle.
	n0 := -1
	for v := 0; v < n; v++ {
		if inCycle[v] {
			n0 = v
			break
		}
	}

	hasEdge := func(u, target int) bool {
		_, ok := slices.BinarySearch(adj[u], target)
		return ok
	}

	if hasEdge(n0, n0) {
		return nil, &CycleError{Cycle: []string{names[n0]}}
	}

	// Greedily build the lexicographically smallest simple cycle starting at n0.
	path := []int{n0}
	inPath := make([]bool, n)
	inPath[n0] = true
	blocked := make([]bool, n)
	canReach := make([]bool, n)
	queue := make([]int, 0, n)

	for {
		curr := path[len(path)-1]
		if len(path) > 1 && hasEdge(curr, n0) {
			break
		}

		clear(canReach)
		queue = queue[:0]
		queue = append(queue, n0)
		for len(queue) > 0 {
			u := queue[0]
			queue = queue[1:]
			for _, prev := range revAdj[u] {
				if prev != n0 && !blocked[prev] && !canReach[prev] {
					canReach[prev] = true
					queue = append(queue, prev)
				}
			}
		}

		next := -1
		for _, v := range adj[curr] {
			if !inPath[v] && canReach[v] {
				next = v
				break
			}
		}

		path = append(path, next)
		inPath[next] = true
		blocked[next] = true
	}

	cycle := make([]string, len(path))
	for i, id := range path {
		cycle[i] = names[id]
	}
	return nil, &CycleError{Cycle: cycle}
}

type intHeap []int

func (h *intHeap) push(x int) {
	*h = append(*h, x)
	i := len(*h) - 1
	for i > 0 {
		p := (i - 1) / 2
		if (*h)[p] <= (*h)[i] {
			break
		}
		(*h)[p], (*h)[i] = (*h)[i], (*h)[p]
		i = p
	}
}

func (h *intHeap) pop() int {
	old := *h
	x := old[0]
	last := len(old) - 1
	old[0] = old[last]
	*h = old[:last]
	i := 0
	for {
		l := 2*i + 1
		if l >= len(*h) {
			break
		}
		smallest := l
		if r := l + 1; r < len(*h) && (*h)[r] < (*h)[l] {
			smallest = r
		}
		if (*h)[i] <= (*h)[smallest] {
			break
		}
		(*h)[i], (*h)[smallest] = (*h)[smallest], (*h)[i]
		i = smallest
	}
	return x
}
